local config = {
  ui_story_5089_50890100_1_dialog_content = "Cuaca hari ini sangat bagus. Rasanya baik untuk berkeliling Kota Haojin sendirian setelah waktu yang lama.",
  ui_story_5089_50890100_2_dialog_content = "Tapi, aku merasa diawasi sejak aku tiba di sini...",
  ui_story_5089_50890100_3_dialog_content = "Aku tidak merasakan ada niat jahat, tapi tetap saja membuat bulu kudukku merinding... Apakah aku terlalu aneh dibanding orang lain di sini?",
  ui_story_5089_50890100_4_dialog_content = "Ehem, maafkan saya, anak muda, tapi apakah Anda utusan dari Astra?",
  ui_story_5089_50890100_5_dialog_content = "Eh, ya, itu benar. Apakah ada sesuatu yang kamu butuhkan?",
  ui_story_5089_50890100_6_dialog_content = "Ah, betapa indahnya! Saya hanya pemilik bisnis kecil, menjalankan beberapa restoran dan hotel di Kerajaan Ji.",
  ui_story_5089_50890100_7_dialog_content = "Aku diberitahu bahwa kamu suka tahu kering, dan salah satu toko ku adalah spesialis dalam membuatnya. Ini bukanlah hadiah yang berarti, tapi tolong terimalah.",
  ui_story_5089_50890100_8_dialog_content = "Jika rasa ini sesuai dengan selera kamu, cukup minta dan aku akan mengirimkan lebih banyak lagi!",
  ui_story_5089_50890100_9_dialog_content = "Hah? Kapan aku bilang aku suka tahu kering? Tunggu, aku masih tidak tahu siapa kamu—",
  ui_story_5089_50890100_10_dialog_content = "Utusan terhormat akhirnya tiba! Betapa besar kehormatannya bisa bertemu dengan Anda! Silakan, lihatlah sutera halus saya!",
  ui_story_5089_50890100_11_dialog_content = "Cepat! Ambilkan Brokat Harmoni Phoenix yang tak ternilai dari toko kita dan persembahkan kepada tamu kita!",
  ui_story_5089_50890100_12_dialog_content = "Oh, tidak, aku tidak mungkin bisa mengambil itu!",
  ui_story_5089_50890100_13_dialog_content = "Maafkan saya, tapi tuan saya telah menyiapkan makanan yang hebat untuk Anda. Kami akan merasa terhormat jika utusan dari Astra menjadi tamu kehormatan kami!",
  ui_story_5089_50890100_14_dialog_content = "Salam, Tuan! Putri tuan rumah saya akan menjadi tuan rumah pertemuan puisi di rumah kami besok, dan dia menulis undangan ini khusus untuk Anda.",
  ui_story_5089_50890100_15_dialog_content = "Siapa itu di sana? Mengapa mereka membuat keributan seperti itu?",
  ui_story_5089_50890100_16_dialog_content = "Tampaknya itu utusan dari tanah barat!",
  ui_story_5089_50890100_17_dialog_content = "Orang yang mendapatkan kasih sayang dari Gadis Naga, dan membantu meredakan banjir di Haojin serta mengalahkan naga jahat. Saya mendengar utusan itu bahkan akan segera menikah dengan pangeran mahkota!",
  ui_story_5089_50890100_18_dialog_content = "Benarkah? Mari kita lihat!",
  ui_story_5089_50890100_19_dialog_content = "Utusan! Di sini, utusan...!",
  ui_story_5089_50890100_20_dialog_content = "(Ini-Ini buruk! Aku harus keluar dari sini!)",
  ui_story_5089_50890100_21_dialog_content = "Ha... Fyuh... Akhirnya aku berhasil kembali.",
  ui_story_5089_50890100_22_dialog_content = "Aku tahu aku telah membantu mereka sebelumnya, tapi antusiasme setiap orang sepertinya sedikit berlebihan.",
  ui_story_5089_50890100_23_dialog_content = "Haruskah saya meminta Chen'ni untuk melindungi saya setiap kali saya keluar sekarang?",
  ui_story_5089_50890100_24_dialog_content = "Juga, aku cukup yakin aku mendengar salah satu dari mereka mengatakan sesuatu yang benar-benar konyol barusan.",
  ui_story_5089_50890100_25_dialog_content = "<color=#e8d9bb>Cuit-cuit!</color>",
  ui_story_5089_50890100_26_dialog_content = "Hei, ini burung mekanik yang saya kirim untuk mengirim pesan ke Xuan Ji! Mari kita lihat...",
  ui_story_5089_50890100_27_dialog_content = "Hah?",
  ui_story_5089_50890100_28_dialog_content = "Ini adalah surat yang saya kirim, tetapi belum dibuka sama sekali. Apakah surat ini tidak dapat menemukannya?",
  ui_story_5089_50890100_29_dialog_content = "Cuit.",
  ui_story_5089_50890100_30_dialog_content = "Itu aneh. Selama Festival Musim Semi, dia bilang dia akan kembali ke Kerajaan Ye untuk menangani beberapa urusan yang belum selesai.",
  ui_story_5089_50890100_31_dialog_content = "Jadi, bagaimana saya bisa berakhir di hutan gunung kuno?",
  ui_story_5089_50890100_32_dialog_content = "Sekarang jika aku pikirkan, sejak aku tiba di Longzhou, dia selalu menjaga jarak sambil menyelidiki sesuatu. Apakah mungkin...?",
  ui_story_5089_50890100_33_dialog_content = "Tuan, ada tamu di sini untuk menemui Anda.",
  ui_story_5089_50890100_34_dialog_content = "... A-Apakah orang-orang itu mengikutiku sampai ke Royal Guesthouse?!",
  ui_story_5089_50890100_35_dialog_content = "Maaf, tapi saya tidak ingin melihat mereka sekarang. Katakan saja bahwa Caelestites harus hibernasi untuk musim dingin atau semacamnya.",
  ui_story_5089_50890100_36_dialog_content = "Tapi... Bukankah musim dingin baru saja berlalu?",
  ui_story_5089_50890100_37_dialog_content = "Th-Tapi katakan saja pada mereka bahwa aku masih menyesuaikan diri dengan musim semi dan bahwa aku harus bersiap untuk hibernasi tahun depan! Tidak masalah. Cukup buat alasan saja!",
  ui_story_5089_50890100_38_dialog_content = "Tak pernah terpikir olehku bahwa akan begitu sulit untuk mendapatkan audiensi denganmu, PlayerName.",
  ui_story_5089_50890100_39_dialog_content = "D-Dantang?! Bukan, alasan itu bukan untukmu—",
  ui_story_5089_50890100_40_dialog_content = "Aku tahu.",
  ui_story_5089_50890100_41_dialog_content = "Kamu bukan lagi hanya utusan dari Astra, tetapi juga pahlawan yang berprestasi untuk Kerajaan Ji.",
  ui_story_5089_50890100_42_dialog_content = "Jalan-jalan di Haojin dipenuhi dengan desas-desus tentang pertunangan Anda yang akan datang dengan pangeran mahkota juga.",
  ui_story_5089_50890100_43_dialog_content = "Tidak heran jika pedagang Kerajaan Ji berlomba-lomba untuk menjalin hubungan baik dengan Anda.",
  ui_story_5089_50890100_44_dialog_content = "Mengapa semua orang di Haojin tahu tentang ini?! Dan tidak ada yang memiliki pertanyaan tentang itu?",
  ui_story_5089_50890100_45_dialog_content = "Bahkan rumor paling absurd sekalipun memiliki sedikit kebenaran, bukan?",
  ui_story_5089_50890100_46_dialog_content = "G-Beri aku istirahat...",
  ui_story_5089_50890100_47_dialog_content = "Ada keuntungan dalam menerima proposal dari pangeran mahkota, tahu?",
  ui_story_5089_50890100_48_dialog_content = "Dia mungkin sedikit nakal, tetapi hatinya murni dan penuh pengaguman atas kepahlawananmu selama ekuinoks musim semi.",
  ui_story_5089_50890100_49_dialog_content = "Setelah menjadi pasangan pangeran mahkota dan pindah ke istana kerajaan, tak seorang pun akan berani menyebarkan rumor tentang kamu lagi.",
  ui_story_5089_50890100_50_dialog_content = "Apakah kamu benar-benar membutuhkan sesuatu, Dantang? Atau apakah kamu benar-benar datang ke sini hanya untuk mempermainkanku?",
  ui_story_5089_50890100_51_dialog_content = "\"Mengganggu kamu\"? Apakah itu benar-benar cara kamu melihat saya, PlayerName?",
  ui_story_5089_50890100_52_dialog_content = "Tidak! Bukan itu maksudku...",
  ui_story_5089_50890100_53_dialog_content = "Heheh, aku tahu. Tak perlu gugup begitu.",
  ui_story_5089_50890100_54_dialog_content = "Namun, ada alasan mengapa saya datang ke sini hari ini... Jiu.",
  ui_story_5089_50890100_55_dialog_content = "Baik, Yang Mulia.",
  ui_story_5089_50890100_56_dialog_content = "Wah! Kamu juga di sini, Jiu? Saya sama sekali tidak melihatmu di sana!",
  ui_story_5089_50890100_57_dialog_content = "Yang Mulia memiliki hal penting untuk dibahas dengan utusan. Aku akan tetap di sisinya; sisanya dari kalian boleh pergi.",
  ui_story_5089_50890100_58_dialog_content = "Baik, Yang Mulia.",
  ui_story_5089_50890100_59_dialog_content = "Aku akan membuat teh.",
  ui_story_5089_50890100_60_dialog_content = "T-Tidak apa-apa, saya bisa—",
  ui_story_5089_50890100_61_dialog_content = "Saya juga membawa beberapa makanan ringan dari istana untuk kesenangan Anda, jadi silakan bantu diri Anda sendiri. Jika saya tidak lagi dibutuhkan, maka saya akan pergi sekarang.",
  ui_story_5089_50890100_62_dialog_content = "Hah? Maksudmu kamu tidak akan makan bersama kami, Jiu?",
  ui_story_5089_50890100_63_dialog_content = "Lihat, Jiu? PlayerName menginginkan kehadiranmu, sekarang silakan duduk.",
  ui_story_5089_50890100_64_dialog_content = "... Itu akan menjadi pelanggaran etiket, Yang Mulia. Jika Anda membutuhkan saya, saya akan berada di pintu.",
  ui_story_5089_50890100_65_dialog_content = "...",
  ui_story_5089_50890100_66_dialog_content = "... Tentang apa itu tadi?",
  ui_story_5089_50890100_67_dialog_content = "Jiu memang bukan tipe yang suka berbicara, tapi jarak di antara kita terasa lebih kuat dari biasanya hari ini.",
  ui_story_5089_50890100_68_dialog_content = "Jika ada, aku lebih suka dia berdebat denganku.",
  ui_story_5089_50890100_69_dialog_content = "?",
  ui_story_5089_50890100_70_dialog_content = "Tapi mari kita tidak membicarakan itu sekarang. Alasan saya datang kemari hari ini adalah untuk mengucapkan selamat tinggal padamu.",
  ui_story_5089_50890100_71_dialog_content = "Pamit...? Kamu mau pergi ke mana?",
  ui_story_5089_50890100_72_dialog_content = "Paman saya, atau lebih tepatnya raja saat ini dari Kerajaan Ye, telah memanggil saya kembali ke kerajaan.",
  ui_story_5089_50890100_73_dialog_content = "Baiklah! Dantang, akhirnya kamu bisa pulang sekarang!",
  ui_story_5089_50890100_74_dialog_content = "Tapi, apakah benar-benar semudah itu? Lagipula, kamu datang ke Kerajaan Ji sebagai... Um, sebagai mahasiswa pertukaran.",
  ui_story_5089_50890100_75_dialog_content = "Tidak ada yang perlu disembunyikan. Apakah benar-benar sulit untuk mengucapkan kata \"sandera\"?",
  ui_story_5089_50890100_76_dialog_content = "Kekhawatiranmu, bagaimanapun, sangat valid. Sebagai sandera politik, kembali ke rumah dari mana saya diasingkan tidak akan pernah menjadi hal yang sederhana.",
  ui_story_5089_50890100_77_dialog_content = "Di permukaan, tampaknya kerajaan Ji dan Ye sedang bernegosiasi tentang persyaratan baru.",
  ui_story_5089_50890100_78_dialog_content = "Tapi di bawah permukaannya?",
  ui_story_5089_50890100_79_dialog_content = "Masterku sudah meyakinkan aku bahwa Kerajaan Ji tidak akan menghalangi perjalanan pulangku.",
  ui_story_5089_50890100_80_dialog_content = "\"Pedagang, meskipun didorong oleh keuntungan, sama sekali tidak tidak bersyukur.\" Itulah kurang lebih kata-kata dari raja.",
  ui_story_5089_50890100_81_dialog_content = "Maksudnya bagaimana...?",
  ui_story_5089_50890100_82_dialog_content = "Setelah kerusuhan Festival Musim Semi, sebuah kuil yang didedikasikan untuk Dragon Maiden dibangun di dalam istana, dan sebuah patung emas dibuat untuk menghormatinya.",
  ui_story_5089_50890100_83_dialog_content = "Keluarga Lin sedang berkumpul dan semakin kuat setiap harinya, dan kamu menjadi warga yang dicintai dan dihormati di Kerajaan Ji.",
  ui_story_5089_50890100_84_dialog_content = "Saya sendiri tidak terkecuali menerima hadiah murah hati dari kerajaan.",
  ui_story_5089_50890100_85_dialog_content = "Tapi ada satu orang yang, meskipun usahanya, belum menerima kompensasi dalam bentuk apa pun.",
  ui_story_5089_50890100_86_dialog_content = "Maksudmu Xuan Ji, 'kan? Aku sama sekali tidak bisa menghubunginya akhir-akhir ini... Apakah kamu tahu apa yang terjadi padanya?",
  ui_story_5089_50890100_87_dialog_content = "Ini adalah hal kedua yang ingin saya bicarakan dengan Anda.",
  ui_story_5089_50890100_88_dialog_content = "Kami menerima dekrit kerajaan dari Kerajaan Ye. Atas perintah raja, Menteri Armilla harus ditangkap dan dipenjara setelah penutupan Festival Musim Semi.",
  ui_story_5089_50890100_89_dialog_content = "Dia dituduh mengkhianati kerajaan melalui penggunaan mesin kritisnya.",
  ui_story_5089_50890100_90_dialog_content = "Apa?!",
  ui_story_5089_50890100_91_dialog_content = "Dan untuk alasan ini, aku telah memutuskan untuk segera bertindak dan kembali ke Ye Kingdom besok.",
  ui_story_5089_50890100_92_dialog_content = "Saya hanya berharap bisa melakukan perjalanan ini lebih cepat. Demi Ministress Armilla, saya harus menyelidiki tuduhan-tuduhan ini dan mengungkap kebenaran.",
  ui_story_5089_50890100_93_dialog_content = "PlayerName—",
  ui_story_5089_50890100_94_dialog_content = "Aku juga akan pergi!",
  ui_story_5089_50890100_95_dialog_content = "Baiklah.",
  ui_story_5089_50890100_96_dialog_content = "Ketika kamu bilang akan pergi, aku sudah ingin memintamu untuk membawaku bersamamu.",
  ui_story_5089_50890100_97_dialog_content = "Aku bukan dewa, dan aku tidak datang ke Longzhou hanya untuk duduk di sini dan menerima persembahan—bahkan dewa sejati pun tidak melakukan hal itu.",
  ui_story_5089_50890100_98_dialog_content = "Tidak ada yang bisa saya lakukan di Haojin, jadi sekarang adalah waktu yang tepat untuk pergi.",
  ui_story_5089_50890100_99_dialog_content = "Dan selain itu, Xuan Ji juga adalah temanku. Tidak peduli apa yang kamu katakan, aku akan menemukan cara untuk ikut. Tunggu, apa yang baru saja kamu katakan?",
  ui_story_5089_50890100_100_dialog_content = "Baiklah.",
  ui_story_5089_50890100_101_dialog_content = "... Saya pikir kamu akan mengatakan bahwa ini tidak ada hubungannya dengan saya, dan menyuruh saya untuk tinggal di sini.",
  ui_story_5089_50890100_102_dialog_content = "Tidak ada yang bisa bertahan hidup dalam isolasi. Mereka yang memiliki banyak sekutu berkembang, sementara mereka yang sedikit punah.",
  ui_story_5089_50890100_103_dialog_content = "Ajaranmu masih bergema di telingaku. Aku tidak berani melupakannya.",
  ui_story_5089_50890100_104_dialog_content = "D-Apakah aku benar-benar mengatakan sesuatu yang keren kepada kamu?",
  ui_story_5089_50890100_105_dialog_content = "Heheh. Jika Anda memaafkan saya, saya harus kembali ke istana untuk membuat persiapan akhir kita. Sampai besok, PlayerName.",
  ui_story_5089_50890100_106_dialog_content = "Aku juga harus mengemas barang-barangku...",
  ui_story_5089_50890100_107_dialog_content = "Meninggalkan begitu cepat?",
  ui_story_5089_50890100_108_dialog_content = "Wow! Chen'ni? Apa yang kamu lakukan di sini lagi?!",
  ui_story_5089_50890100_109_dialog_content = "Oh, sekitar waktu kamu berharap aku bisa menggunakan kekuatanku untuk menyembunyikanmu.",
  ui_story_5089_50890100_110_dialog_content = "J-Jadi selama ini kau berada di sini!",
  ui_story_5089_50890100_111_dialog_content = "... Yang berarti kamu juga mendengar semua itu, kan? Aku akan pergi ke Kerajaan Ye besok, jadi aku tidak bisa bermain denganmu untuk sementara waktu.",
  ui_story_5089_50890100_112_dialog_content = "Tidak masalah! Aku juga akan ikut; jika ada yang menghalangi kita, aku akan melakukan yang terbaik!",
  ui_story_5089_50890100_113_dialog_content = "\"Tinju iblis dan kirim mereka terbang ke segala arah!\"",
  ui_story_5089_50890100_114_dialog_content = "Tidak, tidak, tidak. Itu bukan dalam Tarian Naga, kenapa kamu terus menerus mengingat itu?!",
  ui_story_5089_50890100_115_dialog_content = "Apakah itu benar-benar penting? Bagaimanapun, legenda tentang dewa-dewi dan pahlawan selalu berubah sepanjang tahun.",
  ui_story_5089_50890100_116_dialog_content = "Dan berkat kamu, aku memutuskan untuk mengambil pelajaran bela diri dan menjalani legenda terbaru ku!",
  ui_story_5089_50890100_117_dialog_content = "Baik, tapi ingatlah untuk menahan pukulanmu. Aku tidak akan ada di sana untuk mengawasimu, jadi kamu harus melakukannya sendiri.",
  ui_story_5089_50890100_118_dialog_content = "Jadi, kau benar-benar tidak ingin aku menemanimu ke Kerajaan Ye? Karena jika kau hanya membuat keinginan...",
  ui_story_5089_50890100_119_dialog_content = "Andai aku melakukannya, apakah kau masih akan menjadi temanku?",
  ui_story_5089_50890100_120_dialog_content = "...",
  ui_story_5089_50890100_121_dialog_content = "Aku ingin tetap berteman dengan kamu selama aku masih ada, Chen'ni.",
  ui_story_5089_50890100_122_dialog_content = "Ini berarti saya tidak akan pernah memperlakukan Naga Mulia Yang Maha Pengasih sebagai sumber daya yang bisa dieksploitasi.",
  ui_story_5089_50890100_123_dialog_content = "<color=#e8d9bb>Tiba-tiba, Chen'ni mengulurkan tangan dan mencabut daun dari pohon di luar jendela, lalu menyerahkannya.</color>",
  ui_story_5089_50890100_124_dialog_content = "Apa ini?",
  ui_story_5089_50890100_125_dialog_content = "Sebuah hadiah perpisahan.",
  ui_story_5089_50890100_126_dialog_content = "Ini tradisi Aurorian, kan?",
  ui_story_5089_50890100_127_dialog_content = "Aku akan berada di sini menunggu saat kamu kembali, PlayerName. Kita akan memiliki banyak kesenangan saat kamu melakukannya!",
  ui_story_5089_50890100_128_dialog_content = "Saya cukup yakin Aurorian menggunakan cabang willow untuk—Uh, Chen'ni?",
  ui_story_5089_50890100_129_dialog_content = "Dia pergi tanpa kata lain... Sepertinya aku akan menyimpan ini untuk saat ini dan menjemurnya nanti.",
  ui_story_5089_50890100_130_dialog_content = "Ini juga waktu yang baik untuk mengucapkan selamat tinggal kepada yang lainnya.",
  ui_story_5089_50890100_131_dialog_content = "<color=#e8d9bb>Hari berikutnya</color>",
  ui_story_5089_50890100_132_dialog_content = "Ini adalah tempat di mana saya seharusnya bertemu Dantang, benar?",
  ui_story_5089_50890100_133_dialog_content = "PlayerName! PlayerName! Akhirnya kamu di sini! Aku sudah menunggu cukup lama, tahu!",
  ui_story_5089_50890100_134_dialog_content = "Pangeran Mahkota... Apa yang sedang Anda lakukan di sini? Dan apa itu kotak besar di sana?",
  ui_story_5089_50890100_135_dialog_content = "Saya di sini untuk mengantarkan kepulanganmu, tentu saja. Saya bahkan telah menyiapkan beberapa hadiah perpisahan.",
  ui_story_5089_50890100_136_dialog_content = "Aku dengan hati-hati memilih setiap harta karun yang tak ternilai ini hanya untukmu!",
  ui_story_5089_50890100_137_dialog_content = "Lihat? Ini adalah boneka yang selalu saya bawa kemana-mana saat masih kecil. Dan ini adalah lentera yang saya buat sendiri saat festival.",
  ui_story_5089_50890100_138_dialog_content = "Oh, dan buku cerita favoritku! Tuan tidak membiarkanku membacanya, jadi aku harus meminta banyak orang untuk membantuku membelinya!",
  ui_story_5089_50890100_139_dialog_content = "Yang mengingatkan saya... Dantang dan Penasihat Utama menceritakan semuanya kepada saya.",
  ui_story_5089_50890100_140_dialog_content = "Aku tidak pernah meminta pendapatmu sebelum memutuskan bahwa kamu akan menjadi pasanganku. Itu adalah kesalahanku, dan aku minta maaf telah menempatkanmu dalam posisi yang sulit seperti ini.",
  ui_story_5089_50890100_141_dialog_content = "Yang Mulia...",
  ui_story_5089_50890100_142_dialog_content = "Kapal akan segera berlayar, PlayerName.",
  ui_story_5089_50890100_143_dialog_content = "Ah, oke. Pokoknya, karena ini semua adalah tanda kejujuranmu, aku dengan senang hati akan menerimanya.",
  ui_story_5089_50890100_144_dialog_content = "Luar biasa!",
  ui_story_5089_50890100_145_dialog_content = "Pengawal, pergi ambil sisanya!",
  ui_story_5089_50890100_146_dialog_content = "T-Tunggu... Apa itu tumpukan peti?!",
  ui_story_5089_50890100_147_dialog_content = "Oh, hanya beberapa barang kecil untuk perjalananmu. Saya hanya punya waktu untuk menyiapkan kotak ini, jadi saya meninggalkan sisanya dengan pria-pria saya.",
  ui_story_5089_50890100_148_dialog_content = "Tapi ketulusan saya benar-benar nyata! Tolong percayalah padaku!",
  ui_story_5089_50890100_149_dialog_content = "Sekarang setelah aku tumbuh dan memahami cara kerja dunia, aku menyadari betapa cerobohnya aku sebelumnya.",
  ui_story_5089_50890100_150_dialog_content = "Saya sekarang melihat bahwa proses pendekatan harus selalu dilakukan sebelum pernikahan!",
  ui_story_5089_50890100_151_dialog_content = "...Maafkan aku?",
  ui_story_5089_50890100_152_dialog_content = "Angkat jangkar—",
  ui_story_5089_50890100_153_dialog_content = "Angkat sauh—",
  ui_story_5089_50890100_154_dialog_content = "<color=#e8d9bb>Saat kapal perlahan berangkat, sang pangeran melambaikan tangan dan berteriak dari pantai.</color>",
  ui_story_5089_50890100_155_dialog_content = "Selamat jalan! Dan tenang saja, saya akan terus memanjakanmu dengan hadiah sampai kamu setuju untuk menjadi pendampingku—",
  ui_story_5089_50890100_156_dialog_content = "...",
  ui_story_5089_50890100_157_dialog_content = "Aku tahu keluar dari Haojin adalah langkah yang tepat!",
  ui_story_5089_50890100_158_dialog_content = "Bahkan saya terkejut dengan kasih sayang pangeran terhadapmu, PlayerName. Saya belum pernah melihat dia mengejar sesuatu dengan niat yang begitu teguh.",
  ui_story_5089_50890100_159_dialog_content = "Tapi, aku tidak bisa menerima semua hadiah ini, meskipun mereka hanya sekumpulan mainan...",
  ui_story_5089_50890100_160_dialog_content = "Jika kamu benar-benar tidak bisa menerimanya, saya bisa mengatur untuk mengirimkannya kembali setelah kita sampai di Kerajaan Ye.",
  ui_story_5089_50890100_161_dialog_content = "Itu harus menjadi rencananya. Menyelamatkan Xuan Ji lebih penting daripada segalanya.",
  ui_story_5089_50890100_162_dialog_content = "Benar. Akhirnya saatnya untuk pergi... Tidak, tunggu.",
  ui_story_5089_50890100_163_dialog_content = "Akhirnya saatnya kembali ke Kerajaan Ye.",
  ui_story_5089_50890201_1_dialog_content = "Yang Mulia, PlayerName, silakan bersiap untuk turun.",
  ui_story_5089_50890201_2_dialog_content = "Tapi kita baru saja melewati perbatasan antara dua kerajaan, bukan? Apakah kita benar-benar di sana?",
  ui_story_5089_50890201_3_dialog_content = "Belum, tidak. Tidak seperti Kerajaan Ji dan banyak jalur airnya, Kerajaan Ye terletak di dataran luas, di tengah-tengah. Kapal hanya bisa membawa kita sejauh ini.",
  ui_story_5089_50890201_4_dialog_content = "Hei, saya ingat pelabuhan ini... Ini adalah Kota Tongli, bukan?",
  ui_story_5089_50890201_5_dialog_content = "Ya, Yang Mulia. Saya sudah memesan penginapan untuk malam ini. Kita akan beristirahat di sana dan melanjutkan perjalanan kita besok.",
  ui_story_5089_50890201_6_dialog_content = "Setelah kereta-kereta telah diamankan, kita akan langsung berangkat ke ibukota melalui darat.",
  ui_story_5089_50890201_7_dialog_content = "Itu mengesankan, Jiu! Bagaimana Anda bisa melakukan semua itu sementara kita masih di atas air?",
  ui_story_5089_50890201_8_dialog_content = "Kapal ini dilengkapi dengan perahu dayung kecil. Saya menggunakannya untuk sampai ke pantai dan mengatur segalanya lebih awal.",
  ui_story_5089_50890201_9_dialog_content = "Mengingat sifat perjalanan kita yang tiba-tiba dan tak terduga, tidak ada yang telah diberitahu untuk menerima kita pada titik ini.",
  ui_story_5089_50890201_10_dialog_content = "Sudah cukup menjadi kejahatan bahwa Yang Mulia harus menginap di penginapan kecil yang sederhana ini, jadi kita harus setidaknya memastikan keamanan sekitarnya.",
  ui_story_5089_50890201_11_dialog_content = "Kamu bilang kita sudah dekat, tapi aku tidak melihat tanda-tanda daratan...",
  ui_story_5089_50890201_12_dialog_content = "Kamu mendayung sejauh itu sendiri... Tidak heran kamu benar-benar basah kuyup.",
  ui_story_5089_50890201_13_dialog_content = "Sebaiknya kamu mengganti pakaianmu dengan yang kering sebelum kamu masuk angin.",
  ui_story_5089_50890201_14_dialog_content = "Terima kasih atas perhatianmu, tapi aku tidak begitu rapuh. Seumur hidup berlatih seni bela diri membuatku dalam kondisi kesehatan yang cukup baik.",
  ui_story_5089_50890201_15_dialog_content = "Saya mendarat untuk mengintai area dan memastikan keamanannya, tetapi meninggalkan Yang Mulia untuk urusanku sendiri akan menjadi kelalaian tugas.",
  ui_story_5089_50890201_16_dialog_content = "Kemudian lagi, tidak pantas bagiku untuk menunjukkan pemandangan seperti itu di sekitar Yang Mulia. Maafkan saya, saya akan tetap berada di luar pandangan.",
  ui_story_5089_50890201_17_dialog_content = "Tunggu, bukan itu maksudku—",
  ui_story_5089_50890201_18_dialog_content = "Tak apa, PlayerName. Biarkan saja dia pergi.",
  ui_story_5089_50890201_19_dialog_content = "Ini adalah waktu terlama aku melihat dia menampakkan dirinya dalam waktu yang cukup lama.",
  ui_story_5089_50890201_20_dialog_content = "Bahkan di istana, ketika saya sibuk mengurusi surat-surat dan dokumen, dia sering mengisi ulang teh dan makanan ringan saya tanpa saya sadari.",
  ui_story_5089_50890201_21_dialog_content = "Atau ketika saya kembali dari pertemuan dengan orang lain, saya selalu menemukan kamar saya sangat rapi dan bersih.",
  ui_story_5089_50890201_22_dialog_content = "Dia telah melakukan lebih banyak dari biasanya tanpa ada yang menyadari sama sekali.",
  ui_story_5089_50890201_23_dialog_content = "(E-Elfin pembuat sepatu?)",
  ui_story_5089_50890201_24_dialog_content = "Jadi, apa yang sebenarnya terjadi di antara kalian berdua?",
  ui_story_5089_50890201_25_dialog_content = "PlayerName, apakah kamu masih ingat kelompok orang yang bertanggung jawab atas kekacauan di Haojin beberapa waktu lalu?",
  ui_story_5089_50890201_26_dialog_content = "Maksudmu orang-orang yang menyebut diri mereka Fate Riders?",
  ui_story_5089_50890201_27_dialog_content = "Ya. Dengan bantuan dari Naga Mulia Yang Maha Penyayang, Kantor Inspeksi berhasil menangkap sejumlah besar Fate Riders yang bersembunyi di Kerajaan Ji.",
  ui_story_5089_50890201_28_dialog_content = "Di antara mereka ada puluhan orang yang menjabat posisi resmi di pengadilan kerajaan.",
  ui_story_5089_50890201_29_dialog_content = "Meskipun mereka kebanyakan adalah pejabat tingkat bawah, seiring waktu, mereka mampu membentuk jaringan yang kuat di antara mereka sendiri...",
  ui_story_5089_50890201_30_dialog_content = "Cukup kuat untuk sangat mempengaruhi pengadilan, bahkan raja sendiri. Bahkan, bisa dikatakan bahwa orang-orang ini telah memperoleh kekuatan untuk mengguncang seluruh kerajaan hingga ke intinya.",
  ui_story_5089_50890201_31_dialog_content = "Beruntung, kita berhasil menangkap mereka semua, dan sekarang raja dan penasihatnya lebih waspada dari sebelumnya. Para pengkhianat ini tidak akan bisa bertindak semena-mena lagi.",
  ui_story_5089_50890201_32_dialog_content = "Tetapi meski begitu, PlayerName... Apakah kamu benar-benar percaya bahwa jaringan mereka hanya terbatas di Kerajaan Ji?",
  ui_story_5089_50890201_33_dialog_content = "Maksudmu…",
  ui_story_5089_50890201_34_dialog_content = "Pada malam kerusuhan di Haojin, saya mencoba mencari Anda, tetapi saya dicegat segera setelah meninggalkan gerbang istana.",
  ui_story_5089_50890201_35_dialog_content = "Ini pertama kalinya aku mendengar tentang ini! Mereka tidak menyakitimu, kan? Kenapa kamu tidak memberitahu siapa pun?!",
  ui_story_5089_50890201_36_dialog_content = "Karena yang menghadang saya adalah mata-mata dari Kerajaan Ye.",
  ui_story_5089_50890201_37_dialog_content = "Apa?!",
  ui_story_5089_50890201_38_dialog_content = "Kaisar saat ini dari Kekaisaran Zhao masih muda, dan delapan raja masing-masing memiliki niat mereka sendiri.",
  ui_story_5089_50890201_39_dialog_content = "Meskipun spionase di antara mereka cukup umum, itu bukanlah sesuatu yang bisa dibicarakan secara terbuka.",
  ui_story_5089_50890201_40_dialog_content = "Dan meskipun mata-mata Kerajaan Ye menghormatiku sebagai tuan putri mereka, mereka tetap hanya menjawab kepada satu orang: paman saya.",
  ui_story_5089_50890201_41_dialog_content = "Jadi mereka menghalangiku, dan dengan demikian membantu Fate Riders dalam rencana mereka...",
  ui_story_5089_50890201_42_dialog_content = "Apakah Raja Ye benar-benar satu-satunya yang bisa mengendalikan mereka?",
  ui_story_5089_50890201_43_dialog_content = "Paman saya tidak terkenal sebelum naik takhta dan telah menjadi penguasa yang teladan. Dia menunjuk orang berdasarkan bakat mereka, sangat peduli pada rakyatnya, dan membawa dirinya dengan sikap seorang raja sejati.",
  ui_story_5089_50890201_44_dialog_content = "Yang membuat saya berasumsi bahwa ini adalah pekerjaan dari Fate Riders!",
  ui_story_5089_50890201_45_dialog_content = "Oh, begitu. Pantas saja kamu terburu-buru ingin kembali.",
  ui_story_5089_50890201_46_dialog_content = "Dengan menghindari Fate Riders dari Ye Kingdom sebanyak mungkin, kamu bebas bergerak dan menyelidiki masalah, yang nantinya bisa kamu laporkan kepada raja.",
  ui_story_5089_50890201_47_dialog_content = "Dan kemudian, secara logis, kita akan bisa menyelamatkan Xuan Ji, yang dipenjara karena membantu kita!",
  ui_story_5089_50890201_48_dialog_content = "Kamu memang sangat mengenalku, PlayerName.",
  ui_story_5089_50890201_49_dialog_content = "Tapi apa hubungannya semua ini dengan Jiu?",
  ui_story_5089_50890201_50_dialog_content = "Aku kira kamu tahu.",
  ui_story_5089_50890201_51_dialog_content = "Jiu tidak lain adalah pemimpin mata-mata Kerajaan Ye.",
  ui_story_5089_50890201_52_dialog_content = "Apa?! Bukankah dia penjaga pribadimu?",
  ui_story_5089_50890201_53_dialog_content = "Jiu awalnya adalah pelayan yang dipercaya di bawah perintah langsung paman saya. Dia ditugaskan kepada saya sebagai penjaga tepat sebelum saya dikirim ke Kerajaan Ji sebagai sandera.",
  ui_story_5089_50890201_54_dialog_content = "Paman saya telah menunjukkan banyak kebaikan padanya. Dia tidak akan pernah menentang perintah apa pun yang datang darinya.",
  ui_story_5089_50890201_55_dialog_content = "Dan karena paman saya memerintahnya untuk melindungi saya, dia rela mempertaruhkan nyawanya untuk melakukannya.",
  ui_story_5089_50890201_56_dialog_content = "Karena khawatir akan keselamatan saya, dia telah meminta dia untuk menulis kepadanya setiap bulan dengan pembaruan. Terlepas dari musim atau keadaan, dia tidak pernah melewatkan batas waktu.",
  ui_story_5089_50890201_57_dialog_content = "Itu…?",
  ui_story_5089_50890201_58_dialog_content = "Aku mengerti kekhawatiran pamanku, tapi dari perspektif lain, itu juga bisa dianggap sebagai pengawasan.",
  ui_story_5089_50890201_59_dialog_content = "Tunggu, apakah itu berarti Fate Riders masih melacak tindakan kita?! Apakah Jiu...",
  ui_story_5089_50890201_60_dialog_content = "Kamu bisa mengesampingkan keraguanmu.",
  ui_story_5089_50890201_61_dialog_content = "Setelah semua ini, kamu telah melihatnya sendiri, bukan? Jiu menolak untuk berbohong tentang apapun kepada saya atau paman saya.",
  ui_story_5089_50890201_62_dialog_content = "Dia tidak akan pernah menentang perintahnya, tetapi dia sepenuhnya memahami arti dari perjalanan kita. Karena alasan itu, dia hanya bisa memalingkan muka, tetap diam, dan tidak mengajukan pertanyaan.",
  ui_story_5089_50890201_63_dialog_content = "Selama dia menjalankan tugasnya sebagai penjaga dan menjaga jarak dariku, dia tidak perlu melaporkan apa pun yang dia tidak tahu.",
  ui_story_5089_50890201_64_dialog_content = "Dia sudah melakukan segala yang dia bisa untuk kita.",
  ui_story_5089_50890201_65_dialog_content = "Namun, aku tidak bisa menyangkal kegembiraanku setelah melihat penjaga keras kepala saya sedikit goyah.",
  ui_story_5089_50890201_66_dialog_content = "Setidaknya, lima tahun yang kita habiskan bersama di Kerajaan Ji tidak sepenuhnya sia-sia.",
  ui_story_5089_50890201_67_dialog_content = "Dantang.",
  ui_story_5089_50890201_68_dialog_content = "Ya? Biar aku tebak: kamu tidak berpikir aku harus merasa senang melihat dia berjuang, bukan?",
  ui_story_5089_50890201_69_dialog_content = "Kamu pasti sudah sangat kesulitan di Kerajaan Ji selama bertahun-tahun ini, ya?",
  ui_story_5089_50890201_70_dialog_content = "Hah…?",
  ui_story_5089_50890201_71_dialog_content = "Eh, yah... Maksudku...",
  ui_story_5089_50890201_72_dialog_content = "Saya tahu bahwa Raja Ji, Pangeran Mahkota, dan Penasihat Utama semuanya orang baik, tetapi mereka bukan keluargamu.",
  ui_story_5089_50890201_73_dialog_content = "Huh...",
  ui_story_5089_50890201_74_dialog_content = "A-Apa itu? Apa aku mengatakan sesuatu yang salah?",
  ui_story_5089_50890201_75_dialog_content = "Sama sekali tidak. Bahkan, jika kamu adalah seorang komandan tentara, sesuatu mengatakan padaku bahwa kamu akan sangat baik dalam serangan mendadak.",
  ui_story_5089_50890201_76_dialog_content = "Hah? Kenapa kita tiba-tiba membicarakan itu?",
  ui_story_5089_50890201_77_dialog_content = "Jika kamu memaafkan saya, saya perlu merapikan riasan wajah saya sebelum kita turun.",
  ui_story_5089_50890201_78_dialog_content = "Eh, baiklah...",
  ui_story_5089_50890201_79_dialog_content = "Gaok...",
  ui_story_5089_50890201_80_dialog_content = "Gaok...",
  ui_story_5089_50890201_81_dialog_content = "Kayu busuk tidak pernah bisa diukir!",
  ui_story_5089_50890201_82_dialog_content = "Dan pohon besi tidak akan pernah mekar!",
  ui_story_5089_50890201_83_dialog_content = "Hei, siapa yang kamu sebut \"kayu busuk\"?! Tunggu... Mengomel? Mengoceh? Apa yang kalian berdua lakukan di sini?",
  ui_story_5089_50890201_84_dialog_content = "Serahkan beberapa semangka emas dan saya akan memandu jalanmu!",
  ui_story_5089_50890201_85_dialog_content = "Tawarkan beberapa tanggal perak, dan saya akan menghilangkan semua keraguan Anda!",
  ui_story_5089_50890201_86_dialog_content = "Maaf mengecewakan, tapi saya tidak memiliki kedua hal tersebut.",
  ui_story_5089_50890201_87_dialog_content = "Jika kamu lapar, cukup minta makanan dari tuanmu. Dia seharusnya juga ada di sekitar sini, bukan? Saya sangat paham kebiasaannya muncul tiba-tiba.",
  ui_story_5089_50890201_88_dialog_content = "Tianxian! Kamu juga di sini, kan?",
  ui_story_5089_50890201_89_dialog_content = "Kami tidak lagi memiliki seorang Master!",
  ui_story_5089_50890201_90_dialog_content = "Air telah mengklaimnya!",
  ui_story_5089_50890201_91_dialog_content = "Di sana!",
  ui_story_5089_50890201_92_dialog_content = "Apa…?!",
  ui_story_5089_50890201_93_dialog_content = "Glub, glub... Tolong... Aku... Tidak bisa berenang... Glub, glub, glub...",
  ui_story_5089_50890201_94_dialog_content = "Apa yang dia lakukan di air?! Ah, ini tidak baik...",
  ui_story_5089_50890201_95_dialog_content = "Aku harus menyelamatkannya!",
  ui_story_5089_50890202_1_dialog_content = "Hatsyiii!",
  ui_story_5089_50890202_2_dialog_content = "Syukurlah, aku masih bisa melihat hari lain.",
  ui_story_5089_50890202_3_dialog_content = "Apa-apaan yang sedang kamu lakukan, tenggelam di tempat seperti ini? Jangan bilang kamu mendapatkan undangan lain ke Istana Naga?!",
  ui_story_5089_50890202_4_dialog_content = "Tidak... Sebenarnya jauh lebih sederhana dari itu.",
  ui_story_5089_50890202_5_dialog_content = "Saya telah lelah berkelana di Kerajaan Ji, jadi saya berpikir untuk mengunjungi tanah baru. Tetapi seperti yang kamu tahu, saya sering kekurangan dana.",
  ui_story_5089_50890202_6_dialog_content = "Tidak mampu membayar tiket di kapal yang lebih besar, saya tidak punya pilihan selain bepergian dengan karavan pedagang yang lebih kecil. Setelah berhenti tak terhitung jumlahnya di sepanjang jalan, kami akhirnya tiba di Kerajaan Ye.",
  ui_story_5089_50890202_8_dialog_content = "Sungguh pemandangan yang jarang, mengingat istana mengadakan upacara tahunan untuk mengusir monster-monster ini dari tanah mereka. Perbatasan antara Kerajaan Ji dan Ye bahkan tidak dekat dengan laut.",
  ui_story_5089_50890202_10_dialog_content = "Dan begitu mereka mengejar tanpa berpikir dua kali. Saat aku berlari menyelamatkan diri, aku kehilangan pandangan sekeliling dan akhirnya terjun ke laut.",
  ui_story_5089_50890202_11_dialog_content = "Tapi berkat kalian semua, nyawaku sekali lagi diselamatkan. Andai saja aku punya sesuatu yang berharga untuk ditawarkan sebagai tanda terima kasihku...",
  ui_story_5089_50890202_12_dialog_content = "Sepertinya aku tidak punya pilihan selain membayar utangku padamu dengan tubuhku!",
  ui_story_5089_50890202_13_dialog_content = "T-Tidak perlu itu!",
  ui_story_5089_50890202_14_dialog_content = "Kamu tidak punya hal lain yang lebih penting untuk dikerjakan sekarang?!",
  ui_story_5089_50890202_15_dialog_content = "Katakan, apa kau masih ingat namaku?",
  ui_story_5089_50890202_16_dialog_content = "Uh, ya? Itu Tianxian, bukan?",
  ui_story_5089_50890202_17_dialog_content = "Benar! Dan jika Anda menerjemahkannya secara harfiah, itu berarti \"pengangguran terhebat di dunia\"!",
  ui_story_5089_50890202_18_dialog_content = "Jadi tolong, jangan terlalu cepat menolakku. Sebelum saya berangkat, saya meramal nasib saya sendiri. Meskipun itu meramalkan kemalangan besar dalam perjalanan saya, itu juga mengisyaratkan kedatangan seorang dermawan yang baik hati dan kaya raya.",
  ui_story_5089_50890202_19_dialog_content = "Adapun siapa mungkin itu... Sini, ulurkan tanganmu untukku.",
  ui_story_5089_50890202_20_dialog_content = "Begini?",
  ui_story_5089_50890202_21_dialog_content = "<color=#e8d9bb>Gemerincing!</color>",
  ui_story_5089_50890202_22_dialog_content = "Uh... Mengapa Anda membuang semua tongkat ramalan Anda ke tangan saya?",
  ui_story_5089_50890202_23_dialog_content = "Oh sayang, hexagram Yin Naga dan Yin Tikus. Ini bukan pertanda baik bagi kita.",
  ui_story_5089_50890202_24_dialog_content = "Naga yang bangkit dan tikus yang melompat biasanya adalah tanda-tanda yang menggembirakan, tetapi dalam kasus ini, hal tersebut justru sebaliknya. Bersama-sama, mereka menandakan bahwa ancaman yang mengerikan tersembunyi di depan kita, dan bahwa penjahat sedang merencanakan sesuatu yang jahat saat kita berbicara. Singkatnya, kita sedang menghadapi bencana yang segera akan terjadi.",
  ui_story_5089_50890202_25_dialog_content = "Dalam keadaan normal, saya seharusnya sedang berlari menyelamatkan diri sekarang. Namun, saya tidak bisa meninggalkan penyelamat saya sendirian menghadapi bencana ini.",
  ui_story_5089_50890202_26_dialog_content = "Ah, ya, tidak bisa dihindari. Izinkan saya bergabung dengan Anda dalam perjalanan Anda sehingga kita dapat menghadapi ancaman mengerikan ini bersama-sama.",
  ui_story_5089_50890202_27_dialog_content = "Saya selalu curiga dengan apa pun yang kamu katakan, tetapi situasi ini tampaknya sangat mencurigakan.",
  ui_story_5089_50890202_28_dialog_content = "Bagaimana bisa? Kamu yang telah menyelamatkanku dari kuburan air, 'kan?",
  ui_story_5089_50890202_29_dialog_content = "Ya, tetapi ramalan keberuntunganmu mengatakan seorang \"donatur kaya\" akan menyelamatkanmu.",
  ui_story_5089_50890202_30_dialog_content = "Tidak bermaksud sombong atau apa pun, tapi saya tidak pernah kaya sehari pun dalam hidup saya!",
  ui_story_5089_50890202_31_dialog_content = "Hmm, aneh sekali. Ramalan saya menunjukkan bahwa seharusnya kau sudah cukup kaya untuk bersaing dengan sebuah negara sekarang.",
  ui_story_5089_50890202_32_dialog_content = "Ya, mungkin dalam mimpiku...",
  ui_story_5089_50890202_33_dialog_content = "Kapal sekarang telah merapat, PlayerName. Seorang pendayung akan segera datang untuk membawa barang-barangmu, jadi merasa bebas untuk turun kapan saja.",
  ui_story_5089_50890202_34_dialog_content = "Seorang pendayung? Itu sama sekali tidak bisa! Sebagai bagian dari pembayaran hutang hidupku kepadamu, izinkan aku membawa kotak ini—",
  ui_story_5089_50890202_35_dialog_content = "Aduh! Kenapa ini sangat berat...?!",
  ui_story_5089_50890202_36_dialog_content = "<color=#e8d9bb>Membanting!</color>",
  ui_story_5089_50890202_37_dialog_content = "<color=#e8d9bb>Kotak itu jatuh dengan suara gemuruh, mengetuk tutupnya hingga terbuka. Menjadi kejutan bagi semua orang, kotak itu penuh sampai meluap dengan harta karun yang mempesona dan berwarna emas.</color>",
  ui_story_5089_50890202_38_dialog_content = "PlayerName, saatnya untuk turun—",
  ui_story_5089_50890202_39_dialog_content = "...",
  ui_story_5089_50890202_40_dialog_content = "...",
  ui_story_5089_50890202_41_dialog_content = "...",
  ui_story_5089_50890202_42_dialog_content = "T-Tidak ada yang rusak, kan? Oh tidak, oh Tuhan di atas... Aku tidak akan pernah bisa mengganti apa pun dari ini jika aku merusaknya!",
  ui_story_5089_50890202_43_dialog_content = "Uh, teman-teman? Saya cukup yakin ada yang salah dengan mata saya.",
  ui_story_5089_50890202_44_dialog_content = "Kotak yang diberikan pangeran kepadaku... Kenapa sepertinya penuh dengan emas? Hahaha...",
  ui_story_5089_50890202_45_dialog_content = "... Jiu.",
  ui_story_5089_50890202_46_dialog_content = "<color=#e8d9bb>Jiu tiba-tiba muncul atas panggilan Dantang. Tanpa kata lain, dia memeriksa setiap peti yang diberikan kepada mereka oleh pangeran mahkota.</color>",
  ui_story_5089_50890202_47_dialog_content = "Pemeriksaanku selesai, Lady Dantang. Selain dua kotak penuh mainan dan beberapa kasus jade dan batu berharga, semuanya lainnya adalah emas.",
  ui_story_5089_50890301_1_dialog_content = "Kita sudah berjalan bertahun-tahun... Bagaimana mungkin kita belum sampai? Apakah penginapan benar-benar sejauh itu dari dermaga...?",
  ui_story_5089_50890301_2_dialog_content = "Bukankah kamu yang bersikeras mengambil jalan belakang karena takut dirampok? Anda tidak punya siapa-siapa untuk disalahkan selain diri sendiri karena telah mengundang dewa kekayaan ke rumah Anda, teman saya.",
  ui_story_5089_50890301_3_dialog_content = "Jangan salah paham! Saya hanya ketakutan akan dirampok karena saya memiliki kewajiban untuk mengembalikan semua barang ini! Siapa pun juga akan bereaksi dengan cara yang sama!",
  ui_story_5089_50890301_4_dialog_content = "Pangeran bahkan mengatakan bahwa kotak-kotak ini hanyalah \"barang kecil\" untuk perjalanan kami...",
  ui_story_5089_50890301_5_dialog_content = "Untuk Pangeran Mahkota Kerajaan Ji, emas dan perak hanyalah benda-benda sepele.",
  ui_story_5089_50890301_6_dialog_content = "Tapi untuk orang lain... Kamu bisa dengan mudah membeli seluruh kota di Kerajaan Ye dengan emas sebanyak ini, PlayerName.",
  ui_story_5089_50890301_7_dialog_content = "Tapi tidak perlu khawatir. Dengan Jiu di pihak kita, tidak ada bandit biasa yang berharap bisa mendekati kita.",
  ui_story_5089_50890301_8_dialog_content = "Kita hampir sampai di penginapan. Itu hanya di ujung jalan ini.",
  ui_story_5089_50890301_9_dialog_content = "Akhirnya, istirahat yang sangat dibutuhkan. Bagian perjalanan ini sangat membuat gugup... Hah? Ada yang salah, Dantang?",
  ui_story_5089_50890301_10_dialog_content = "Tidak, hanya saja... Aku ingat melewati tempat ini dalam perjalanan ke Kerajaan Ji beberapa tahun lalu.",
  ui_story_5089_50890301_11_dialog_content = "Kota Tongli... Sebuah pemukiman pantai yang berbatasan dengan salah satu wilayah penghasil biji-bijian terbesar di Kerajaan Ye. Mungkin tidak bisa dibandingkan dengan kota utama, tetapi pasti ramai pada saat itu.",
  ui_story_5089_50890301_12_dialog_content = "Namun entah bagaimana, kali ini terasa jauh lebih sepi.",
  ui_story_5089_50890301_13_dialog_content = "Maka sepertinya kamu belum pernah ke sini selama bertahun-tahun, wanita muda.",
  ui_story_5089_50890301_14_dialog_content = "Tolong jelaskan, Tuan yang baik.",
  ui_story_5089_50890301_15_dialog_content = "Mencerahkan kamu, eh? Apa yang bisa saya ajarkan kepada kamu yang setiap orang tidak sudah tahu?",
  ui_story_5089_50890301_16_dialog_content = "Dalam beberapa tahun terakhir, kota ini telah membangun banyak workshop besar, menawarkan gaji bulanan yang murah hati dan menarik semua orang muda untuk bekerja di dalamnya.",
  ui_story_5089_50890301_17_dialog_content = "Jika saja aku tidak begitu tua dan lemah, aku pasti suka bekerja di tempat yang tidak tergantung pada cuaca.",
  ui_story_5089_50890301_18_dialog_content = "Saya mengerti. May Boleh saya tanya berapa harga beras ini, Pak?",
  ui_story_5089_50890301_19_dialog_content = "Kamu ingin membeli beberapa? Aku harus memberi tahu kamu, harga beras telah naik selama dua bulan terakhir, dan sedikit lebih tinggi hari ini. Untuk beras sebanyak ini—",
  ui_story_5089_50890301_20_dialog_content = "... Baiklah. Terima kasih.",
  ui_story_5089_50890301_21_dialog_content = "Apakah ada yang salah dengan tas beras itu?",
  ui_story_5089_50890301_22_dialog_content = "Ketika kita kembali ke Haojin, saya bertanya tentang harga beras, dan tampaknya cocok dengan harga di sini. Itu seharusnya tidak menjadi masalah, kan?",
  ui_story_5089_50890301_23_dialog_content = "Biaya beras di kota kecil seperti ini mengejutkan karena mirip dengan Haojin, salah satu kota terkaya di Kekaisaran Zhao.",
  ui_story_5089_50890301_24_dialog_content = "Mengatakan ini bukan masalah jauh dari kebenaran. Tapi bagaimana ini mungkin...?",
  ui_story_5089_50890301_25_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5089_50890301_26_dialog_content = "Oh, maaf tentang itu! Aku tidak bermaksud menabrakmu... Huh? Apa itu di tanganmu...?",
  ui_story_5089_50890301_27_dialog_content = "…!",
  ui_story_5089_50890301_28_dialog_content = "S-Tuan! Kamu harus menghentikan anak kecil itu!",
  ui_story_5089_50890301_29_dialog_content = "Dia kabur dengan barang bawaanmu!",
  ui_story_5089_50890301_30_dialog_content = "!",
  ui_story_5089_50890301_31_dialog_content = "—!",
  ui_story_5089_50890301_32_dialog_content = "Berhenti melawan.",
  ui_story_5089_50890301_33_dialog_content = "Hrngh! Lepaskan aku! Biarkan aku... PERGI!",
  ui_story_5089_50890301_34_dialog_content = "<color=#e8d9bb>Anak laki-laki itu menggigit tangan Jiu dengan ganas, tetapi yang terakhir tetap sama sekali tidak terpengaruh, ekspresinya dingin dan tanpa perasaan.</color>",
  ui_story_5089_50890301_35_dialog_content = "Kembalikan apa yang telah kamu curi.",
  ui_story_5089_50890301_36_dialog_content = "<color=#e8d9bb>Dengan mata yang merah dan bengkak, anak laki-laki itu menggigit lebih keras lagi.</color>",
  ui_story_5089_50890301_37_dialog_content = "Jiu!",
  ui_story_5089_50890301_38_dialog_content = "<color=#e8d9bb>Dalam kehilangan fokus sesaat itu, anak laki-laki itu terlepas dari genggaman Jiu seperti ikan.</color>",
  ui_story_5089_50890301_39_dialog_content = "Pffft!",
  ui_story_5089_50890301_40_dialog_content = "Hei, kamu—",
  ui_story_5089_50890301_41_dialog_content = "Tolong! Selamatkan aku! Orang-orang itu mencoba menculikku!",
  ui_story_5089_50890301_42_dialog_content = "Apa? Siapa yang cukup bodoh untuk mencoba menculik anak kecil di siang bolong?!",
  ui_story_5089_50890301_43_dialog_content = "Orang-orang di sana itu, yang memakai pakaian aneh itu! Saya tahu mereka bermasalah sejak pertama kali melihat mereka!",
  ui_story_5089_50890301_44_dialog_content = "Panggil penjaga kota! Tangkap para penjahat itu!",
  ui_story_5089_50890301_45_dialog_content = "Ap-Apa ini sekarang? Tolong jangan terburu-buru! Saya jamin kita semua di pihak yang sama, jadi mari kita bicarakan ini dengan tenang dan rasional!",
  ui_story_5089_50890301_46_dialog_content = "Tidak ada yang berpihak padamu, pidana!",
  ui_story_5089_50890301_47_dialog_content = "Argh, ada terlalu banyak orang di sini! Anak itu semakin menjauh!",
  ui_story_5089_50890301_48_dialog_content = "Minggir dari putri!",
  ui_story_5089_50890301_49_dialog_content = "Tidak apa-apa, Jiu. Mereka hanya warga biasa yang peduli dengan keselamatan mereka sendiri.",
  ui_story_5089_50890301_50_dialog_content = "Tapi bagaimana jika...",
  ui_story_5089_50890301_51_dialog_content = "Kamu lebih cepat tanpa aku, jadi ambil PlayerName dan pergi mencari anak kecil itu. Aku akan menangani sisanya dari penduduk kota.",
  ui_story_5089_50890301_52_dialog_content = "Saya tidak bisa melakukan itu, Yang Mulia. Perintah saya adalah melindungi Anda.",
  ui_story_5089_50890301_53_dialog_content = "Maka anggaplah itu sebagai perintah dariku. Sekarang pergi.",
  ui_story_5089_50890301_54_dialog_content = "... Ya, Yang Mulia.",
  ui_story_5089_50890301_55_dialog_content = "Tolong tetap dekat dengan saya, PlayerName.",
  ui_story_5089_50890301_56_dialog_content = "Bagaimana bisa anak itu berhasil meloloskan diri begitu cepat?",
  ui_story_5089_50890301_57_dialog_content = "Huh... Aku punya firasat sesuatu seperti ini akan terjadi segera setelah aku melihat tumpukan emas itu.",
  ui_story_5089_50890301_58_dialog_content = "Namun, saya terkejut bahwa orang yang merampok saya hanyalah seorang anak kecil.",
  ui_story_5089_50890301_59_dialog_content = "Dia berpakaian compang-camping, meski begitu. Saya yakin dia juga telah menghadapi berbagai kesulitan.",
  ui_story_5089_50890301_60_dialog_content = "...",
  ui_story_5089_50890301_61_dialog_content = "Kamu tidak akan berbicara denganku kecuali jika benar-benar perlu, bukan?",
  ui_story_5089_50890301_62_dialog_content = "...",
  ui_story_5089_50890301_63_dialog_content = "Saya tahu saya hanyalah orang luar, dan saya masih memiliki banyak hal yang harus dipelajari tentang Longzhou. Akan sangat arogan jika saya mengatakan bahwa saya mengerti situasi Anda.",
  ui_story_5089_50890301_64_dialog_content = "Tapi, saya telah bertemu banyak orang berbeda selama perjalanan saya.",
  ui_story_5089_50890301_65_dialog_content = "Beberapa dari mereka dengan rela mengorbankan segalanya untuk keyakinan mereka, dan menjadi mercusuar untuk fajar yang akan datang.",
  ui_story_5089_50890301_66_dialog_content = "Beberapa orang bersedia menghancurkan segalanya demi mimpi mereka, meskipun itu berarti jatuh ke dalam jurang kegelapan terdalam.",
  ui_story_5089_50890301_67_dialog_content = "Saya tidak memiliki hak untuk menilai benar atau salah mereka, dan saya pasti tidak memenuhi syarat untuk mendefinisikan kehidupan orang lain hanya dalam beberapa kata. Saya rasa itu yang coba saya sampaikan.",
  ui_story_5089_50890301_68_dialog_content = "Adalah bahwa hanya ada satu cara untuk tidak mencapai apa-apa, dan itu adalah dengan tidak melakukan apa-apa sama sekali.",
  ui_story_5089_50890301_69_dialog_content = "Saya adalah seorang prajurit di bawah perintah Raja Ye, dan penjaga yang dipercaya dengan perlindungan Tuan Putri Dantang.",
  ui_story_5089_50890301_70_dialog_content = "Tugas saya adalah mematuhi perintah dan memenuhi tanggung jawab saya tanpa ragu-ragu.",
  ui_story_5089_50890301_71_dialog_content = "Tak perlu bagi saya untuk mengubah apa pun.",
  ui_story_5089_50890301_72_dialog_content = "Lalu, izinkan saya bertanya sesuatu. Apa yang akan Anda lakukan jika raja dan Dantang memberi Anda perintah yang bertentangan?",
  ui_story_5089_50890301_73_dialog_content = "Baik raja maupun tuan putri adalah penguasa yang murah hati yang memikul penderitaan rakyat mereka di hati mereka. Mereka sepenuhnya mengabdikan diri mereka untuk kepentingan Kerajaan Ye.",
  ui_story_5089_50890301_74_dialog_content = "Itu bukan jawaban yang sangat meyakinkan, tahu?",
  ui_story_5089_50890301_75_dialog_content = "Aku…",
  ui_story_5089_50890301_76_dialog_content = "Masih belum ada tanda-tanda dari anak itu, ya? Mungkin aku harus mencoba merasakan lokasinya.",
  ui_story_5089_50890301_77_dialog_content = "Pemindaian Psikis!",
  ui_story_5089_50890301_78_dialog_content = "Di sana! Dia berada di sebuah gang di selatan kita—Hah?",
  ui_story_5089_50890301_79_dialog_content = "Pffffft—",
  ui_story_5089_50890301_80_dialog_content = "Anak itu...",
  ui_story_5089_50890301_81_dialog_content = "(Eh? Sepertinya aku baru saja tersandung sesuatu...)",
  ui_story_5089_50890301_82_dialog_content = "<color=#e8d9bb>Gemerincing, gemerincing!</color>",
  ui_story_5089_50890301_83_dialog_content = "<color=#e8d9bb>Seikat batang bambu jatuh dengan hantaman keras.</color>",
  ui_story_5089_50890301_84_dialog_content = "Sebuah jebakan?!",
  ui_story_5089_50890301_85_dialog_content = "(A-Aku harus minggir!)",
  ui_story_5089_50890301_86_dialog_content = "<color=#e8d9bb>Seolah-olah mengantisipasi langkah selanjutnya dari penyusup, batu bata di bawah perangkap runtuh ke dalam lubang yang tersembunyi dengan baik.</color>",
  ui_story_5089_50890301_87_dialog_content = "<color=#e8d9bb>Sploosh!</color>",
  ui_story_5089_50890301_88_dialog_content = "<color=#e8d9bb>Sebuah ember kayu penuh air jatuh dari langit—</color>",
  ui_story_5089_50890301_89_dialog_content = "Ahhhh!",
  ui_story_5089_50890301_90_dialog_content = "Awas.",
  ui_story_5089_50890301_91_dialog_content = "<color=#e8d9bb>Jiu melaju ke depan seperti hembusan angin yang tak terlihat.</color>",
  ui_story_5089_50890301_92_dialog_content = "<color=#e8d9bb>Dengan gesit, dia memukul ember dengan ujung pedangnya yang belum ditarik, mengarahkannya menjauh dari target yang dimaksud.</color>",
  ui_story_5089_50890301_93_dialog_content = "<color=#e8d9bb>Dengan suara duk yang ringan, botol itu mendarat dengan anggun di kaki anak laki-laki itu tanpa menumpahkan setetes air pun.</color>",
  ui_story_5089_50890301_94_dialog_content = "<color=#e8d9bb>Sementara itu, tiang bambu yang berjatuhan melayang di udara sejenak sebelum terpecah menjadi berbagai bagian dan jatuh tanpa membahayakan ke lantai..</color>",
  ui_story_5089_50890301_95_dialog_content = "<color=#e8d9bb>Pada suatu titik, mereka telah dipotong rapi menjadi dua bagian.</color>",
  ui_story_5089_50890301_96_dialog_content = "I-Itu... luar biasa.",
  ui_story_5089_50890301_97_dialog_content = "Bagaimana dia...",
  ui_story_5089_50890301_98_dialog_content = "Kembalikan apa yang telah kamu curi. Aku tidak akan mengatakannya lagi.",
  ui_story_5089_50890301_99_dialog_content = "... Aku tidak tahu apa yang kamu bicarakan!!",
  ui_story_5089_50890301_100_dialog_content = "Berhenti—",
  ui_story_5089_50890301_101_dialog_content = "Tunggu, Jiu.",
  ui_story_5089_50890301_102_dialog_content = "Dia berusaha keras untuk memasang jebakan-jebakan ini, dan dia bahkan tetap di sini ketika dia tidak perlu. Mungkin ada alasan yang baik untuk itu.",
  ui_story_5089_50890301_103_dialog_content = "Barang-barang yang dicuri pasti disembunyikan di rumah sebelah.",
  ui_story_5089_50890301_104_dialog_content = "!",
  ui_story_5089_50890301_105_dialog_content = "Hei, berhenti! Aku yang mencuri barangmu, jadi datang dan tangkap aku!",
  ui_story_5089_50890301_106_dialog_content = "Sudah kuduga.",
  ui_story_5089_50890301_107_dialog_content = "Aku belum akan masuk sekarang, tetapi apakah kamu bersedia untuk tenang dan berbicara dengan kami sebagai gantinya?",
  ui_story_5089_50890301_108_dialog_content = "Kami bukan orang jahat, saya janji. Bahkan, jika kamu sedang mengalami masa-masa sulit, kami mungkin bahkan bisa membantu.",
  ui_story_5089_50890301_109_dialog_content = "... Sebenarnya, saya...",
  ui_story_5089_50890301_110_dialog_content = "Mundur!",
  ui_story_5089_50890301_111_dialog_content = "Apa…?!",
  ui_story_5089_50890301_112_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5089_50890301_113_dialog_content = "<color=#e8d9bb>Jiu menghunus pedangnya lebih cepat daripada yang bisa dilihat siapa pun.</color>",
  ui_story_5089_50890301_114_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_5089_50890301_115_dialog_content = "<color=#e8d9bb>Dengan gerakan yang penuh semangat, dia membelokkan beberapa kawat logam yang sangat kuat dan halus.</color>",
  ui_story_5089_50890301_116_dialog_content = "Di situ kau rupanya.",
  ui_story_5089_50890301_117_dialog_content = "Siapa—",
  ui_story_5089_50890301_118_dialog_content = "<color=#e8d9bb>Tanpa memberi respons, sosok misterius itu melepaskan serangan kawat yang kejam lagi!</color>",
  ui_story_5089_50890302_1_dialog_content = "Sekarang kesempatanmu, Jiu! Turunkan dia!",
  ui_story_5089_50890302_2_dialog_content = "Hmph.",
  ui_story_5089_50890302_3_dialog_content = "<color=#e8d9bb>Sekarang berbaring di tanah, pembunuh tiba-tiba mengangkat lengannya dan melancarkan serangan diam-diam dengan kawatnya!</color>",
  ui_story_5089_50890302_4_dialog_content = "Argh!",
  ui_story_5089_50890302_5_dialog_content = "<color=#e8d9bb>Menetes.</color>",
  ui_story_5089_50890302_6_dialog_content = "<color=#e8d9bb>Sebuah tetes darah merah tua jatuh dengan diam ke tanah yang kotor.</color>",
  ui_story_5089_50890302_7_dialog_content = "Jiu...!",
  ui_story_5089_50890302_8_dialog_content = "<color=#e8d9bb>Jiu berdiri di depan penyerang mereka, kawatnya tertangkap di tangan telanjangnya.</color>",
  ui_story_5089_50890302_9_dialog_content = "Permintaan maaf saya karena mengejutkan Anda, Tuan PlayerName.",
  ui_story_5089_50890302_10_dialog_content = "<color=#e8d9bb>Tiba-tiba, dia menggenggam tangannya bersama-sama dan menarik dengan sekuat tenaga.</color>",
  ui_story_5089_50890302_11_dialog_content = "<color=#e8d9bb>Pembunuh yang mencoba melarikan diri dengan melompat, ditarik turun oleh kawat logam merah darah dan jatuh keras ke tanah.</color>",
  ui_story_5089_50890302_12_dialog_content = "Sebentar sementara saya menangkapnya.",
  ui_story_5089_50890302_13_dialog_content = "Sial... Seandainya bukan iblis bertopeng itu...",
  ui_story_5089_50890302_14_dialog_content = "Datanglah dengan damai, dan mungkin nyawamu bisa diselamatkan.",
  ui_story_5089_50890302_15_dialog_content = "Frost Blade... Mungkin aku hanya seorang pengintai, tapi kita berdua langsung bertanggung jawab kepada raja. Itu berarti kita berada di pihak yang sama, bukan?",
  ui_story_5089_50890302_16_dialog_content = "Saya hanya mencoba menjalankan misi saya. Apakah Anda benar-benar berniat menghalangi saya untuk memenuhi perintah raja kita?",
  ui_story_5089_50890302_17_dialog_content = "...",
  ui_story_5089_50890302_18_dialog_content = "Kamu kembali, Jiu! Bagaimana luka-lukamu? Pembunuh itu barusan...",
  ui_story_5089_50890302_19_dialog_content = "Maafkan aku, aku... aku membiarkannya kabur.",
  ui_story_5089_50890302_20_dialog_content = "Selama kamu baik-baik saja, maka tidak apa-apa... Tunggu, tidak, ini sama sekali tidak baik!",
  ui_story_5089_50890302_21_dialog_content = "Mengapa kamu baru saja menggunakan tanganmu untuk menahan serangannya?! Apakah kamu tidak merasa sakit atau bagaimana?! Di sini, biarkan aku melihat lukamu!",
  ui_story_5089_50890302_22_dialog_content = "Ini hanya goresan, PlayerName, tidak lebih. Saya bisa merawatnya sendiri.",
  ui_story_5089_50890302_23_dialog_content = "Lagi? Uhh... Sudahlah. Lakukan apa pun yang kamu mau, aku akan pergi mengurus anak-anak.",
  ui_story_5089_50890302_24_dialog_content = "\"Anak-anak\"?",
  ui_story_5089_50890302_25_dialog_content = "Benar, dua anak itu dari sebelumnya. Mereka berada di rumah itu di sana.",
  ui_story_5089_50890302_26_dialog_content = "Waaaaaah! Aku sangat takut!",
  ui_story_5089_50890302_27_dialog_content = "J-Jangan menangis lagi, bisa tidak? Ini, saya membawakan Anda beberapa barang bagus hari ini!",
  ui_story_5089_50890302_28_dialog_content = "Lihat? Banyak mainan lucu dan lentera cantik, hanya untukmu!",
  ui_story_5089_50890302_29_dialog_content = "Dan lihat semua buku cerita ini! Mau aku baca satu untukmu? Ayo, jangan menangis...",
  ui_story_5089_50890302_30_dialog_content = "Waaaaaaaaah!",
  ui_story_5089_50890302_31_dialog_content = "Dan itulah yang terjadi. Anak itu tidak pernah mencuri emas sang pangeran. Yang dia inginkan hanyalah kotak penuh mainan.",
  ui_story_5089_50890302_32_dialog_content = "Siapa yang peduli dengan emas baumu itu?",
  ui_story_5089_50890302_33_dialog_content = "Waaaaaah! Orang menakutkan lainnya!",
  ui_story_5089_50890302_34_dialog_content = "Oh, bagus. Lihat apa yang telah kamu lakukan! Keluar dari sini sekarang juga! Sudah, sudah, jangan menangis! Aku akan memberimu apa pun yang kamu inginkan, aku janji!",
  ui_story_5089_50890302_35_dialog_content = "...",
  ui_story_5089_50890302_36_dialog_content = "Jiu?",
  ui_story_5089_50890302_37_dialog_content = "<color=#e8d9bb>Jiu jongkok di depan gadis kecil itu, dengan canggung mengangkat tangannya, dan meletakkan topengnya di atas kepala gadis itu.</color>",
  ui_story_5089_50890302_38_dialog_content = "A-Apa yang kamu pikir kamu lakukan?! Jika kamu menyentuhnya—",
  ui_story_5089_50890302_39_dialog_content = "Angin telah datang, hujan telah datang, Raja Naga memukul drumnya.",
  ui_story_5089_50890302_40_dialog_content = "Di bawah topeng ini, kamu akan menemukan tempat untuk bersembunyi, anak kecilku.",
  ui_story_5089_50890302_41_dialog_content = "Dan kita akan makan semangka di bawah sinar matahari setelah badai berlalu.",
  ui_story_5089_50890302_42_dialog_content = "<color=#e8d9bb>Ketika Jiu dengan lembut membacakan lagu pengantar tidur, tangisan gadis yang tersembunyi di balik topeng perlahan mereda.</color>",
  ui_story_5089_50890302_43_dialog_content = "(Aku tidak tahu Jiu bisa begitu lembut.)",
  ui_story_5089_50890302_44_dialog_content = "PlayerName! Jiu! Syukurlah aku akhirnya menemukanmu!",
  ui_story_5089_50890302_45_dialog_content = "Oh? Apa yang sedang terjadi di sini? Kenapa Jiu memutuskan untuk melepas topengnya?",
  ui_story_5089_50890302_46_dialog_content = "Yang Mulia! Saya hanya...",
  ui_story_5089_50890302_47_dialog_content = "Um, permisi...",
  ui_story_5089_50890302_48_dialog_content = "Hah?",
  ui_story_5089_50890302_49_dialog_content = "B-Bisakah kamu menyanyikan lagu itu sekali lagi?",
  ui_story_5089_50890302_50_dialog_content = "Ini sama seperti... Lagu yang biasa dinyanyikan ibuku.",
  ui_story_5089_50890302_51_dialog_content = "Tentu saja.",
  ui_story_5089_50890302_52_dialog_content = "Benarkah? Lalu, dapatkah teman-temanku datang dan mendengarkan juga?",
  ui_story_5089_50890302_53_dialog_content = "Temanmu...?",
  ui_story_5089_50890302_54_dialog_content = "Kakak Ergou! Pergi panggil yang lainnya!",
  ui_story_5089_50890302_55_dialog_content = "Mungkin mereka tidak terlalu buruk setelah semua. Tunggu sebentar, aku akan pergi mencari mereka.",
  ui_story_5089_50890302_56_dialog_content = "Apa yang terjadi, Xiaohua? Kenapa kau memanggil kita?",
  ui_story_5089_50890302_57_dialog_content = "Apa benar itu penting? Toh memang tidak ada hal lebih baik yang bisa kita lakukan.",
  ui_story_5089_50890302_58_dialog_content = "Apa yang dilakukan semua orang dewasa ini di sini...?",
  ui_story_5089_50890302_59_dialog_content = "Kenapa ada begitu banyak anak-anak di sini?",
  ui_story_5089_50890302_60_dialog_content = "Pemilik penginapan cukup baik untuk memberi tahu saya tentang situasi di kota ini. Izinkan saya menjelaskan.",
  ui_story_5089_50890302_61_dialog_content = "Ingat apa yang dikatakan pria tua itu tentang bengkel-bengkel di kota, dan bagaimana sebagian besar orang yang mampu bekerja di kota telah pergi untuk bekerja di sana? Meskipun pekerjaan ini mungkin menguntungkan, mereka masih membutuhkan pekerja untuk meninggalkan rumah mereka jauh-jauh.",
  ui_story_5089_50890302_62_dialog_content = "Sebagai hasilnya, banyak anak-anak yang ditinggalkan dalam asuhan kakek-nenek mereka, yang tidak bisa diharapkan untuk menjaga mereka setiap jam dalam sehari.",
  ui_story_5089_50890302_63_dialog_content = "Tanpa pengawasan, anak-anak ini cenderung berkumpul dan berlarian tanpa kendali.",
  ui_story_5089_50890302_64_dialog_content = "Jadi mereka sebenarnya tidak berhubungan darah? Saya pikir mereka berdua adalah saudara, jadi saya...",
  ui_story_5089_50890302_65_dialog_content = "Xiaohua masih tetap kakakku. Orang tuaku meninggal dini, tapi keluarganya telah memberi makan padaku selama ini.",
  ui_story_5089_50890302_66_dialog_content = "Jadi tentu saja, saya setuju untuk merawatnya ketika mereka memberi tahu saya bahwa mereka akan pergi bekerja beberapa hari yang lalu.",
  ui_story_5089_50890302_67_dialog_content = "Tapi Xiaohua sangat merindukan orang tuanya. Dia telah menangis beberapa hari ini, jadi itulah mengapa aku...",
  ui_story_5089_50890302_68_dialog_content = "Ingin menghiburnya dengan beberapa mainan?",
  ui_story_5089_50890302_69_dialog_content = "Ya. Tapi sekarang setelah kamu menangkapku, saya akan menerima hukuman atau teguran apa pun yang kamu berikan untukku.",
  ui_story_5089_50890302_70_dialog_content = "Meskipun mencuri itu salah, bagaimana mungkin aku bisa memarahimu setelah mengetahui semua ini?",
  ui_story_5089_50890302_71_dialog_content = "Ah, apa yang harus kita lakukan tentang anak-anak ini? Sekarang setelah mereka telah mengepung Jiu, sepertinya dia benar-benar terjebak.",
  ui_story_5089_50890302_72_dialog_content = "Maka kamu harus segera bergegas membantunya, PlayerName.",
  ui_story_5089_50890302_73_dialog_content = "Tapi apa yang harus kulakukan?",
  ui_story_5089_50890302_74_dialog_content = "Meminta Jiu untuk bernyanyi untuk begitu banyak orang adalah sedikit berlebihan, bahkan untuk dirinya. Kita harus mencoba meringankan beban untuknya.",
  ui_story_5089_50890302_75_dialog_content = "Ayo, mari kita ambil pipa saya dari penginapan.",
  ui_story_5089_50890302_76_dialog_content = "Dulu saya diberitahu bahwa kamu cukup mahir bermain piano, tapi saya belum pernah mendengar kamu bermain. Maukah kamu bergabung denganku untuk berduet hari ini?",
  ui_story_5089_50890302_77_dialog_content = "Sebenarnya mau, tapi aku tidak melihat piano di sini.",
  ui_story_5089_50890302_78_dialog_content = "Oh, itu seharusnya tidak menjadi masalah.",
  ui_story_5089_50890302_79_dialog_content = "Musisi masa lalu bisa mengimprovisasi melodi dengan benda sehari-hari. Saya tidak melihat alasan mengapa Caelestite tidak bisa melakukan hal yang sama, terutama ketika kita memiliki semua cangkir ini.",
  ui_story_5089_50890302_80_dialog_content = "Nih? Kita bisa menghasilkan semua jenis nada dengan mengisinya dengan berbagai jumlah air dan memukulnya seperti ini.",
  ui_story_5089_50890302_81_dialog_content = "Kurasa aku bisa mencobanya.",
  ui_story_5089_50890302_82_dialog_content = "Jiu, apakah kamu masih ingat apa yang kukatakan saat kita pertama kali mengunjungi Twin Pavilions Bay?",
  ui_story_5089_50890302_83_dialog_content = "Jika, suatu hari, aku bisa duet dengan pemain piano, aku berharap kamu akan datang dan menari dengan pedangmu.",
  ui_story_5089_50890302_84_dialog_content = "T-T-Tapi ada begitu banyak orang...",
  ui_story_5089_50890302_85_dialog_content = "Kamu tidak sendirian, Jiu. Kami juga bersamamu.",
  ui_story_5089_50890302_86_dialog_content = "Jika itu terlalu banyak untuk diminta, saya tidak akan memaksa Anda. Hanya saja, penampilan hari ini mungkin agak kurang tanpa bantuan Anda.",
  ui_story_5089_50890302_87_dialog_content = "U-Mengerti...",
  ui_story_5089_50890302_88_dialog_content = "Betapa memalukannya.",
  ui_story_5089_50890302_89_dialog_content = "Hehe, saya tidak begitu yakin. Lihat saja betapa cerahnya mata anak-anak bersinar, Jiu!",
  ui_story_5089_50890302_90_dialog_content = "Bagi mereka, tarian pedangmu adalah yang terbaik di dunia!",
  ui_story_5089_50890302_91_dialog_content = "Anda memuji saya, Yang Mulia. Saya hanya berusaha sebaik mungkin untuk menghindari membuat diri saya tampak lebih bodoh.",
  ui_story_5089_50890302_92_dialog_content = "Wah, lihat saja penampilan yang mengagumkan ini! Apakah ada yang bisa saya lakukan untuk berkontribusi?",
  ui_story_5089_50890302_93_dialog_content = "Mungkin sebuah lagu gembira untuk menghidupkan suasana bagi semua orang?",
  ui_story_5089_50890302_94_dialog_content = "Oh? Lagu apa yang kamu tahu?",
  ui_story_5089_50890302_95_dialog_content = "Ehem, biarkan aku melihat...",
  ui_story_5089_50890302_96_dialog_content = "Dari selatan ke utara, kami hadirkan pertunjukan hebat kami!",
  ui_story_5089_50890302_97_dialog_content = "Baik kamu pangeran atau pengemis, itu tidak masalah. Namun, uang recehmu sangat berarti!",
  ui_story_5089_50890302_98_dialog_content = "<color=#e8d9bb>Ding.</color>",
  ui_story_5089_50890302_99_dialog_content = "<color=#e8d9bb>Menyebutkan, sejumlah warga kota yang tidak curiga melemparkan beberapa koin kepadanya.</color>",
  ui_story_5089_50890302_100_dialog_content = "Li Tianxian!",
  ui_story_5089_50890302_101_dialog_content = "I-Ini semua bagian dari pertunjukan, Yang Mulia! Ingatlah untuk fokus pada musiknya!",
  ui_story_5089_50890302_102_dialog_content = "<color=#e8d9bb>Badai yang mengancam dan sekelompok penampil yang tidak mungkin, masing-masing dengan kekhawatiran mereka sendiri.</color>",
  ui_story_5089_50890302_103_dialog_content = "<color=#e8d9bb>Jauh dari pertunjukan yang sempurna, pertunjukan mereka lebih seperti kebetulan yang aneh.</color>",
  ui_story_5089_50890302_104_dialog_content = "<color=#e8d9bb>Tapi setidaknya, saat ini—</color>",
  ui_story_5089_50890302_105_dialog_content = "<color=#e8d9bb>Layak mendapatkan lagu sendiri.</color>",
  ui_story_5089_50890401_1_dialog_content = "Apa yang sedang kamu balik-balik di tanganmu, PlayerName?",
  ui_story_5089_50890401_2_dialog_content = "Maksudmu ini? Ini hanya patung perunggu. Er Gou mengembalikannya kepada saya sebelum kita berpisah tadi.",
  ui_story_5089_50890401_3_dialog_content = "Xiaohua tidak ingin mainan lain setelah dia mendapatkan topeng itu dari Jiu, jadi Ergou menyerahkan semua yang dia curi.",
  ui_story_5089_50890401_4_dialog_content = "Dan sebagai permintaan maaf, dia juga memberikan ini padaku.",
  ui_story_5089_50890401_5_dialog_content = "Dia mengatakan bahwa seorang wanita baik memberikannya kepadanya saat dia sedang lewat di kota. Dia mengatakan itu disebut boneka Moheluo.",
  ui_story_5089_50890401_6_dialog_content = "Ada sekelompok orang yang juga mengikutinya. Mereka semua mengenakan pakaian hitam dan hampir tidak mengucapkan sepatah kata pun sepanjang waktu, sungguh menyeramkan!",
  ui_story_5089_50890401_7_dialog_content = "Tapi dia adalah orang yang baik, tidak ada keraguan tentang itu. Dia bahkan mengundang kami ke salah satu penginapan yang lebih besar untuk makan malam, dan memberi kami semua daging yang bisa kami makan!",
  ui_story_5089_50890401_8_dialog_content = "Dia juga cukup pintar. Semua perangkap yang kami pasang di gang dibuat menggunakan desainnya.",
  ui_story_5089_50890401_9_dialog_content = "Dia mengatakan bahwa itu adalah dasar-dasar teknik penjebakan, dan kita bisa menjadi lebih cerdas dengan memahaminya.",
  ui_story_5089_50890401_10_dialog_content = "Apa dia menyebutkan namanya sama sekali?",
  ui_story_5089_50890401_11_dialog_content = "Tidak... Dia dan pengikutnya hanya tinggal di kota selama sehari, dan mereka pergi begitu cepat. Tapi itu mengingatkan saya!",
  ui_story_5089_50890401_12_dialog_content = "Dia memiliki kebiasaan aneh membawa payung besar ke mana pun dia pergi, meskipun tidak pernah hujan saat dia di sini!",
  ui_story_5089_50890401_13_dialog_content = "Kedengarannya seperti seseorang yang kita kenal, bukan?",
  ui_story_5089_50890401_14_dialog_content = "Benar bahwa rute ini adalah cara tercepat untuk kembali ke Kerajaan Ji. Mungkin Menteri Armilla benar-benar melewati sini?",
  ui_story_5089_50890401_15_dialog_content = "Namun, baginya bermain dengan anak-anak dan mentraktir mereka makan malam mewah, semuanya sambil membawa senjata di siang bolong...",
  ui_story_5089_50890401_16_dialog_content = "Tampaknya penjahat yang paling dicari di seluruh Kerajaan Ye sebenarnya menjalani kehidupan yang cukup bebas dan tanpa beban.",
  ui_story_5089_50890401_17_dialog_content = "Tapi dengan semua orang berpakaian hitam itu mengikutinya, mungkin dia tidak bisa bergerak sebebas yang dia inginkan.",
  ui_story_5089_50890401_18_dialog_content = "Maafkan saya PlayerName, tapi bolehkah saya melihat patung itu sebentar?",
  ui_story_5089_50890401_19_dialog_content = "Tentu. Saya telah mencoba merasakannya untuk informasi yang berguna, tetapi saya tidak menemukan apa pun.",
  ui_story_5089_50890401_20_dialog_content = "Sepertinya pikiran kita berpikir sama. Jika ada informasi yang bisa ditemukan, mungkin saja tersembunyi di dalam boneka ini...",
  ui_story_5089_50890401_21_dialog_content = "<color=#e8d9bb>Terlambat di malam hari</color>",
  ui_story_5089_50890401_22_dialog_content = "*Menguap*",
  ui_story_5089_50890401_23_dialog_content = "Ugh, tenggorokanku sangat kering. Aku butuh air...",
  ui_story_5089_50890401_24_dialog_content = "Ah, tekonya sudah kosong... Lebih baik periksa lorongnya.",
  ui_story_5089_50890401_25_dialog_content = "Hah? Lampu masih menyala di sana. Bukankah itu kamar Dantang?",
  ui_story_5089_50890401_26_dialog_content = "Apakah itu kamu di sana, PlayerName?",
  ui_story_5089_50890401_27_dialog_content = "Eh? Anda bisa melihat saya atau apa?",
  ui_story_5089_50890401_28_dialog_content = "Tidak, tapi aku bisa tahu dari suara langkah kakimu. Silakan masuk.",
  ui_story_5089_50890401_29_dialog_content = "Boneka itu lagi... Apakah kamu masih mempelajarinya?",
  ui_story_5089_50890401_30_dialog_content = "Ya. Apakah dia bermaksud meninggalkan ini atau tidak, saya yakin boneka ini memiliki beberapa pengetahuan tentang Menteri Armilla.",
  ui_story_5089_50890401_31_dialog_content = "Jadi, apa sebenarnya boneka Moheluo itu?",
  ui_story_5089_50890401_32_dialog_content = "Ini adalah jenis mainan yang populer di masa lalu. Namun, biasanya diukir dari tanah liat atau kayu, bukan logam.",
  ui_story_5089_50890401_33_dialog_content = "Dan masih, yang ini terbuat dari perunggu, benar?",
  ui_story_5089_50890401_34_dialog_content = "Benar, dan Ministress Armilla kebetulan sangat mahir dengan perunggu. Bahkan, klaim terawalnya terhadap ketenaran berasal dari seperangkat boneka mekanik musikal yang dia desain dan buat sendiri.",
  ui_story_5089_50890401_35_dialog_content = "Dia memainkan musik bersama maneken-maneken ini, dan baru setelah pertunjukan berakhir penontonnya menyadari ada yang tidak beres. Itulah saat mereka menyadari bahwa para musisi adalah semua boneka mekanik.",
  ui_story_5089_50890401_36_dialog_content = "Saya terkesan bahwa Xuan Ji bisa menciptakan boneka-boneka yang luar biasa... Jadi, kenapa boneka ini begitu kasar dan jelek?",
  ui_story_5089_50890401_37_dialog_content = "Itu poin aneh lainnya yang ingin saya sebutkan.",
  ui_story_5089_50890401_38_dialog_content = "Boneka Moheluo biasanya dibuat menyerupai anak kecil yang lucu dan menggemaskan, namun boneka ini tampak keriput dan mengerikan.",
  ui_story_5089_50890401_39_dialog_content = "Lebih lanjut, ini dimaksudkan untuk memegang daun atau bunga teratai di tangannya.",
  ui_story_5089_50890401_40_dialog_content = "Meskipun patung ini memang memegang bunga, pemeriksaan lebih dekat mengungkapkan bahwa itu adalah magnolia.",
  ui_story_5089_50890401_41_dialog_content = "Satu spesies berkembang di bawah air sementara yang lain takut akan banjir. Mereka sama tidak kompatibelnya seperti air dan api.",
  ui_story_5089_50890401_42_dialog_content = "Boneka ini mirip boneka Moheluo dalam banyak hal, namun sebenarnya sangat berbeda. Saya hanya bisa menggambarkannya sebagai pengganti, atau bahkan palsu.",
  ui_story_5089_50890401_43_dialog_content = "Sebuah pengganti atau palsu, huh...",
  ui_story_5089_50890401_44_dialog_content = "Di masa lalu, ada juga drama dengan nama yang sama persis.",
  ui_story_5089_50890401_45_dialog_content = "Kebanyakan orang tidak terlalu familiar dengan drama itu sendiri, tetapi salah satu barisnya sangat terkenal dan diakui oleh semua orang.",
  ui_story_5089_50890401_46_dialog_content = "Garis apa itu?",
  ui_story_5089_50890401_47_dialog_content = "\"Anda bisa melukis bulu harimau, tetapi tidak jiwanya. Anda bisa melihat wajah seseorang, tetapi tidak hatinya.\"",
  ui_story_5089_50890401_48_dialog_content = "<color=#e8d9bb>Jepret!</color>",
  ui_story_5089_50890401_49_dialog_content = "!",
  ui_story_5089_50890401_50_dialog_content = "Siapa yang pergi ke sana?!",
  ui_story_5089_50890402_1_dialog_content = "Melarikan diri di hadapan kekalahan? Setidaknya, hari ini aku telah mengukur kemampuan mereka.",
  ui_story_5089_50890402_2_dialog_content = "Apakah mereka Fate Riders tadi? Atau mereka...",
  ui_story_5089_50890402_3_dialog_content = "Saya tidak yakin.",
  ui_story_5089_50890402_4_dialog_content = "Tapi sebagaimana adanya, tidak ada perbedaan antara mereka dan mata-mata Kerajaan Ye.",
  ui_story_5089_50890402_5_dialog_content = "Beruntung, jumlah mereka tidak banyak, dan seni bela diri mereka medioker.",
  ui_story_5089_50890402_6_dialog_content = "Mereka memang ahli dalam melakukan penarikan diri dengan cepat, yang membuat saya berasumsi bahwa mereka hanya pengintai yang mengumpulkan informasi.",
  ui_story_5089_50890402_7_dialog_content = "Tapi itu berarti kita telah terbongkar, bukan? Bukankah kita harus pergi sekarang juga?",
  ui_story_5089_50890402_8_dialog_content = "Katakan padaku, PlayerName, pernahkah kamu memperhatikan sesuatu yang aneh?",
  ui_story_5089_50890402_9_dialog_content = "Apa yang kamu... Tunggu!",
  ui_story_5089_50890402_10_dialog_content = "Kami membuat keributan besar tadi... Tapi Jiu tidak ada di mana-mana!",
  ui_story_5089_50890402_11_dialog_content = "Mengapa orang-orang itu belum kembali? Mereka tidak terbunuh, bukan?",
  ui_story_5089_50890402_12_dialog_content = "Hmph, jika mereka tidak bisa menangani sesuatu sekecil ini, maka mereka pantas mati.",
  ui_story_5089_50890402_13_dialog_content = "*hela nafas* Kurasa itu sudah takdir kita. Lupakan mereka, dan aku akan ke kamar kecil.",
  ui_story_5089_50890402_14_dialog_content = "Jangan bergerak.",
  ui_story_5089_50890402_15_dialog_content = "!",
  ui_story_5089_50890402_16_dialog_content = "B-Baiklah, kamu menang. Aku tidak akan bergerak.",
  ui_story_5089_50890402_17_dialog_content = "Jika kamu bisa menyusup ke kamp kami dan menyandera saya seperti ini, maka saya pasti bukan tandinganmu.",
  ui_story_5089_50890402_18_dialog_content = "Jadi, bisakah kamu tolong geser sedikit pedangmu dari leherku? Lagipula, aku tidak akan bisa menjawab pertanyaan apa pun jika tanganmu kebetulan tergelincir.",
  ui_story_5089_50890402_19_dialog_content = "Mengapa kamu di sini? Apa perintahmu?",
  ui_story_5089_50890402_20_dialog_content = "Ada alasan khusus kenapa kamu...",
  ui_story_5089_50890402_21_dialog_content = "Cukup. Jawab pertanyaannya.",
  ui_story_5089_50890402_22_dialog_content = "S-Sesuai keinginan Anda. Kami hanya mengikuti perintah tuan kami untuk membawa putri yang tidak patuh ini kembali ke rumahnya.",
  ui_story_5089_50890402_23_dialog_content = "Kami hanya membantu dalam urusan keluarga kecil, itu saja. Kami tidak melakukan apa pun yang ilegal.",
  ui_story_5089_50890402_24_dialog_content = "Apakah membantu dalam \"masalah keluarga kecil\" biasanya membutuhkan banyak prajurit seperti ini?",
  ui_story_5089_50890402_25_dialog_content = "Bisakah kamu menyalahkan kami? Rumah tuan kami sangat megah, dan putrinya dilindungi oleh salah satu prajurit paling tangguh di kerajaan.",
  ui_story_5089_50890402_26_dialog_content = "Master kami secara pribadi menugaskan dia kepada putri kesayangannya, tetapi sepertinya dia telah menjadi liar bersama dengan orang yang dia awasi.",
  ui_story_5089_50890402_27_dialog_content = "Guru kita cukup kecewa dengan mereka berdua.",
  ui_story_5089_50890402_28_dialog_content = "...",
  ui_story_5089_50890402_29_dialog_content = "Seperti yang saya katakan, ini hanya masalah keluarga kecil, dan lebih baik diserahkan kepada mereka.",
  ui_story_5089_50890402_30_dialog_content = "Meskipun marah, master kami tidak akan pernah menyakiti putrinya dengan cara apa pun.",
  ui_story_5089_50890402_31_dialog_content = "Meskipun dia terus bersikap tidak masuk akal, tidak ada bahaya yang akan menimpanya. Pada paling buruk, dia akan dikurung di rumahnya dan dipaksa untuk menulis perintah keluarganya berulang kali.",
  ui_story_5089_50890402_32_dialog_content = "Di sisi lain, penjaganya mengancam rencana masternya dengan meninggalkan tugasnya.",
  ui_story_5089_50890402_33_dialog_content = "Saya hanya bisa membayangkan rasa sakitnya setelah menghabiskan semua tahun itu, hanya untuk membesarkan seorang pengkhianat yang tidak tahu berterima kasih. Apa pendapatmu—",
  ui_story_5089_50890402_34_dialog_content = "Halo? Apakah kamu masih di sana?",
  ui_story_5089_50890402_35_dialog_content = "Heheh.",
  ui_story_5089_50890402_36_dialog_content = "Apa yang membuatmu begitu lama?",
  ui_story_5089_50890402_37_dialog_content = "Maaf, saya baru saja berhenti untuk mengobrol dengan seorang teman lama.",
  ui_story_5089_50890402_38_dialog_content = "Tolong berikan pesan kepada mata-mata kita saat mereka kembali.",
  ui_story_5089_50890402_39_dialog_content = "Beritahu mereka bahwa kita akan mengantar putri pulang sebelum akhir hari besok.",
  ui_story_5089_50890402_40_dialog_content = "Dan jika iblis bertopeng itu menghalangi jalan kita, anggap saja itu sebagai tindakan pengkhianatan tingkat tinggi...",
  ui_story_5089_50890402_41_dialog_content = "Dihukum mati.",
  ui_story_5089_50890402_42_dialog_content = "... Yang Mulia? PlayerName? Mengapa kalian berada di luar?",
  ui_story_5089_50890402_43_dialog_content = "Di mana kamu, Jiu? Kami baru saja mendapatkan—",
  ui_story_5089_50890402_44_dialog_content = "PlayerName.",
  ui_story_5089_50890402_45_dialog_content = "Sudah malam. Kita seharusnya mundur ke kamar kita untuk sisa malam ini.",
  ui_story_5089_50890402_46_dialog_content = "Aku masih memiliki banyak yang harus dipertimbangkan, jika kamu tidak keberatan.",
  ui_story_5089_50890402_47_dialog_content = "… Oke.",
  ui_story_5089_50890402_48_dialog_content = "Selamat malam, Dantang. Kamu juga, Jiu.",
  ui_story_5089_50890402_49_dialog_content = "Selamat malam, PlayerName.",
  ui_story_5089_50890402_50_dialog_content = "...",
  ui_story_5089_50890402_51_dialog_content = "<color=#e8d9bb>Hari berikutnya</color>",
  ui_story_5089_50890402_52_dialog_content = "Master Li? May Bolehkah saya mengganggu Anda sebentar?",
  ui_story_5089_50890402_53_dialog_content = "Nngh... Apakah aku masih bermimpi? Apakah hari ini matahari terbit dari barat?",
  ui_story_5089_50890402_54_dialog_content = "Apa yang membuat Anda berbicara dengan sopan kepada saya hari ini, Yang Mulia?",
  ui_story_5089_50890402_55_dialog_content = "... Aku membutuhkan kamu untuk melakukan ramalan untukku.",
  ui_story_5089_50890402_56_dialog_content = "Astaga, sungguh kejadian yang sangat langka.",
  ui_story_5089_50890402_57_dialog_content = "Apa yang akan terjadi hari ini, Yang Mulia? Rencana takdir? Ramalan keberuntungan? Atau mungkin sesuatu yang lebih mendesak, seperti prospek pernikahan?",
  ui_story_5089_50890402_58_dialog_content = "Aku... Hanya ingin bertanya tentang jalan di depan.",
  ui_story_5089_50890402_59_dialog_content = "Saya memiliki masalah tertentu di tangan saya, tapi saya tidak tahu bagaimana melanjutkannya... Atau jika saya bahkan bisa melakukannya, untuk masalah itu.",
  ui_story_5089_50890402_60_dialog_content = "Tentu saja, Yang Mulia! Sekarang jika Anda mau, tolong ulurkan tangan Anda dan kita bisa mulai.",
  ui_story_5089_50890402_61_dialog_content = "Baiklah.",
  ui_story_5089_50890402_62_dialog_content = "<color=#e8d9bb>Gemerincing!</color>",
  ui_story_5089_50890402_63_dialog_content = "<color=#e8d9bb>Dua batang tongkat ramalan jatuh ke tangan Dantang. Namun, sebelum dia bisa melihat lebih dekat—</color>",
  ui_story_5089_50890402_64_dialog_content = "<color=#e8d9bb>Tianxian menuangkan sisa tongkat ramalannya.</color>",
  ui_story_5089_50890402_65_dialog_content = "A-Apa maksudnya ini, Master Li?",
  ui_story_5089_50890402_66_dialog_content = "Agh, mendengar kamu mengatakan itu terasa sangat tidak alami. Tolong panggil aku Tianxian atau Lying Li jika kamu lebih suka.",
  ui_story_5089_50890402_67_dialog_content = "Nah, tongkat ramalan saya mungkin tidak terlihat berarti bagi Anda, tetapi saya telah mengandalkan mereka untuk menjelajahi dunia selama ini.",
  ui_story_5089_50890402_68_dialog_content = "Ada orang-orang yang percaya pada bakat saya. Dengan keyakinan mereka, saya dapat membantu mereka menghindari segala macam kekacauan dan bencana.",
  ui_story_5089_50890402_69_dialog_content = "Ada juga mereka yang tidak percaya, mereka yang menertawakan ramalanku dan hanya melanjutkan hari mereka seperti biasa.",
  ui_story_5089_50890402_70_dialog_content = "Tapi untuk kamu meminta bantuan saya dan meragukannya dalam satu nafas, untuk kamu mencari petunjuk saya namun menolak untuk mengikutinya dengan tulus...",
  ui_story_5089_50890402_71_dialog_content = "Ini sama saja dengan meludahi seniku.",
  ui_story_5089_50890402_72_dialog_content = "... Tidakkah kamu pikir kamu mungkin sedikit berlebihan?",
  ui_story_5089_50890402_73_dialog_content = "Saya hampir tidak berpikir begitu.",
  ui_story_5089_50890402_74_dialog_content = "Jika saya berani bertanya, Lady Dantang, ketika dua batang pertama jatuh ke tangan Anda, Anda sudah berharap untuk hasil tertentu, bukan?",
  ui_story_5089_50890402_75_dialog_content = "...",
  ui_story_5089_50890402_76_dialog_content = "Saya bisa melihat saya tidak salah. Putri Zhuohua yang terhormat bukanlah orang yang akan menyerah pada takdir.",
  ui_story_5089_50890402_77_dialog_content = "Dan karena kamu sudah memutuskan, tidak ada gunanya lagi bermain-main.",
  ui_story_5089_50890402_78_dialog_content = "Namun, saya harus meminta Anda untuk membantu saya meletakkan kembali tongkat ramalan saya di tempatnya. Itu adalah tanda hormat profesional, bukan?",
  ui_story_5089_50890402_79_dialog_content = "Tuan Li.",
  ui_story_5089_50890402_80_dialog_content = "Tidak perlu panggilan hormat. Bukankah saya sudah menjelaskan hal itu barusan?",
  ui_story_5089_50890402_81_dialog_content = "Aku masih punya satu permintaan lagi untuk meminta.",
  ui_story_5089_50890402_82_dialog_content = "... Mohon maafku. Izinkan aku menarik kembali pernyataan sebelumnya.",
  ui_story_5089_50890402_83_dialog_content = "Sini, ulurkan tanganmu sekali lagi. Saya akan memastikan bahwa keberuntunganmu mengatakan untuk meninggalkan masalah ini.",
  ui_story_5089_50890402_84_dialog_content = "Itu tidak perlu. Lagipula, saya adalah Putri Zhuohua.",
  ui_story_5089_50890402_85_dialog_content = "Ketidakpercayaanku pada takdir diketahui oleh semua orang.",
  ui_story_5089_50890402_86_dialog_content = "Ah, ya, saya kira saya memang baru saja mengatakan itu.",
  ui_story_5089_50890402_87_dialog_content = "Seharusnya aku berhenti melakukan ini pada diri sendiri!",
  ui_story_5089_50890402_88_dialog_content = "*Hela nafas* Baiklah, jadi... Bagaimanapun juga, aku masih berutang budi padamu karena telah menyelamatkan hidupku.",
  ui_story_5089_50890402_89_dialog_content = "Lanjutkan, sebutkan favoritmu.",
  ui_story_5089_50890402_90_dialog_content = "Hei Dantang, saya menemukan layanan pengawalan bersenjata seperti yang Anda minta.",
  ui_story_5089_50890402_91_dialog_content = "Mereka setuju untuk mengembalikan emas putra mahkota ke ibu kota Kerajaan Ji.",
  ui_story_5089_50890402_92_dialog_content = "Jadi apa yang selanjutnya untuk kita? Haruskah kita juga pergi?",
  ui_story_5089_50890402_93_dialog_content = "Belum saja.",
  ui_story_5089_50890402_94_dialog_content = "Pemilik penginapan baru saja membawa dua paket teh segar, dan rasanya cukup luar biasa. Tidak ada salahnya menghabiskan beberapa menit lagi untuk menikmati teh kita, bukan?",
  ui_story_5089_50890402_95_dialog_content = "Kurasa tidak, tapi bisakah kita benar-benar mampu bersantai seperti ini?",
  ui_story_5089_50890402_96_dialog_content = "Jangan khawatir, ini tidak akan memakan waktu lama.",
  ui_story_5089_50890402_97_dialog_content = "Kamu disana, Jiu?",
  ui_story_5089_50890402_98_dialog_content = "... Ya, Yang Mulia.",
  ui_story_5089_50890402_99_dialog_content = "Kemarilah dan minumlah secangkir teh bersama kami. Saya ada hal yang ingin kuberitahu setelah kita selesai di sini.",
  ui_story_5089_50890402_100_dialog_content = "Baiklah.",
  ui_story_5089_50890402_101_dialog_content = "Teh ini benar-benar enak! Rasanya ringan tapi menyegarkan dan memiliki aroma buah yang biasanya tidak dimiliki teh lainnya.",
  ui_story_5089_50890402_102_dialog_content = "Oh, itu karena saya menambahkan \"bubuk penggigil darah,\" yang dibuat dari buah yang sedikit beracun.",
  ui_story_5089_50890402_103_dialog_content = "... Hah?",
  ui_story_5089_50890402_104_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5089_50890402_105_dialog_content = "<color=#e8d9bb>Tiba-tiba, Jiu jatuh berlutut.</color>",
  ui_story_5089_50890402_106_dialog_content = "J-Jiu...!",
  ui_story_5089_50890402_107_dialog_content = "Jangan khawatir, jenis obat ini hanya melumpuhkan anggota tubuh tanpa merusak tubuh itu sendiri. Ini akan hilang dengan sendirinya setelah beberapa waktu.",
  ui_story_5089_50890402_108_dialog_content = "Menariknya, efeknya lebih cepat dan lebih kuat pada mereka yang memiliki kekuatan batin dan kemampuan seni bela diri yang hebat.",
  ui_story_5089_50890402_109_dialog_content = "Oh, itu menjelaskan mengapa aku belum merasakan apa-apa... Tunggu, bukan itu intinya!",
  ui_story_5089_50890402_110_dialog_content = "Mengapa kamu melakukan hal seperti ini, Dantang?!",
  ui_story_5089_50890402_111_dialog_content = "Karena kita kehabisan waktu.",
  ui_story_5089_50890402_112_dialog_content = "Kebawah Duli, Squawk dan Jabber telah memberi tahu saya bahwa cukup banyak orang telah tiba di penginapan.",
  ui_story_5089_50890402_113_dialog_content = "Dan sepertinya tamu baru kita tidak datang dengan damai.",
  ui_story_5089_50890402_114_dialog_content = "Tianxian, bukan kamu juga... Tunggu, siapa sebenarnya kamu?!",
  ui_story_5089_50890402_115_dialog_content = "Jelas, aku satu-satunya Miss Jiu. Baik sedang beristirahat atau di jalan, itu tidak berubah.",
  ui_story_5089_50890402_116_dialog_content = "Ini bukan waktunya untuk menciptakan dirimu sendiri, Tianxian!",
  ui_story_5089_50890402_117_dialog_content = "Bukan juga saatnya untuk membuat keributan yang tidak perlu, bukan begitu menurutmu?",
  ui_story_5089_50890402_118_dialog_content = "Bisakah kamu benar-benar menyalahkan saya? Ini benar-benar konyol!",
  ui_story_5089_50890402_119_dialog_content = "Itu sudah cukup, temanku. Sekarang bantu aku menyembunyikan Miss Jiu di lemari pakaian di sana, dan cepat.",
  ui_story_5089_50890402_120_dialog_content = "Uh, tentu... Wah!",
  ui_story_5089_50890402_121_dialog_content = "Jiu, apa yang kamu...",
  ui_story_5089_50890402_122_dialog_content = "<color=#e8d9bb>Tubuh Jiu sedikit bergoyang saat dia menahan efek obat dengan sekuat tenaga. Suara tulangnya yang bergetar dari dalam hampir bisa didengar.</color>",
  ui_story_5089_50890402_123_dialog_content = "<color=#e8d9bb>Tiba-tiba, luka di tangannya terbuka lebar, merendam pakaiannya dengan darah segar.</color>",
  ui_story_5089_50890402_124_dialog_content = "<color=#e8d9bb>Dia memaksakan tubuhnya yang kaku bergerak cukup untuk mencengkeram ujung rok Dantang.</color>",
  ui_story_5089_50890402_125_dialog_content = "...",
  ui_story_5089_50890402_126_dialog_content = "<color=#e8d9bb>Dantang mundur, menarik roknya dari tangan berdarah Jiu.</color>",
  ui_story_5089_50890402_127_dialog_content = "Siang dan malam selama lima tahun terakhir, kamu selalu ada di sisiku. Aku sangat berterima kasih untuk semua yang telah kamu lakukan untukku, Jiu.",
  ui_story_5089_50890402_128_dialog_content = "Anda adalah orang yang baik, serta pelayan yang paling setia yang bisa diminta oleh siapa pun.",
  ui_story_5089_50890402_129_dialog_content = "Namun, tidak ada cara lagi untuk menjaga kedamaian kita.",
  ui_story_5089_50890402_130_dialog_content = "Aku tahu kamu tidak ingin menyakitiku, tapi kamu juga tidak akan pernah menentang perintah paman saya.",
  ui_story_5089_50890402_131_dialog_content = "Sebagai satu orang, kamu tidak bisa menempuh dua jalan yang berlawanan, atau menjadi pedang di tangan dua orang berbeda dengan tujuan yang bertentangan.",
  ui_story_5089_50890402_132_dialog_content = "Pangeran... Dantang...",
  ui_story_5089_50890402_133_dialog_content = "Sebenarnya, saya tidak berhak memberi Anda perintah sampai Anda membuat keputusan Anda.",
  ui_story_5089_50890402_134_dialog_content = "Hanya tahu bahwa jika kamu menolak untuk melakukannya, seseorang seperti saya akan akhirnya turun tangan dan mengambil hak itu darimu.",
  ui_story_5089_50890402_135_dialog_content = "Dengan menyerahkan kebebasan pilihanmu, kamu akan secara alami menjadi boneka yang bergantung pada belas kasihan orang lain.",
  ui_story_5089_50890402_136_dialog_content = "Situasi Anda saat ini seharusnya menjadi bukti dari itu.",
  ui_story_5089_50890402_137_dialog_content = "Jiu.",
  ui_story_5089_50890402_138_dialog_content = "Mulai saat ini, kamu sudah dibebaskan dari tugas sebagai penjaga Putri Zhuohua.",
  ui_story_5089_50890402_139_dialog_content = "!",
  ui_story_5089_50890402_140_dialog_content = "Saya tidak ingin dan tidak membutuhkan kamu seperti sekarang.",
  ui_story_5089_50890402_141_dialog_content = "Aku menolak untuk hidup di bawah perlindunganmu atau, lebih buruk lagi, pengawasanmu.",
  ui_story_5089_50890402_142_dialog_content = "Apa yang aku inginkan adalah...",
  ui_story_5089_50890402_143_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5089_50890402_144_dialog_content = "<color=#e8d9bb>Kata-kata terakhir Dantang tenggelam oleh suara keras dari luar.</color>",
  ui_story_5089_50890402_145_dialog_content = "Silahkan!",
  ui_story_5089_50890402_146_dialog_content = "?",
  ui_story_5089_50890402_147_dialog_content = "<color=#e8d9bb>Aku juga didorong masuk ke dalam lemari.</color>",
  ui_story_5089_50890402_148_dialog_content = "Maafkan aku karena egois mengambil tindakan dengan caraku sendiri, PlayerName.",
  ui_story_5089_50890402_149_dialog_content = "Aku menyerahkan Jiu dan segalanya di tanganmu sekarang.",
  ui_story_5089_50890402_150_dialog_content = "Tunggu, Dantang!",
  ui_story_5089_50890402_151_dialog_content = "<color=#e8d9bb>Pintu lemari berayun tertutup.</color>",
  ui_story_5089_50890402_152_dialog_content = "<color=#e8d9bb>Momen berikutnya, pintu ruangan tiba-tiba terbuka lebar.</color>",
  ui_story_5089_50890402_153_dialog_content = "Ah, akhirnya. Mendapatkan audiensi dengan Anda tidaklah mudah, Putri Zhuohua.",
  ui_story_5089_50890402_154_dialog_content = "(Suara itu!)",
  ui_story_5089_50890402_155_dialog_content = "Zhui Hu...",
  ui_story_5089_50890402_156_dialog_content = "Tampaknya Ministress Armilla benar: kamu sangat hidup dan sehat walafiat.",
  ui_story_5089_50890402_157_dialog_content = "Tentu saja. Bagaimanapun, aku tidak mungkin mati sebelum menciptakan Binatang Mekanik paling kuat di dunia.",
  ui_story_5089_50890402_158_dialog_content = "Saya tidak sempat bertanya sebelumnya, tetapi rumor tentang afiliasimu dengan Fate Riders jelas benar.",
  ui_story_5089_50890402_159_dialog_content = "Ya, tapi bukankah itu sangat normal? Siapa pun yang bersedia mendukung kerajinanku pantas disebut masterku.",
  ui_story_5089_50890402_160_dialog_content = "Namun, tidak mudah mendapatkan Zhuyin Flame sekali lagi. Saya sibuk mengembangkan sistem kekuatan baru untuk Stinger terbaru.",
  ui_story_5089_50890402_161_dialog_content = "Tapi pria-pria ini bersikeras menyeret saya ke sini untuk bertemu dengan kamu.",
  ui_story_5089_50890402_162_dialog_content = "Mereka memang berjanji akan memberiku sesuatu yang bagus untuk masalahku, namun.",
  ui_story_5089_50890402_163_dialog_content = "Mereka mengatakan bahwa jika kamu atau penjagamu melawan kami dengan cara apapun, aku bisa mencoba senjata terbaru ku padamu.",
  ui_story_5089_50890402_164_dialog_content = "Nah, apa kau keberatan untuk sedikit melawan? Bahkan yang paling kecil sekalipun sudah cukup, hehehe.",
  ui_story_5089_50890402_165_dialog_content = "Saya tidak melihat alasan untuk melakukannya.",
  ui_story_5089_50890402_166_dialog_content = "Saya adalah Putri Zhuohua dari Kerajaan Ye, dan selain kamu, sisanya dari prajurit ini adalah pelayan setia paman saya.",
  ui_story_5089_50890402_167_dialog_content = "Sebagai contoh, mereka tidak akan pernah menyakitiku dengan cara apa pun. Mereka hanya datang untuk menyambutku pulang, bukan Jiu?",
  ui_story_5089_50890402_168_dialog_content = "*Mengangguk*",
  ui_story_5089_50890402_169_dialog_content = "Sayang sekali, tapi lakukanlah apa yang kamu mau. Masih banyak yang harus dikerjakan di bengkelku, jadi ayo kita mulai.",
  ui_story_5089_50890402_170_dialog_content = "... Tunggu. Ada dua orang lagi yang bepergian bersama putri.",
  ui_story_5089_50890402_171_dialog_content = "Ya, tapi penipu peramal itu melarikan diri begitu melihat pasukanmu mendekat.",
  ui_story_5089_50890402_172_dialog_content = "Mengenai Caelestite, dia tidak mampu menyelesaikan apa pun sendiri, terutama di negeri asing. Kenapa kamu begitu khawatir tentang mereka?",
  ui_story_5089_50890402_173_dialog_content = "Perintah paman saya adalah untuk mengantarku kembali ke ibu kota, dan tidak ada orang lain. Apakah saya salah?",
  ui_story_5089_50890402_174_dialog_content = "Tidak, Yang Mulia... Ke sini, silakan.",
  ui_story_5089_50890402_175_dialog_content = "<color=#e8d9bb>Ruang itu kembali menjadi sunyi.</color>",
  ui_story_5089_50890402_176_dialog_content = "<color=#e8d9bb>Tapi kali ini, hanya Jiu dan aku yang tersisa.</color>",
  ui_story_5089_50890501_1_dialog_content = "... Apa yang mereka pikirkan?!",
  ui_story_5089_50890501_2_dialog_content = "Dia baru saja berbicara tentang berjuang untuk waktu yang lebih lama, dan sekarang dia langsung masuk ke dalam perangkap mereka!",
  ui_story_5089_50890501_3_dialog_content = "Bagaimana kita bisa menjaga keselamatan diri kita sendiri ketika seseorang seperti Zhui Hu terlibat?!",
  ui_story_5089_50890501_4_dialog_content = "Tidak ada yang masuk akal! Kamu juga berpikir begitu, kan, Jiu?",
  ui_story_5089_50890501_5_dialog_content = "Aku… aku tak tahu.",
  ui_story_5089_50890501_6_dialog_content = "Sepertinya Tuan Putri Dantang tidak lagi percaya padaku.",
  ui_story_5089_50890501_7_dialog_content = "Mungkin dia benar. Mungkin aku telah gagal dalam menjalankan tugas-tugasku.",
  ui_story_5089_50890501_8_dialog_content = "Tapi sekarang setelah aku bukan lagi penjaganya, aku tidak tahu apa yang harus dilakukan...",
  ui_story_5089_50890501_9_dialog_content = "Apa yang kamu bicarakan? Masih ada satu hal yang benar-benar harus dilakukan, ingat?",
  ui_story_5089_50890501_10_dialog_content = "Apa?",
  ui_story_5089_50890501_11_dialog_content = "Dantang mengatakan kita kehabisan waktu.",
  ui_story_5089_50890501_12_dialog_content = "Tapi dia tidak terburu-buru saat kita berada di kapal. Dia bahkan mengatakan dia bisa mengerti keraguan Anda.",
  ui_story_5089_50890501_13_dialog_content = "Namun, setelah semalam, terjadi sesuatu yang membuat sikapnya berubah.",
  ui_story_5089_50890501_14_dialog_content = "Apapun itu, pasti ada kaitannya dengan boneka itu.",
  ui_story_5089_50890501_15_dialog_content = "Bukan hanya itu, dia bilang dia akan meninggalkan sisanya padaku, meskipun dia tidak menjelaskan apa-apa...",
  ui_story_5089_50890501_16_dialog_content = "Dugaanku adalah kita perlu terus mencari petunjuk yang akan membawa kita ke Xuan Ji. Setelah kita menemukannya, saya yakin kita akan memahami hal-hal dengan jauh lebih baik.",
  ui_story_5089_50890501_17_dialog_content = "Kamu bisa berdebat dengan Dantang sebanyak yang kamu mau setelah kita melakukannya, Jiu.",
  ui_story_5089_50890501_18_dialog_content = "Bertengkar... dengan Yang Mulia? A-Aku tidak akan pernah melakukan sesuatu yang begitu lancang!",
  ui_story_5089_50890501_19_dialog_content = "Tapi, jelas dia bukan lagi tuanmu, 'kan?",
  ui_story_5089_50890501_20_dialog_content = "Meski begitu...",
  ui_story_5089_50890501_21_dialog_content = "Apapun situasinya, dia membuat keputusan ini sendiri tanpa berkonsultasi dengan kami berdua.",
  ui_story_5089_50890501_22_dialog_content = "Sejujurnya, bahkan aku sedikit kesal padanya.",
  ui_story_5089_50890501_23_dialog_content = "Bukan hanya meninggalkan aku di tempat yang hampir tidak aku ketahui apa-apa...",
  ui_story_5089_50890501_24_dialog_content = "Dia juga menempatkan saya dalam situasi di mana saya harus melihat teman-teman saya mempertaruhkan nyawa mereka untuk saya.",
  ui_story_5089_50890501_25_dialog_content = "Jadi, setelah semua kekacauan ini selesai, mari kita berikan dia sebagian dari pikiran kita.",
  ui_story_5089_50890501_26_dialog_content = "Kita akan memiliki percakapan panjang yang baik dengan sang putri tentang bagaimana cara memperlakukan teman-temannya dengan benar.",
  ui_story_5089_50890501_27_dialog_content = "PlayerName…",
  ui_story_5089_50890501_28_dialog_content = "Tapi sebelum kita melakukan itu, bisakah kamu memberikan dukunganmu padaku?",
  ui_story_5089_50890501_29_dialog_content = "Lagipula, hanya ada sedikit yang bisa kulakukan sendirian.",
  ui_story_5089_50890501_30_dialog_content = "Saya dibesarkan di bawah perintah Raja Ye. Mengayunkan pedang dan mengikuti perintah adalah semua yang saya tahu.",
  ui_story_5089_50890501_31_dialog_content = "Tapi jika kemampuan saya dapat dimanfaatkan dengan baik, PlayerName, silakan perintahkan saya sesuai keinginan Anda.",
  ui_story_5089_50890501_32_dialog_content = "Uh tentu, tapi mari kita mulai dengan sedikit mengubah pola pikir itu...",
  ui_story_5089_50890501_33_dialog_content = "Ingatlah bahwa kita adalah teman dan selalu saling membantu. Cukup sederhana, bukan?",
  ui_story_5089_50890501_34_dialog_content = "... Aku belum pernah punya teman sebelumnya.",
  ui_story_5089_50890501_35_dialog_content = "Saya tidak akan membiarkan Dantang mendengar kamu mengatakan itu, atau dia akan lebih marah daripada kita!",
  ui_story_5089_50890501_36_dialog_content = "Yang Mulia Lady Dantang lahir dari garis keturunan yang tinggi dan bangsawan! Bagaimana mungkin dia bisa berteman dengan seseorang seperti saya?! Saya—",
  ui_story_5089_50890501_37_dialog_content = "Baiklah, aku mengerti. Obatnya masih belum habis, jadi berikan saja tanganku dan lakukan dengan perlahan.",
  ui_story_5089_50890501_38_dialog_content = "Ayo, kita menuju ibukota bersama-sama.",
  ui_story_5089_50890502_1_dialog_content = "Mengaum-",
  ui_story_5089_50890502_2_dialog_content = "Roh jahat telah dibersihkan, PlayerName.",
  ui_story_5089_50890502_3_dialog_content = "Kita tidak terlalu jauh dari kota, 'kan?",
  ui_story_5089_50890502_4_dialog_content = "Ada banyak desa lain di sekitar sini juga, dan ibu kota kerajaan kurang dari setengah jam jauhnya.",
  ui_story_5089_50890502_6_dialog_content = "Hmm…",
  ui_story_5089_50890502_8_dialog_content = "Mudah-mudahan ini hanya kebetulan. Kami tidak punya waktu untuk menghadapi masalah lain sekarang... Mari kita terus bergerak.",
  ui_story_5089_50890502_9_dialog_content = "Aku mengerti.",
  ui_story_5089_50890502_10_dialog_content = "Apakah ada sesuatu di sana?",
  ui_story_5089_50890502_11_dialog_content = "?",
  ui_story_5089_50890502_12_dialog_content = "Maaf, rasanya seperti tatapanmu terus melayang ke sana.",
  ui_story_5089_50890502_13_dialog_content = "Itu desa tempat saya tinggal ketika saya masih muda.",
  ui_story_5089_50890502_14_dialog_content = "Kampung halamanmu, huh? Apakah kamu ingin kembali dan melihatnya?",
  ui_story_5089_50890502_15_dialog_content = "Tidak perlu. Saya sudah kehilangan keluarga saya lama sekali, dan saya tidak terlalu akrab dengan penduduk desa lainnya.",
  ui_story_5089_50890502_16_dialog_content = "Selain itu, dua pondok yang tersisa hampir tidak bisa disebut rumah lagi.",
  ui_story_5089_50890502_17_dialog_content = "Kami memiliki masalah yang lebih penting di tangan.",
  ui_story_5089_50890502_18_dialog_content = "Lihat ke sana, PlayerName. Di depanmu adalah ibukota Kerajaan Ye: Kota Jingliang.",
  ui_story_5089_50890502_19_dialog_content = "...",
  ui_story_5089_50890502_20_dialog_content = "(Saya pikir setelah melihat emas dan jade di istana Kerajaan Ji, saya tidak akan terkejut dengan apa pun lagi di Longzhou.)",
  ui_story_5089_50890502_21_dialog_content = "(Tapi di Kota Jingliang, mesin berbentuk naga menyemburkan kabut dari atap-atap, sementara phoenix tembaga mengirim pesan ke seluruh kota.)",
  ui_story_5089_50890502_22_dialog_content = "<color=#e8d9bb>Jalanan lebar dan ramai saat asap dan api meletus dari banyak bengkel.</color>",
  ui_story_5089_50890502_23_dialog_content = "<color=#e8d9bb>Alih-alih hiasan mewah dan keindahan alam yang mewah, Kota Jingliang ditandai dengan nuansa metalik dan energi berdenyut dari kerajinan tangan yang cerdas.</color>",
  ui_story_5089_50890502_24_dialog_content = "<color=#e8d9bb>Gruduk!</color>",
  ui_story_5089_50890502_25_dialog_content = "A-Apa itu tadi?!",
  ui_story_5089_50890502_26_dialog_content = "Hanya suara dari Carrier Huolong.",
  ui_story_5089_50890502_27_dialog_content = "PlayerName, apakah kamu melihat sesuatu yang tidak biasa tentang jalan-jalan di sini?",
  ui_story_5089_50890502_28_dialog_content = "Kamu sedang berbicara tentang dua jejak logam yang tertanam di tanah, bukan? Saya telah melihatnya dari waktu ke waktu.",
  ui_story_5089_50890502_29_dialog_content = "Mereka sangat mirip dengan sesuatu yang pernah kulihat sebelumnya...",
  ui_story_5089_50890502_30_dialog_content = "Carrier Huolong dirancang untuk istana kerajaan bertahun-tahun yang lalu oleh seorang penemu hebat yang dikenal sebagai Tuan Houfeng.",
  ui_story_5089_50890502_31_dialog_content = "Dengan menggabungkan Seni Kekuatan Air dan Api sebagai sumber energinya, Carrier Huolong mampu mengangkut jumlah kargo massal tanpa kehilangan mobilitasnya.",
  ui_story_5089_50890502_32_dialog_content = "Kekurangan utamanya adalah konsumsi energi yang berlebihan dan keterbatasannya pada trek yang sangat spesifik.",
  ui_story_5089_50890502_33_dialog_content = "Sebagai hasilnya, pengadilan kerajaan bertanggung jawab atas sebagian besar perencanaan dan infrastrukturnya, sementara pemilik bengkel yang lebih besar mendukung pembangunannya melalui pendanaan.",
  ui_story_5089_50890502_34_dialog_content = "Sebagai imbalan atas bantuan dengan jejak Carrier Huolong, pemilik bengkel juga diberi prioritas saat mengangkut barang dan bahan.",
  ui_story_5089_50890502_35_dialog_content = "Seperti yang kupikirkan... Itu kereta uap, bukan?!",
  ui_story_5089_50890502_36_dialog_content = "\"Kereta api uap\"? Apa itu?",
  ui_story_5089_50890502_37_dialog_content = "Pikirkan itu sebagai versi Astra sendiri dari Huolong Carrier. Saya terkesan bahwa Lord Houfeng mampu menciptakan sesuatu seperti itu juga!",
  ui_story_5089_50890502_38_dialog_content = "Putri Dantang pernah mengatakan sesuatu yang serupa di masa lalu.",
  ui_story_5089_50890502_39_dialog_content = "Dia percaya bahwa dengan ciptaannya, bakatnya pasti sebanding dengan Lady Xuan Ji.",
  ui_story_5089_50890502_40_dialog_content = "Pada suatu titik, mereka mengatakan dia sedang mengembangkan semacam layang-layang raksasa yang bisa mengangkut orang ke dan dari tanah yang jauh.",
  ui_story_5089_50890502_41_dialog_content = "Sayangnya, karena konflik politik dalam kerajaan, dia menghilang tanpa jejak dan penelitiannya akhirnya dihentikan.",
  ui_story_5089_50890502_42_dialog_content = "Sayang sekali. Saya yakin itu pasti akan sama mengesankannya dengan Huolong Carrier-nya, jika tidak lebih.",
  ui_story_5089_50890502_43_dialog_content = "Sepertinya kamu tahu banyak tentang ini, Jiu. Saya tidak menyangka kamu tertarik dengan hal semacam ini?",
  ui_story_5089_50890502_44_dialog_content = "Ini hanya karena Yang Mulia memberi tahu saya banyak tentang itu.",
  ui_story_5089_50890502_45_dialog_content = "Dia juga menyesali dirinya yang terlalu muda dan naif saat itu, jika tidak dia pasti akan menemukan cara untuk mempertahankan penemu berbakat seperti itu.",
  ui_story_5089_50890502_46_dialog_content = "Heh, itu pasti terdengar seperti Dantang.",
  ui_story_5089_50890502_47_dialog_content = "Baiklah, Jiu, ayo kita berusaha sebaik mungkin untuk menemukan cara melakukannya.",
  ui_story_5089_50890502_48_dialog_content = "Kita perlu menjaga Kerajaan Ye agar tidak kehilangan penemu brilian seperti Xuan Ji dan Putri Zhuohua yang setia.",
  ui_story_5089_50890502_49_dialog_content = "Pertama, kita harus mencari cara untuk bertemu dengan mereka...",
  ui_story_5089_50890502_50_dialog_content = "Penjahat yang ditangkap oleh pengawal pribadi raja biasanya ditahan di Penjara Langit di tepi luar istana.",
  ui_story_5089_50890502_51_dialog_content = "Meski dilindungi oleh legiun prajurit, bahkan jika aku jatuh, aku yakin kamu akan berhasil menyelamatkan Lady Xuan Ji dari penjara, PlayerName.",
  ui_story_5089_50890502_52_dialog_content = "Ke-Kenapa kita mulai dengan strategi paling agresif?!",
  ui_story_5089_50890502_53_dialog_content = "PlayerName, ketika kamu meminta bantuan saya, bukankah maksudmu agar saya menjadi pedangmu?",
  ui_story_5089_50890502_54_dialog_content = "Aku tidak berusaha menjadi musuh pengadilan, Jiu! Dan tentu saja aku tidak berencana mengirimmu untuk mati!",
  ui_story_5089_50890502_55_dialog_content = "Pasti ada cara lain. Mari kita periksa Penjara Langit itu dulu.",
  ui_story_5089_50890502_56_dialog_content = "Jika mereka melukai Xuan Ji dengan cara apa pun... Itulah saatnya kita menggunakan cara terakhir kita.",
  ui_story_5089_50890502_57_dialog_content = "Saya ingin bertanya, Jiu. Apakah banyak orang yang mengenalmu di Kota Jingliang?",
  ui_story_5089_50890502_58_dialog_content = "Mungkin. Sebagai penjaga raja, saya melayaninya kebanyakan di bayangan dan hanya berinteraksi dengan pengawal lainnya sesuai kebutuhan.",
  ui_story_5089_50890502_59_dialog_content = "Beberapa orang mungkin mengenaliku dari topengku, tetapi tidak banyak lagi. Bahkan, mereka mungkin tidak tahu apakah saya seorang pria atau wanita.",
  ui_story_5089_50890502_60_dialog_content = "Bagaimanapun, mereka hanya menyebutku \"iblis bertopeng\" ketika mereka membicarakanku di belakangku.",
  ui_story_5089_50890502_61_dialog_content = "Tapi jika kamu pikir itu akan membantu, PlayerName...",
  ui_story_5089_50890502_62_dialog_content = "Kurasa ini harus dilakukan.",
  ui_story_5089_50890502_63_dialog_content = "Uh, tentu saja... Entah kenapa, aku merasa kamu tampak lebih mencolok sekarang.",
  ui_story_5089_50890502_64_dialog_content = "Seperti yang kupikir, wajahku memang tampak tak tertahankan... Aku akan segera mencari sesuatu untuk menutupinya.",
  ui_story_5089_50890502_65_dialog_content = "M-Maksudku bukan itu! Darimana kamu mendapatkan ide itu?! Kenyataannya, penampilanmu sebenarnya sangat... Uh...",
  ui_story_5089_50890502_66_dialog_content = "Sangat indah!",
  ui_story_5089_50890502_67_dialog_content = "?",
  ui_story_5089_50890502_68_dialog_content = "Er, sudahlah. Tidak ada waktu untuk dibuang, jadi mari kita terus bergerak.",
  ui_story_5089_50890502_69_dialog_content = "Tempat ini berada di bawah yurisdiksi istana kerajaan. Jika kamu tidak punya urusan di sini, maka pergilah sekarang juga.",
  ui_story_5089_50890502_70_dialog_content = "Tebakan pendekatan langsung ternyata tidak mungkin.",
  ui_story_5089_50890502_71_dialog_content = "Maka izinkan saya untuk menyusup ke dalam gedung...",
  ui_story_5089_50890502_72_dialog_content = "M-Mari kita simpan itu untuk terakhir!",
  ui_story_5089_50890502_73_dialog_content = "Benar, saya masih memiliki burung mekanik Xuan Ji bersama saya. Mungkin saya bisa menggunakannya untuk berkomunikasi dengannya jika kita bisa mengalihkan perhatian para soldiers.",
  ui_story_5089_50890502_74_dialog_content = "Maka izinkan aku untuk mengalihkan perhatian para prajurit—",
  ui_story_5089_50890502_75_dialog_content = "Tunggu—Oh tidak!",
  ui_story_5089_50890502_76_dialog_content = "<color=#e8d9bb>Untuk kejutan mereka, burung mekanik tiba-tiba hidup dan terbang.</color>",
  ui_story_5089_50890502_77_dialog_content = "<color=#e8d9bb>Seolah mengikuti program yang telah ditentukan, ia langsung menuju gerbang istana mencari Xuan Ji...</color>",
  ui_story_5089_50890502_78_dialog_content = "Kita sudah selesai... Huh?",
  ui_story_5089_50890502_79_dialog_content = "<color=#e8d9bb>Seberkas cahaya emas berkilauan dari sumber yang tidak diketahui.</color>",
  ui_story_5089_50890502_80_dialog_content = "<color=#e8d9bb>Dua prajurit itu, tampaknya tidak menyadarinya, membiarkan Clockwork Bird melewati gerbang.</color>",
  ui_story_5089_50890502_81_dialog_content = "... Apakah kamu masih membutuhkanku untuk mengalihkan perhatian prajurit?",
  ui_story_5089_50890502_82_dialog_content = "Hmm…",
  ui_story_5089_50890502_83_dialog_content = "<color=#e8d9bb>Tiba-tiba, suara samar dapat terdengar dari balik gerbang istana.</color>",
  ui_story_5089_50890502_84_dialog_content = "Maafkan saya, tetapi bolehkah saya bertanya apakah ada tamu terhormat yang sedang menunggu di luar?",
  ui_story_5089_50890502_85_dialog_content = "Eh, siapa kamu?",
  ui_story_5089_50890502_86_dialog_content = "Hanya seorang pembantu rendahan, tuan. Sekarang, silakan ikuti saya.",
  ui_story_5089_50890502_87_dialog_content = "Lady Xuan Ji sudah menunggu kamu.",
  ui_story_5089_50890502_88_dialog_content = "Selamat datang, PlayerName. Kita belum bertemu sejak musim semi lalu, bukan?",
  ui_story_5089_50890502_89_dialog_content = "Dan kamu juga, Jiu. Kamu baik-baik saja akhir-akhir ini?",
  ui_story_5089_50890502_90_dialog_content = "Ini adalah Xuan Ji yang asli! Apakah kamu baik-baik saja? Mereka tidak menyakitimu, kan?!",
  ui_story_5089_50890502_91_dialog_content = "Tentu saja tidak—Ugh, rel-rel ini sangat mengganggu. Tunggu sebentar, ya.",
  ui_story_5089_50890502_92_dialog_content = "... Hah?",
  ui_story_5089_50890502_93_dialog_content = "Ayo, duduklah! Kamu belum makan siang, 'kan? Jika belum, kamu datang pada waktu yang tepat!",
  ui_story_5089_50890502_94_dialog_content = "Fixit, Crafty, pergi lihat apa yang ada di dapur istana hari ini.",
  ui_story_5089_50890502_95_dialog_content = "Saya menang taruhan melawan Jie Gaoqing, dan dia berjanji akan membawakan saya ikan segar hari ini.",
  ui_story_5089_50890502_96_dialog_content = "Beritahu koki untuk mengukusnya dan sajikan dengan saus kacang hitam.",
  ui_story_5089_50890502_97_dialog_content = "Baiklah.",
  ui_story_5089_50890502_98_dialog_content = "Uh, Xuan Ji...? Apa yang terjadi di sini?",
  ui_story_5089_50890502_99_dialog_content = "Oh jangan khawatir, makanan di istana ini sangat lezat. Hanya saja sulit mendapatkan sesuatu yang segar di sini, itu saja.",
  ui_story_5089_50890502_100_dialog_content = "...",
  ui_story_5089_50890502_101_dialog_content = "Tiba-tiba, aku merasa seperti tekad kita untuk membantu kamu kabur dari penjara adalah lelucon belaka.",
  ui_story_5089_50890502_102_dialog_content = "Apakah kamu bahkan ditangkap di tempat pertama? Apakah ini bahkan penjara, untuk urusan itu?!",
  ui_story_5089_50890502_103_dialog_content = "Hahaha, tentu saja! Tidak bisakah kamu lihat betapa kosongnya labu anggurku?",
  ui_story_5089_50890502_104_dialog_content = "Tapi ingat, aku pernah menjadi anggota terhormat di istana kerajaan. Aku masih memiliki banyak teman di dalam, termasuk beberapa rekan kerja yang sangat peduli dengan keamananku.",
  ui_story_5089_50890502_105_dialog_content = "Selain itu, tidak peduli seberapa besar raja mungkin membenci saya, menghukum saya tanpa secara formal menghukum saya terlebih dahulu tidak akan benar.",
  ui_story_5089_50890502_106_dialog_content = "Sayangnya, karena aku masih ditahan sebagai pidana, mereka tidak akan memberiku apa pun yang lebih kuat dari teh biasa. Semoga kamu tidak keberatan!",
  ui_story_5089_50890502_107_dialog_content = "Nyonya Jiu, PlayerName.",
  ui_story_5089_50890502_108_dialog_content = "Perjalanan ke sini pasti cukup sulit. Izinkan saya mengangkat cangkir teh ini sebagai penghormatan untuk Anda.",
  ui_story_5089_50890502_109_dialog_content = "Terima kasih atas pertimbangan baik Anda.",
  ui_story_5089_50890502_110_dialog_content = "Aku tidak pernah menyangka bahwa harta terbesar dari perjalanan ku ke Astra bukanlah Zhuyin Flame, tetapi teman-teman yang aku temui sepanjang jalan.",
  ui_story_5089_50890502_111_dialog_content = "T-Tidak perlu begitu formal, Xuan Ji...",
  ui_story_5089_50890502_112_dialog_content = "Tapi itu mengingatkanku! Apakah kamu tahu siapa yang memiliki Api Zhuyin sekarang? Karena Dantang adalah—",
  ui_story_5089_50890502_113_dialog_content = "Ssst.",
  ui_story_5089_50890502_114_dialog_content = "Jangan lupa, saya hanya seorang tahanan sekarang. Tidak ada gunanya memberi tahu saya tentang dunia di luar sel saya.",
  ui_story_5089_50890502_115_dialog_content = "Dan selain itu, saya memiliki segala yang saya inginkan di sini. Sangat nyaman sehingga hampir bisa membuat saya lupa tentang masalah hidup saya.",
  ui_story_5089_50890502_116_dialog_content = "Mengapa aku harus peduli tentang hal lain?",
  ui_story_5089_50890502_117_dialog_content = "Pembohong.",
  ui_story_5089_50890502_118_dialog_content = "Oh?",
  ui_story_5089_50890502_119_dialog_content = "Tidak ada satu pun bagian mesin di sini, bukan?",
  ui_story_5089_50890502_120_dialog_content = "Siapa yang waras akan percaya bahwa Xuan Ji yang terkenal akan merasa tempat ini nyaman sekalipun?",
  ui_story_5089_50890502_121_dialog_content = "Ha ha ha, seperti biasa, sangat langsung, PlayerName.",
  ui_story_5089_50890502_122_dialog_content = "Lalu tolong dengarkan baik-baik.",
  ui_story_5089_50890502_123_dialog_content = "Raja sendiri yang memerintahkan penangkapanku, dan sekarang nasibku sepenuhnya ada di tangannya.",
  ui_story_5089_50890502_124_dialog_content = "Bahkan jika aku berhasil melarikan diri dengan mengandalkan keahlian bela diri Miss Jiu yang superior, nama baikku tetap akan ternoda dan kata-kataku tidak akan pernah diterima.",
  ui_story_5089_50890502_125_dialog_content = "Tapi kamu pasti tahu sesuatu tentang semua ini, 'kan? Apa yang harus kita lakukan sekarang?",
  ui_story_5089_50890502_126_dialog_content = "Sekarang bukan waktunya mempertimbangkan \"apa yang harus dilakukan.\"",
  ui_story_5089_50890502_127_dialog_content = "Meskipun bukan tempat saya untuk berkomentar tentang urusan eksternal, saya pernah menjabat sebagai seorang strategis untuk beberapa waktu, jadi saya bisa berbagi beberapa pengalaman saya dengan Anda.",
  ui_story_5089_50890502_128_dialog_content = "Misalnya, jika kamu ingin mencapai sesuatu tetapi tidak memiliki kekuatan dan visi untuk melakukannya, kamu harus mengandalkan strategi dan taktik untuk maju.",
  ui_story_5089_50890502_129_dialog_content = "Pilihan terbaik akan selalu adalah bergerak dengan tujuan dan mendapatkan momentum.",
  ui_story_5089_50890502_130_dialog_content = "Bergeraklah mengikuti arus keadaanmu, dan langit akan menuntun jalurmu.",
  ui_story_5089_50890502_131_dialog_content = "Tetapi ingat, Anda harus terlebih dahulu memperluas cakrawala Anda untuk mengetahui arah gelombang yang mengancam.",
  ui_story_5089_50890502_132_dialog_content = "Hanya dengan begitu Anda akan dapat membangun momentum ketika peluang itu muncul.",
  ui_story_5089_50890502_133_dialog_content = "Mirip seperti makhluk mekanik, bahkan putaran terkecil dari roda gigi dapat menggerakkan seluruh tubuh.",
  ui_story_5089_50890502_134_dialog_content = "Dan bahkan tindakan yang paling sederhana sekalipun membutuhkan koordinasi dari beberapa bagian.",
  ui_story_5089_50890502_135_dialog_content = "Kamu tidak pernah tahu komponen kecil mana yang mungkin gagal, menyebabkan seluruh mesin runtuh.",
  ui_story_5089_50890502_136_dialog_content = "Tapi... Aku bahkan tidak tahu harus mencari di mana.",
  ui_story_5089_50890502_137_dialog_content = "Kalau begitu, mari kita mulai dengan melihat sekeliling kita, ya?",
  ui_story_5089_50890502_138_dialog_content = "Misalnya, sekarang ini hanya kalian berdua yang berdiri di depan saya. Bukankah itu sudah tampak seperti bagian yang disengaja dari rencana orang lain?",
  ui_story_5089_50890502_139_dialog_content = "!",
  ui_story_5089_50890502_140_dialog_content = "Selain itu, kita sudah mengenal Miss Jiu di sini cukup lama sekarang...",
  ui_story_5089_50890502_141_dialog_content = "Tapi apakah kamu benar-benar tahu dari mana dia berasal?",
  ui_story_5089_50890502_142_dialog_content = "Lady Xuan Ji, makanan sudah siap.",
  ui_story_5089_50890502_143_dialog_content = "Pengawal raja tiba-tiba muncul baru saja, mengklaim bahwa mereka ingin membawamu untuk diinterogasi.",
  ui_story_5089_50890502_144_dialog_content = "Crafty sedang menghalangi mereka saat kita berbicara,, tapi aku khawatir dia tidak akan bisa menjauhkan mereka untuk waktu yang lama...",
  ui_story_5089_50890502_145_dialog_content = "Aku mengerti.",
  ui_story_5089_50890502_146_dialog_content = "Interogasi tepat ketika kami akan makan siang. Waktunya tidak bisa lebih buruk lagi!",
  ui_story_5089_50890502_147_dialog_content = "Berkat mereka, PlayerName dan Nona Jiu harus melewatkan ikan kukus yang lezat ini.",
  ui_story_5089_50890502_148_dialog_content = "Ah, tapi begitulah kehidupan seorang tahanan, saya kira.",
  ui_story_5089_50890502_149_dialog_content = "... Bagaimana kalau kalian ikut saja dengan kami, Xuan Ji?",
  ui_story_5089_50890502_150_dialog_content = "Kami sudah melihatnya sendiri sebelumnya. Pengawal raja juga bersekutu dengan Zhui Hu, dan mereka—",
  ui_story_5089_50890502_151_dialog_content = "Fixit, tolong antar tamu-tamu kami keluar.",
  ui_story_5089_50890502_152_dialog_content = "Xuan Ji!",
  ui_story_5089_50890502_153_dialog_content = "Cukup sudah, sekarang pergilah. Kita masing-masing punya urusan sendiri untuk diurus, bukan?",
  ui_story_5089_50890502_154_dialog_content = "Saya memiliki kepercayaan penuh padamu, PlayerName.",
  ui_story_5089_50890502_155_dialog_content = "Kamu pasti akan menemukan momentummu dalam waktu dekat.",
  ui_story_5089_50890601_1_dialog_content = "<color=#e8d9bb>Fixit pergi setelah mengantar kami keluar dari kota dengan kereta.</color>",
  ui_story_5089_50890601_2_dialog_content = "Sepertinya hanya kita berdua lagi, Jiu.",
  ui_story_5089_50890601_3_dialog_content = "Xuan Ji mengatakan begitu banyak, tapi apa arti dari semua itu ...?",
  ui_story_5089_50890601_4_dialog_content = "<color=#e8d9bb>Menggeram-</color>",
  ui_story_5089_50890601_5_dialog_content = "...",
  ui_story_5089_50890601_6_dialog_content = "Sekarang setelah saya memikirkannya, kita belum makan sama sekali hari ini.",
  ui_story_5089_50890601_7_dialog_content = "Saya akan pergi bertanya apakah ada penduduk desa yang bersedia memberi makan kami sebagai ganti pembayaran.",
  ui_story_5089_50890601_8_dialog_content = "Tolong tunggu di sini, PlayerName.",
  ui_story_5089_50890601_9_dialog_content = "Oke... Hah?",
  ui_story_5089_50890601_10_dialog_content = "Apakah benar ada desa di sekitar sini?",
  ui_story_5089_50890601_11_dialog_content = "Beras telah dijual dengan harga yang lebih tinggi akhir-akhir ini, yang jarang terjadi di daerah ini, jadi saya menjual semua beras saya kepada beberapa pedagang yang lewat dari Kerajaan Ji.",
  ui_story_5089_50890601_12_dialog_content = "Sayangnya, saya hanya memiliki sedikit bubur yang dibuat dari beras merah tua keluarga kami. Itu tidak banyak, tetapi saya harap Anda menyukainya...",
  ui_story_5089_50890601_13_dialog_content = "Kami sama sekali tidak keberatan! Kami belum makan sepanjang hari, jadi makanan adalah berkah.",
  ui_story_5089_50890601_14_dialog_content = "Maaf, tapi apakah ada alasan kamu tidak makan? Apakah kamu ingin sesuatu yang lain untuk menemani buburmu?",
  ui_story_5089_50890601_15_dialog_content = "Tidak, terima kasih. Saat ini aku tidak membutuhkan makanan.",
  ui_story_5089_50890601_16_dialog_content = "Sekarang, sekarang, itu tidak bisa! Tubuhmu tidak akan bisa bertahan tanpa makanan yang layak, tahu?",
  ui_story_5089_50890601_17_dialog_content = "Seperti yang saya katakan, saya tidak memerlukan makanan sekarang. Saya telah bertahan tanpa makan selama berhari-hari dalam misi, yang tidak pernah mempengaruhi kemampuan pedang saya.",
  ui_story_5089_50890601_18_dialog_content = "Lebih lagi, aku lebih memilih untuk tidak menakuti siapa pun dengan penampilanku.",
  ui_story_5089_50890601_19_dialog_content = "Tentang itu...",
  ui_story_5089_50890601_20_dialog_content = "Topeng dan cara bicaramu sedikit familiar... Tunggu! Jiu-mei... Apakah itu kamu?",
  ui_story_5089_50890601_21_dialog_content = "\"Jiu-mei\"?",
  ui_story_5089_50890601_22_dialog_content = "... Iya.",
  ui_story_5089_50890601_23_dialog_content = "Sudah beberapa waktu, Paman Li.",
  ui_story_5089_50890601_24_dialog_content = "Sungguh luar biasa! Aku tidak bisa percaya kamu masih hidup!",
  ui_story_5089_50890601_25_dialog_content = "Setelah orang tua Anda meninggal begitu tragis tahun itu, bahkan pihak berwenang yakin bahwa Anda meninggal bersama mereka!",
  ui_story_5089_50890601_26_dialog_content = "Saat itu kamu masih anak-anak! Wah, betapa kamu sudah tumbuh, Jiu-mei!",
  ui_story_5089_50890601_27_dialog_content = "Bagaimana kabarmu selama bertahun-tahun ini, Gadisku...?",
  ui_story_5089_50890601_28_dialog_content = "Saya baik-baik saja, Paman Li. Seorang pria baik telah merawat saya dan memberi saya kehidupan yang baik.",
  ui_story_5089_50890601_29_dialog_content = "Bagus, bagus! Mendengar itu membuat hatiku berbunga-bunga dengan kegembiraan!",
  ui_story_5089_50890601_30_dialog_content = "Kemari, duduk dan makan bubur! Tunggu di sini sementara Paman Li mengambilkanmu sayuran acar!",
  ui_story_5089_50890601_31_dialog_content = "Ini pasti kampung halamanmu, 'kan, Jiu?",
  ui_story_5089_50890601_32_dialog_content = "Dalam arti tertentu, ya.",
  ui_story_5089_50890601_33_dialog_content = "Keluarga saya awalnya tinggal di desa yang lebih terpencil lagi. Kami pindah ke sini untuk menghindari bencana.",
  ui_story_5089_50890601_34_dialog_content = "Sebuah bencana?",
  ui_story_5089_50890601_35_dialog_content = "Ya. Waktu itu aku belum genap sepuluh tahun, jadi aku tidak ingat banyak detail.",
  ui_story_5089_50890601_36_dialog_content = "Saya percaya seorang bangsawan tertentu menyukai wajahku, dan ingin membeliku untuk dijadikan sebagai pelayan.",
  ui_story_5089_50890601_37_dialog_content = "Tapi ketika orang tua saya menolak, dia dan anak buahnya mulai melecehkan kami di setiap kesempatan. Akhirnya, kami melarikan diri ke tempat ini.",
  ui_story_5089_50890601_38_dialog_content = "Setelah itu, orang tuaku memaksa aku untuk memakai topeng dan menyuruhku memberitahu semua orang bahwa aku tampak seperti iblis, tidak layak dilihat oleh orang lain.",
  ui_story_5089_50890601_39_dialog_content = "Itu... tidak bisa dipercaya...",
  ui_story_5089_50890601_40_dialog_content = "Aku tidak keberatan memakainya. Lagipula, wajahku menyebabkan keluargaku menderita, dan aku memang bukan tipe orang yang suka berbicara dengan orang lain.",
  ui_story_5089_50890601_41_dialog_content = "Jika ada, orang tua saya merasa lebih menyesal daripada saya.",
  ui_story_5089_50890601_42_dialog_content = "Setiap kali anak-anak desa lain memanggilku aneh, ibuku memeluk dan menyanyikan lagu untukku.",
  ui_story_5089_50890601_43_dialog_content = "Dan ayahku akan memberiku melon manis yang tidak tega dia makan sendiri.",
  ui_story_5089_50890601_44_dialog_content = "Lalu lagu pengantar tidur yang kau nyanyikan tadi... Itu dibuat khusus untukmu, bukan? Ayah dan ibumu pasti sangat menyayangimu.",
  ui_story_5089_50890601_45_dialog_content = "Bisakah saya bertanya apa yang terjadi pada mereka?",
  ui_story_5089_50890601_46_dialog_content = "Ada gunung tepat di barat desa ini. Kamu menyadarinya sebelumnya, 'kan PlayerName?",
  ui_story_5089_50890601_47_dialog_content = "Uh... Yang mana lagi?",
  ui_story_5089_50890601_48_dialog_content = "Ayo. Kita akan bicara di luar.",
  ui_story_5089_50890601_49_dialog_content = "Jiu-mei... Apakah kamu dan temanmu akan pergi begitu cepat?",
  ui_story_5089_50890601_50_dialog_content = "Ya, Paman Li. Kami ingin mengunjungi tambang di sana.",
  ui_story_5089_50890601_51_dialog_content = "Baiklah, tapi kamu harus tahu bahwa tambang itu sudah habis hanya beberapa tahun lalu, dan semua pekerja juga sudah pergi.",
  ui_story_5089_50890601_52_dialog_content = "Sebuah workshop besar dibangun di lahan tersebut setelahnya, tetapi tampaknya tidak ada yang mencolok yang dihasilkan di sana.",
  ui_story_5089_50890601_53_dialog_content = "Salah satu pemuda di desa kami pergi ke sana mencari pekerjaan, tetapi tidak ada satu pun jiwa di sana. Dari apa yang kami kumpulkan, tempat itu telah ditinggalkan untuk beberapa waktu.",
  ui_story_5089_50890601_54_dialog_content = "Satu hal lagi, Jiu-mei...",
  ui_story_5089_50890601_55_dialog_content = "Ya?",
  ui_story_5089_50890601_56_dialog_content = "I-Ini bukan hal yang terlalu penting... Hanya saja, kita semua telah berjuang selama beberapa tahun terakhir.",
  ui_story_5089_50890601_57_dialog_content = "Tapi, kamu cukup beruntung untuk menemukan kehidupan yang baik, jadi tolong... Hiduplah dengan baik dan bahagia.",
  ui_story_5089_50890601_58_dialog_content = "Jika orang tuamu bisa melihatmu sekarang, saya yakin mereka juga akan sangat gembira melihatmu.",
  ui_story_5089_50890601_59_dialog_content = "... Baiklah.",
  ui_story_5089_50890601_60_dialog_content = "Apakah itu gunung yang kamu sebutkan sebelumnya, Jiu?",
  ui_story_5089_50890601_61_dialog_content = "Ya. Sebelum raja kami naik takhta, semua tanah ini, termasuk milikku, adalah wilayahnya.",
  ui_story_5089_50890601_62_dialog_content = "Dia mendirikan kamp kerja di kaki gunung, di mana dia akan mempekerjakan pengungsi dan tahanan.",
  ui_story_5089_50890601_63_dialog_content = "Suatu hari, dua pengikut raja sedang mengawal seorang narapidana hukuman mati ke kamp kerja, tetapi mereka menjadi malas dan memutuskan untuk menginap di rumah kami yang dekat.",
  ui_story_5089_50890601_64_dialog_content = "Orang tua saya dipaksa melayani mereka sepanjang hari dan menukar persediaan biji-bijian berharga kami dengan anggur mereka. Mereka bahkan harus mengantarkan makanan ke tahanan itu.",
  ui_story_5089_50890601_65_dialog_content = "Dalam mabuk mereka, mereka bersikeras ingin melihat wajah asli saya. Mereka secara paksa melepas topeng saya dan mengancam untuk menyakiti saya.",
  ui_story_5089_50890601_66_dialog_content = "Itulah saat seorang pejalan kaki misterius meruntuhkan pagar berat di belakang penyerangku, menjebak dan membunuh mereka dalam prosesnya.",
  ui_story_5089_50890601_67_dialog_content = "Dia menyembunyikan dirinya dalam bayang-bayang sepanjang waktu, kemungkinan besar untuk menghindari terlibat dalam kematian mereka. Tetapi saya tidak punya waktu untuk memikirkan tentang dia atau tindakannya.",
  ui_story_5089_50890601_68_dialog_content = "Yang saya tahu adalah bahwa saya telah menimbulkan masalah lagi bagi orang tua saya, jadi saya kembali untuk mencari mereka...",
  ui_story_5089_50890601_69_dialog_content = "Tapi ketika aku kembali, yang kutemukan hanyalah tubuh mereka tergeletak dalam genangan darah.",
  ui_story_5089_50890601_70_dialog_content = "Di samping mereka ada mangkuk bubur panas yang tumpah. Tahanan itu sudah lama lepas dari rantainya dan melarikan diri.",
  ui_story_5089_50890601_71_dialog_content = "Terkadang, aku bertanya-tanya apakah ada kebenaran dalam pernyataan, \"Takdir membuat kita semua menjadi bodoh.\"",
  ui_story_5089_50890601_72_dialog_content = "Aku tak pernah merasa takut. Bahkan ketika orang lain memanggilku aneh atau setan, atau menghina dan melukai saya, aku tidak pernah merasa takut pada mereka.",
  ui_story_5089_50890601_73_dialog_content = "Tapi pada hari itu, ketika aku melihat tubuh orang tuaku yang tak bernyawa... Itulah hari ketika aku benar-benar merasakan ketakutan.",
  ui_story_5089_50890601_74_dialog_content = "Tapi hanya sekali itu, ibuku tidak bisa ada di sana untuk menyanyikan lagunya untukku.",
  ui_story_5089_50890601_75_dialog_content = "Maafkan saya, saya telah bicara terlalu banyak. Mulai sekarang, saya akan—",
  ui_story_5089_50890601_76_dialog_content = "Jiu!",
  ui_story_5089_50890601_77_dialog_content = "?",
  ui_story_5089_50890601_78_dialog_content = "Kamu tidak perlu memberitahuku tentang hal-hal ini, terutama jika kamu tidak mau.",
  ui_story_5089_50890601_79_dialog_content = "Itu tidak ada hubungannya dengan apakah saya ingin memberi tahu Anda atau tidak.",
  ui_story_5089_50890601_80_dialog_content = "Saya masih tidak mengerti makna kata-kata Lady Xuan Ji, tetapi saya tahu bahwa setiap kata yang dia ucapkan memiliki arti tersendiri.",
  ui_story_5089_50890601_81_dialog_content = "Dan karena dia menyebutkan asal-usulku, saya pikir hanya pantas untuk membagikannya dengan kamu.",
  ui_story_5089_50890601_82_dialog_content = "Rincian hidup saya adalah hal yang sepele pada dasarnya, tetapi saya berterima kasih kepada semua orang yang telah mendengarkannya, PlayerName.",
  ui_story_5089_50890601_83_dialog_content = "... Bagaimana kamu bisa mengatakan hal seperti itu tentang dirimu sendiri, Jiu?",
  ui_story_5089_50890601_84_dialog_content = "Kalau kamu benar-benar tidak peduli...",
  ui_story_5089_50890601_85_dialog_content = "Kamu tidak akan mengingat sesuatu yang sekecil mangkuk bubur yang tumpah di tanah itu!",
  ui_story_5089_50890601_86_dialog_content = "Apa kamu marah, PlayerName?",
  ui_story_5089_50890601_87_dialog_content = "Wah, aku terkejut kau bisa tahu!",
  ui_story_5089_50890601_88_dialog_content = "Ya, tentu saja aku marah!",
  ui_story_5089_50890601_89_dialog_content = "Maafkan aku... Aku tahu ini bukan cerita yang paling menyenangkan untuk didengar.",
  ui_story_5089_50890601_90_dialog_content = "Tapi jika ini bisa menjadi penghiburan... Balas dendamku datang tak lama setelah itu.",
  ui_story_5089_50890601_91_dialog_content = "Setelah menemukan orang tua saya seperti itu, saya mengambil belati dari salah satu petugas yang mati dan memburu tahanan selama sehari semalam.",
  ui_story_5089_50890601_92_dialog_content = "Untuk kejutan saya, dia langsung menuju ke kamp kerja tambang dan mencoba untuk membunuh tuan kita, pria yang kemudian akan menjadi Raja Ye.",
  ui_story_5089_50890601_93_dialog_content = "Saat aku berhasil mengejarnya, keadilan sudah dilayani.",
  ui_story_5089_50890601_94_dialog_content = "Yang Mulia bertanya alasan saya berada di sana. Setelah mengetahui tentang kehancuran keluarga saya, dia membawaku masuk dan memberikan nama Jiu kepada saya.",
  ui_story_5089_50890601_95_dialog_content = "Bukan hanya dia membalaskan dendamku, tetapi dia juga memperbolehkan saya tinggal di rumah besarnya. Di sana, dia mengajari saya membaca dan menulis, dan memperkuat saya melalui latihan bela diri.",
  ui_story_5089_50890601_96_dialog_content = "Untuk alasan ini, aku berutang nyawa padanya dan akan melakukan apa saja untuk membalas kebaikannya.",
  ui_story_5089_50890601_97_dialog_content = "Di luar hutang budi ini, aku tidak memiliki alasan lain untuk mengayunkan pedangku... Atau untuk terus hidup, sejatinya.",
  ui_story_5089_50890601_98_dialog_content = "Bukan itu yang saya bicarakan, Jiu.",
  ui_story_5089_50890601_99_dialog_content = "Semua yang kamu lakukan hanyalah bicara tentang balas dendam dan rasa terima kasih.",
  ui_story_5089_50890601_100_dialog_content = "Tapi bagaimana dengan perasaanmu sendiri? Bagaimana dengan hal-hal yang ingin kamu lakukan?",
  ui_story_5089_50890601_101_dialog_content = "Apakah itu saat kamu menerima pukulan untukku sebelumnya, dengan santai menyarankan untuk menyerbu penjara, atau berpikir bahwa perasaanmu tidak penting... Kamu selalu seperti itu.",
  ui_story_5089_50890601_102_dialog_content = "Mengapa kamu terus menganggap enteng pengorbananmu, seolah-olah mereka tidak penting?!",
  ui_story_5089_50890601_103_dialog_content = "Anda mungkin kuat tetapi masih terbuat dari daging dan darah. Anda bisa terluka, merasakan sakit, merasa sedih, dan jika Anda tidak berhati-hati, Anda bisa benar-benar mati.",
  ui_story_5089_50890601_104_dialog_content = "Bukan berarti aku tidak mengakui itu. Hanya saja, demi misi-misiku...",
  ui_story_5089_50890601_105_dialog_content = "Baiklah, aku mengerti. Kurasa aku mulai paham bagaimana berbicara denganmu.",
  ui_story_5089_50890601_106_dialog_content = "Dan sekarang setelah aku sendiri merasakan betapa keras kepalamu, aku merasa seolah aku juga berhutang maaf pada Dantang.",
  ui_story_5089_50890601_107_dialog_content = "Biarkan saya mengatakannya dengan cara yang bisa kamu pahami.",
  ui_story_5089_50890601_108_dialog_content = "?",
  ui_story_5089_50890601_109_dialog_content = "Jujur, keberanian dan kesediaanmu untuk mengorbankan dirimu sendiri selalu membuatku takut.",
  ui_story_5089_50890601_110_dialog_content = "Caelestite adalah ras yang baik dan damai. Kami tidak ingin melihat pertumpahan darah, dan kami terutama tidak ingin melihat teman-teman kami terluka.",
  ui_story_5089_50890601_111_dialog_content = "Saya ingin mengembalikan kamu ke Dantang dengan aman dan selamat.",
  ui_story_5089_50890601_112_dialog_content = "Jadi jika perintah adalah satu-satunya hal yang akan kau dengarkan, maka aku punya perintah khusus untukmu.",
  ui_story_5089_50890601_113_dialog_content = "\"Tidak peduli situasi Anda, selalu hargai hidup Anda dan utamakan melindungi diri Anda sendiri.\"",
  ui_story_5089_50890601_114_dialog_content = "Aku…",
  ui_story_5089_50890601_115_dialog_content = "Saya juga tidak mencari alasan apapun. Cukup katakan ya saja.",
  ui_story_5089_50890601_116_dialog_content = "Ya. Saya akan mengingat perintah Anda.",
  ui_story_5089_50890601_117_dialog_content = "Tapi, apakah ada batas waktu untuk pesanan-pesanan ini?",
  ui_story_5089_50890601_118_dialog_content = "Kamu benar-benar tidak mengerti, bukan?",
  ui_story_5089_50890601_119_dialog_content = "Tidak apa-apa. Jika kamu benar-benar membutuhkan batas waktu, maka...",
  ui_story_5089_50890601_120_dialog_content = "Perintahmu tidak akan berakhir sampai hari di mana kamu bisa mengayunkan pedangmu tanpa melakukannya karena rasa syukur atau balas dendam. Bagaimana menurutmu?",
  ui_story_5089_50890601_121_dialog_content = "Anu…",
  ui_story_5089_50890601_122_dialog_content = "Saya tidak akan mengubah bagian apa pun dari perintahmu, jika itu yang akan kamu tanyakan.",
  ui_story_5089_50890601_123_dialog_content = "Tidak, hanya saja tuanku pernah mengatakan hal yang sama kepada saya.",
  ui_story_5089_50890601_124_dialog_content = "\"Master\"mu?",
  ui_story_5089_50890601_125_dialog_content = "Pendekar terhebat di dunia dan pria yang mengajari saya jalan pedang.",
  ui_story_5089_50890601_126_dialog_content = "Meskipun dia menolak untuk menerima seseorang yang sekeras kepala seperti saya sebagai murid resmi, dia masih mengajari saya banyak hal.",
  ui_story_5089_50890601_127_dialog_content = "Tapi ada satu hal yang dia tidak mau ajarkan kepada saya: Thundering Edge, sebuah teknik yang dikabarkan memiliki kekuatan untuk membelah gunung dan laut.",
  ui_story_5089_50890601_128_dialog_content = "Dia mengklaim itu bukan teknik pedang yang sebenarnya, jadi dia tidak bisa mengajarkannya kepada saya.",
  ui_story_5089_50890601_129_dialog_content = "Hanya ketika aku bisa mengayunkan pedangku tanpa dendam atau rasa terima kasih, aku akan layak untuk mempelajarinya.",
  ui_story_5089_50890601_130_dialog_content = "Itu aneh. Saya tidak melihat petunjuk lain di sekitar sini—Urk!",
  ui_story_5089_50890601_131_dialog_content = "Maafkan aku, PlayerName, tapi kita tidak sendirian.",
  ui_story_5089_50890601_132_dialog_content = "Mmf... Apakah itu Zhui Hu?!",
  ui_story_5089_50890601_133_dialog_content = "Apa yang bisa dia lakukan di sini...? Ayo Jiu, kita ikuti dia!",
  ui_story_5089_50890601_134_dialog_content = "Dia masuk ke workshop itu, 'kan? Mari kita pergi—",
  ui_story_5089_50890601_135_dialog_content = "Kriek—",
  ui_story_5089_50890601_136_dialog_content = "Hati-hati, Jiu! Ada binatang mekanik yang menjaga bengkel!",
  ui_story_5089_50890602_1_dialog_content = "Mengapa sebuah bengkel yang ditinggalkan memerlukan perlindungan sebanyak ini?",
  ui_story_5089_50890602_2_dialog_content = "Ada banyak tanda aktivitas baru-baru ini. Tidak hanya itu, Zhui Hu juga muncul di sini.",
  ui_story_5089_50890602_3_dialog_content = "Jika harus menebak, ini mungkin benteng kuat Fate Rider.",
  ui_story_5089_50890602_4_dialog_content = "Maka kita harus sangat berhati-hati. Selain interior yang sangat besar dan seperti labirin, sebagian dari bengkel juga terletak jauh di bawah tanah.",
  ui_story_5089_50890602_5_dialog_content = "Setelah masuk, kita tidak boleh tersesat.",
  ui_story_5089_50890602_6_dialog_content = "Maka kita beruntung karena saya memiliki banyak pengalaman dengan bangunan seperti ini. Kemampuan psikis bisa sangat berguna untuk mengintai ke depan.",
  ui_story_5089_50890602_7_dialog_content = "Pemindaian Psikis—",
  ui_story_5089_50890602_8_dialog_content = "Wow! Ada begitu banyak senjata yang disimpan di sini!",
  ui_story_5089_50890602_9_dialog_content = "Apa yang rencanakan Fate Riders lakukan dengan mereka? Hah?",
  ui_story_5089_50890602_10_dialog_content = "Sepertinya ada seseorang yang terkunci di ruangan itu.",
  ui_story_5089_50890602_11_dialog_content = "!",
  ui_story_5089_50890602_12_dialog_content = "<color=#e8d9bb>Saat mereka menginjakkan kaki di ruangan itu, bau busuk langsung menyerang indra mereka.</color>",
  ui_story_5089_50890602_13_dialog_content = "<color=#e8d9bb>Sebuah sosok yang berkerumun gemetar di sudut ruangan, dengan putus asa menjauh dari mereka.</color>",
  ui_story_5089_50890602_14_dialog_content = "Lihat saja tempat ini. Mereka pasti sudah menahannya di sini untuk waktu yang lama sekarang.",
  ui_story_5089_50890602_15_dialog_content = "Siapa kamu? Apa yang kamu lakukan di sini?",
  ui_story_5089_50890602_16_dialog_content = "Ahh—Ahh—",
  ui_story_5089_50890602_17_dialog_content = "Argh... Haha... Woooo—",
  ui_story_5089_50890602_18_dialog_content = "Sepertinya orang malang itu sudah terlalu jauh pergi. Kita tidak akan mendapatkan apa-apa lagi darinya.",
  ui_story_5089_50890602_19_dialog_content = "Mari kita terus menyelidiki bengkel ini. Mungkin kita akan menemukan cara untuk menyelamatkannya...",
  ui_story_5089_50890602_20_dialog_content = "Jiu? Kenapa kamu masih berdiri di sana?",
  ui_story_5089_50890602_21_dialog_content = "Tidak... Ini tak mungkin... Kenapa kamu...",
  ui_story_5089_50890602_22_dialog_content = "Mengapa Anda di sini, Raja saya?!",
  ui_story_5089_50890602_23_dialog_content = "Tunggu... Itu Raja Ye?!",
  ui_story_5089_50890700_1_dialog_content = "<color=#e8d9bb>Hari berikutnya</color>",
  ui_story_5089_50890700_2_dialog_content = "... Putri?",
  ui_story_5089_50890700_3_dialog_content = "Hmm? Ya?",
  ui_story_5089_50890700_4_dialog_content = "Kamu memintaku untuk menanyakan tentang kedua putri itu, bukan? Fang Ze dan Shao Qin?",
  ui_story_5089_50890700_5_dialog_content = "Ah, ya. Katakan padaku, apa yang telah kamu pelajari tentang saudara perempuanku?",
  ui_story_5089_50890700_6_dialog_content = "Tampaknya raja mengirim mereka untuk memuja leluhur kerajaan beberapa waktu lalu. Oleh karena itu, mereka akan tinggal di salah satu vila kerajaan alih-alih kembali ke Kota Jingliang.",
  ui_story_5089_50890700_7_dialog_content = "Seharusnya aku tahu...",
  ui_story_5089_50890700_8_dialog_content = "Apakah kamu telah berdiri termenung di sini sepanjang waktu? Kamu hampir tidak menyentuh sarapanmu... Membiarkan semua hidangan lezat ini menjadi dingin adalah suatu pemborosan.",
  ui_story_5089_50890700_9_dialog_content = "Maafkan aku, tapi aku tidak punya banyak nafsu makan.",
  ui_story_5089_50890700_10_dialog_content = "Tidak peduli seberapa besar masalah yang kita hadapi, mengabaikan tubuh kita tidak akan menyelesaikan apa pun. Kamu setuju bukan?",
  ui_story_5089_50890700_11_dialog_content = "Dan selain itu, khawatir tidak akan membantu kamu sekarang karena kita terjebak di istana. Yang bisa kita lakukan adalah menaruh harapan kita pada PlayerName dan Nona Jiu.",
  ui_story_5089_50890700_12_dialog_content = "Pembantumu memberi tahu kami bahwa teman-teman kita baik-baik saja, 'kan?",
  ui_story_5089_50890700_13_dialog_content = "Atau, apakah kamu mengatakan bahwa kamu tidak percaya pada mereka?",
  ui_story_5089_50890700_14_dialog_content = "Tentu saja saya percaya pada mereka. Kamu, di sisi lain...",
  ui_story_5089_50890700_15_dialog_content = "Aku mengharapkan kamu untuk kabur sesegera mungkin, namun kau masih di sini.",
  ui_story_5089_50890700_16_dialog_content = "Ayo sekarang, mengapa aku akan memilih untuk pergi? Istana memberikan aku banyak makanan dan tempat yang hangat untuk tidur. Jika ada apa-apa, ini adalah beberapa hari terbaik dalam hidupku!",
  ui_story_5089_50890700_17_dialog_content = "Saya tidak tahan berpisah dengan kehidupan yang begitu indah, jadi saya melakukan ramalan untuk melihat berapa lama lagi saya bisa tinggal di sini. Bisakah Anda menebak apa yang saya lihat, Yang Mulia?",
  ui_story_5089_50890700_18_dialog_content = "Ramalan saya mengungkapkan bahwa Anda masih membutuhkan saya di sini.",
  ui_story_5089_50890700_19_dialog_content = "Memintamu meniru Jiu sudah terlalu berlebihan. Bagaimana mungkin aku bisa membebani kamu lebih jauh lagi?",
  ui_story_5089_50890700_20_dialog_content = "Setelah masalah ini selesai, aku masih harus memberimu hadiah yang pantas—",
  ui_story_5089_50890700_21_dialog_content = "<color=#e8d9bb>Duaar—!!</color>",
  ui_story_5089_50890700_22_dialog_content = "A-Apa itu tadi?!",
  ui_story_5089_50890700_23_dialog_content = "Yang Mulia! Seorang penyusup telah memaksa masuk ke dalam istana! Tolong cepat ke—Nngh!",
  ui_story_5089_50890700_24_dialog_content = "Kenapa kamu menghajar pria malang itu sampai pingsan, Tianxian?",
  ui_story_5089_50890700_25_dialog_content = "Tentu saja, untuk menunjukkan kepada Anda bahwa saya masih memiliki banyak yang bisa ditawarkan!",
  ui_story_5089_50890700_26_dialog_content = "Ah— Ahhh—",
  ui_story_5089_50890700_27_dialog_content = "*Menguap* Ugh, sudah pagi?",
  ui_story_5089_50890700_28_dialog_content = "Aku terlalu takut untuk tidur tadi malam...",
  ui_story_5089_50890700_29_dialog_content = "Ahh—",
  ui_story_5089_50890700_30_dialog_content = "*Huf* Kami sudah mengambil risiko besar dengan membawa kamu ke sejumlah dokter berbeda di tengah malam.",
  ui_story_5089_50890700_31_dialog_content = "Tapi mereka semua mengatakan hal yang sama: bahwa kondisi Anda disebabkan oleh keracunan, dan racun tersebut sudah meresap ke dalam tulang Anda. Menurut mereka, Anda sudah tidak bisa diselamatkan lagi sekarang.",
  ui_story_5089_50890700_32_dialog_content = "Auu, auuuu—",
  ui_story_5089_50890700_33_dialog_content = "Apakah kamu benar-benar Raja Ye sendiri? Jika begitu...",
  ui_story_5089_50890700_34_dialog_content = "\"Putus asa\" bahkan tidak cukup untuk menggambarkan situasi yang kita hadapi sekarang.",
  ui_story_5089_50890700_35_dialog_content = "Bukan hanya itu, sesuatu yang Jiu katakan kemarin membuatku merasa sangat tidak enak.",
  ui_story_5089_50890700_36_dialog_content = "Jadi klinik ini juga tidak bisa berbuat apa-apa untuknya, huh?",
  ui_story_5089_50890700_37_dialog_content = "Jangan menyerah dulu, Jiu. Mungkin kita bisa membuat salah satu dokter ini menulis surat untuk Liqing?",
  ui_story_5089_50890700_38_dialog_content = "Kita bahkan bisa mencoba mencari pria \"Bucunzi\" yang Dantang sebutkan sebelumnya—",
  ui_story_5089_50890700_39_dialog_content = "PlayerName.",
  ui_story_5089_50890700_40_dialog_content = "Jika orang di atas takhta bukanlah Raja Ye yang sejati, lalu apa yang akan terjadi pada Yang Mulia Ratu?",
  ui_story_5089_50890700_41_dialog_content = "Hmm…",
  ui_story_5089_50890700_42_dialog_content = "Saya sangat berhutang bukan hanya pada raja, tetapi juga pada dia. Dalam waktu bersama kami, Yang Mulia telah menunjukkan kepada saya tidak ada selain kebaikan.",
  ui_story_5089_50890700_43_dialog_content = "Sekarang setelah tuan putri telah membebaskan saya dari tugas saya sebagai pengawalnya, mungkin saya tidak memiliki hak untuk ikut campur dalam urusannya.",
  ui_story_5089_50890700_44_dialog_content = "Tapi jika aku tidak bisa melindunginya lagi...",
  ui_story_5089_50890700_45_dialog_content = "Maka saya menyerahkan keselamatan Yang Mulia kepada kamu.",
  ui_story_5089_50890700_46_dialog_content = "Maaf.",
  ui_story_5089_50890700_47_dialog_content = "Tunggu sebentar... Sebenarnya, dia di mana sih?!",
  ui_story_5089_50890700_48_dialog_content = "Grrr... Sudah kuduga!",
  ui_story_5089_50890700_49_dialog_content = "Untung saya merencanakan sesuatu seperti ini terjadi...",
  ui_story_5089_50890700_50_dialog_content = "Paman Li! Maaf, tapi bisakah saya meminta Anda untuk menjaga pria ini?",
  ui_story_5089_50890700_51_dialog_content = "Eh? Tentu saja, teman muda saya, tapi kemana kamu pergi dengan terburu-buru?",
  ui_story_5089_50890700_52_dialog_content = "Ke Kota Jingliang!",
  ui_story_5089_50890700_53_dialog_content = "Ahh—",
  ui_story_5089_50890700_54_dialog_content = "Tuan saya, seorang pembunuh telah menembus gerbang istana dan pengawal kita tidak sepadan dengannya. Dia sedang mendekati aula utama saat kita berbicara!",
  ui_story_5089_50890700_55_dialog_content = "Harusnya Frost Blade, Yang Mulia.",
  ui_story_5089_50890700_56_dialog_content = "Haruskah kita menghadangnya?",
  ui_story_5089_50890700_57_dialog_content = "Tidak perlu. Jika dia mencari audiensi dengan raja, maka saya akan menunggunya di sini.",
  ui_story_5089_50890700_58_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5089_50890700_59_dialog_content = "Berhenti! Kamu berdiri di depan Raja Ye yang perkasa, sekarang jangan melangkah lebih jauh!",
  ui_story_5089_50890700_60_dialog_content = "Minggir.",
  ui_story_5089_50890700_61_dialog_content = "Eurgh—",
  ui_story_5089_50890700_62_dialog_content = "<color=#e8d9bb>Jiu melangkah masuk ke aula utama dan bertatapan dengan pria di atas takhta.</color>",
  ui_story_5089_50890700_63_dialog_content = "Sepertinya reputasi Anda sebagai pedang terhebat raja memang terbukti.",
  ui_story_5089_50890700_64_dialog_content = "Tidak ada prajurit di seluruh istana yang berharap bisa menandingi kamu.",
  ui_story_5089_50890700_65_dialog_content = "Jangan pura-pura!",
  ui_story_5089_50890700_66_dialog_content = "Saya sudah bertemu dengan raja yang sebenarnya, kamu penipu—",
  ui_story_5089_50890700_67_dialog_content = "Sekarang lepaskan dirimu dari takhta dia!",
  ui_story_5089_50890700_68_dialog_content = "Ah, jadi kamu sudah melihat sendiri orang bodoh yang bingung itu.",
  ui_story_5089_50890700_69_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_5089_50890700_70_dialog_content = "<color=#e8d9bb>Pedang mereka beradu, mengisi ruangan dengan gema yang kuat.</color>",
  ui_story_5089_50890700_71_dialog_content = "Berani-beraninya kau menghina raja dengan begitu sembrono!",
  ui_story_5089_50890700_72_dialog_content = "Heh, keganasanmu sungguh mengagumkan.",
  ui_story_5089_50890700_73_dialog_content = "Kamu benar-benar adalah pendekar pedang terkuat di bawah komandoku.",
  ui_story_5089_50890700_74_dialog_content = "Apa-apaan kau…!",
  ui_story_5089_50890700_75_dialog_content = "Penjaga! Sambut atasanmu dengan ujian kekuatan yang ramah!",
  ui_story_5089_50890700_76_dialog_content = "Baik, Yang Mulia!",
  ui_story_5089_50890700_77_dialog_content = "<color=#e8d9bb>Pengawal bayangan raja mendekat dari kedua sisi, kawat logam tajam mereka memotong udara.</color>",
  ui_story_5089_50890700_78_dialog_content = "<color=#e8d9bb>Saat Jiu hendak menghindar, dia melihat celah di pertahanan raja palsu dan menyerang.</color>",
  ui_story_5089_50890700_79_dialog_content = "—!",
  ui_story_5089_50890700_80_dialog_content = "<color=#e8d9bb>Kawat logam menembus betisnya, namun serangannya tidak goyah sekalipun. Dengan kekuatan penuh, dia menusukkan pedangnya langsung ke jantung raja palsu!</color>",
  ui_story_5089_50890700_81_dialog_content = "Sejak kamu masih kecil, kamu selalu memiliki kebiasaan buruk ini.",
  ui_story_5089_50890700_82_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_5089_50890700_83_dialog_content = "<color=#e8d9bb>Ujung pedangnya menekan ringan baju zirah raja dan sedikit memantul kembali.</color>",
  ui_story_5089_50890700_84_dialog_content = "Kurang ajar...",
  ui_story_5089_50890700_85_dialog_content = "<color=#e8d9bb>Jiu segera pulih dan bersiap untuk menyerang sekali lagi.</color>",
  ui_story_5089_50890700_86_dialog_content = "Pedangmu tajam, tetapi mengasah bilah hingga batasnya berdampak pada daya tahan pedang.",
  ui_story_5089_50890700_87_dialog_content = "Apakah kamu lupa alasan mengapa saya memberimu nama \"Jiu\"?",
  ui_story_5089_50890700_88_dialog_content = "!",
  ui_story_5089_50890700_89_dialog_content = "<color=#e8d9bb>—Sepuluh tahun lalu</color>",
  ui_story_5089_50890700_90_dialog_content = "Jadi kamu mengejar pembunuh keluargamu ke sini, tanpa alas kaki dan sendirian, tanpa makan atau minum apa pun selama sehari penuh?",
  ui_story_5089_50890700_91_dialog_content = "Hahaha, aku tidak pernah menyangka seseorang yang begitu muda bisa begitu bertekad.",
  ui_story_5089_50890700_92_dialog_content = "Tapi lihat dirimu sekarang: kelaparan, penuh dengan lepuhan, dan hampir tidak bisa berdiri.",
  ui_story_5089_50890700_93_dialog_content = "Bahkan jika kamu berhasil mengejar musuhmu dalam kondisi ini, satu-satunya kemenangan yang bisa kamu harapkan adalah kemenangan di mana kalian berdua mati.",
  ui_story_5089_50890700_94_dialog_content = "... Tapi itu tidak mengganggu Anda, bukan? Lagipula, apa lagi yang bisa Anda lakukan dalam hidup Anda selain mengorbankannya demi balas dendam?",
  ui_story_5089_50890700_95_dialog_content = "Tapi sekarang setelah aku telah melaksanakan dendammu, sangatlah pantas jika hidupmu kini milikku.",
  ui_story_5089_50890700_96_dialog_content = "\"Jiu-mei,\" bukan? Nama yang berarti \"putri kesembilan\" hampir tidak layak dipertahankan.",
  ui_story_5089_50890700_97_dialog_content = "Mulai hari ini, kamu akan dikenal hanya sebagai \"Jiu.\"",
  ui_story_5089_50890700_98_dialog_content = "Sebuah nama yang merujuk pada batu berharga berwarna hitam murni. Seindah giok, namun jauh lebih kuat.",
  ui_story_5089_50890700_99_dialog_content = "Di bawah komando saya, kamu akan mengasah ketajamanmu dan menjadi pedang terajam saya, selama kamu tidak membiarkan dirimu menjadi rapuh.",
  ui_story_5089_50890700_100_dialog_content = "<color=#e8d9bb>Jiu sejenak kehilangan fokus, dan segera dipaku ke tanah oleh jaringan kawat logam yang tak terhitung jumlahnya.</color>",
  ui_story_5089_50890700_101_dialog_content = "<color=#e8d9bb>Topengnya jatuh ke tanah, tetapi dia terus menatap dengan marah ke raja palsu.</color>",
  ui_story_5089_50890700_102_dialog_content = "Siapa... Siapa kamu?",
  ui_story_5089_50890700_103_dialog_content = "Bukankah mereka bilang ada seseorang yang menyusup ke istana? Kenapa masih ada begitu banyak penjaga yang mengawasi tempat ini?",
  ui_story_5089_50890700_104_dialog_content = "Ketika kamu bilang untuk kabur tadi, aku pikir itu karena kamu punya semacam rencana brilian.",
  ui_story_5089_50890700_105_dialog_content = "Berimprovisasi adalah rencana aksi yang sangat dapat diterima, mengingat situasi kita.",
  ui_story_5089_50890700_106_dialog_content = "Saya mengerti bahwa Anda memiliki sedikit sekali kepercayaan pada ramalan saya, tetapi saya percaya sepenuhnya padanya.",
  ui_story_5089_50890700_107_dialog_content = "Ramalan mengerikan yang PlayerName tarik sebelumnya cocok sempurna dengan situasi kita saat ini.",
  ui_story_5089_50890700_108_dialog_content = "Namun, jika perhitungan saya benar, kita tidak bisa sepenuhnya mengandalkan PlayerName dan Miss Jiu untuk menyelesaikan masalah ini.",
  ui_story_5089_50890700_109_dialog_content = "Apa maksudmu?",
  ui_story_5089_50890700_110_dialog_content = "Sederhana saja: sementara aku mengalihkan perhatian prajurit, kamu akan memanfaatkan kesempatan untuk melarikan diri dari istana.",
  ui_story_5089_50890700_111_dialog_content = "Mengenai apa yang akan terjadi selanjutnya, kita hanya perlu berimprovisasi!",
  ui_story_5089_50890700_112_dialog_content = "Tunggu, Tianxian!",
  ui_story_5089_50890700_113_dialog_content = "Siapa yang pergi ke sana?!",
  ui_story_5089_50890700_114_dialog_content = "Setelah mereka!",
  ui_story_5089_50890700_115_dialog_content = "Aku tak akan pernah mengerti pria itu.",
  ui_story_5089_50890700_116_dialog_content = "Tapi sepertinya aku tidak punya pilihan sekarang—",
  ui_story_5089_50890700_117_dialog_content = "Kemana Anda pergi, Yang Mulia?",
  ui_story_5089_50890700_118_dialog_content = "...",
  ui_story_5089_50890700_119_dialog_content = "Xuan Ji, para prajurit—",
  ui_story_5089_50890700_120_dialog_content = "Tenanglah, aku sedang sibuk di sini.",
  ui_story_5089_50890700_121_dialog_content = "Tapi tidak ada waktu lagi! Kenapa kamu masih bermain-main dengan ubin itu?",
  ui_story_5089_50890700_122_dialog_content = "Ini bukan ubin biasa! Mereka adalah perangkat cerdas yang telah saya buat dengan teliti selama beberapa hari sekarang.",
  ui_story_5089_50890700_123_dialog_content = "Kamu telah menjadi jauh lebih bijaksana, tapi kamu masih harus banyak belajar tentang kecerdikan dan tipu daya.",
  ui_story_5089_50890700_124_dialog_content = "Maksudmu apa, hah?",
  ui_story_5089_50890700_125_dialog_content = "Yang saya maksud adalah ini mungkin tampak seperti sel penjara biasa bagi kamu.",
  ui_story_5089_50890700_126_dialog_content = "Namun di tangan seorang pengrajin sejati, apa pun dapat dimodifikasi menjadi perangkat atau mekanisme: bangku, meja, balok atap, dan bahkan tanah di bawah kaki Anda.",
  ui_story_5089_50890700_127_dialog_content = "Sekarang nikmati penemuan terbaru saya, yang terinspirasi oleh Caelestite favorit kita dan dibuat menggunakan barang-barang rumah tangga sederhana: Lumina Deflector Tile!",
  ui_story_5089_50890700_128_dialog_content = "... Kamu bercanda kan? Jadi, apa yang sebenarnya itu lakukan?",
  ui_story_5089_50890700_129_dialog_content = "Peralatan bagus ini mampu mengarahkan cahaya atau Lumina yang masuk ke lokasi yang diinginkan.",
  ui_story_5089_50890700_130_dialog_content = "Dan bagaimana tepatnya itu seharusnya membantu kita?",
  ui_story_5089_50890700_131_dialog_content = "Kita akan segera mengetahui!",
  ui_story_5089_50890700_132_dialog_content = "Sepuluh tahun yang lalu, seorang pejabat tinggi yang lelah dengan pertarungan kekuasaan di dalam istana kerajaan, jatuh dari anugerah dan menjadi tahanan. Dia dihukum kerja keras di tambang sampai ajalnya.",
  ui_story_5089_50890700_133_dialog_content = "Namun, nasib memiliki rencana lain untuknya. Para petugas yang mengawalnya ke kamp kerja adalah orang-orang yang malas, dan daripada menyelesaikan perjalanan, mereka memutuskan untuk menginap di rumah keluarga terdekat.",
  ui_story_5089_50890700_134_dialog_content = "Mereka hanyalah warga biasa, yang membuatnya mudah untuk menyergap mereka dan melarikan diri.",
  ui_story_5089_50890700_135_dialog_content = "Namun saat dia melarikan diri dari halaman, dia bertemu dengan penculiknya saat mereka mencoba memanfaatkan putri muda keluarga itu.",
  ui_story_5089_50890700_136_dialog_content = "Dan begitu dia membunuh mereka tanpa berpikir dua kali, dan melanjutkan perjalanan semula menuju kamp kerja.",
  ui_story_5089_50890700_137_dialog_content = "Pangeran yang saat itu bertanggung jawab atas kamp kerja adalah orang baik, tetapi tetap saja seorang bodoh. Hanya dengan satu dosis obat tertentu, pikirannya benar-benar hilang.",
  ui_story_5089_50890700_138_dialog_content = "Dan begitu, setelah mengenakan penyamaran ringan, tahanan itu bertukar tempat dengan pangeran.",
  ui_story_5089_50890700_139_dialog_content = "Para pria di hadapannya begitu kehilangan rasa setia, sehingga mereka tidak pernah menyadari bahwa seorang pria lain telah diam-diam menggantikan tuan mereka.",
  ui_story_5089_50890700_140_dialog_content = "Secara kebetulan, di saat ini juga putri muda itu tiba, mencari pembalasan untuk keluarganya yang telah jatuh.",
  ui_story_5089_50890700_141_dialog_content = "Saat itulah tahanan menyadari bahwa upaya kaburnya yang kasar telah mengakibatkan kematian mereka.",
  ui_story_5089_50890700_142_dialog_content = "Dan begitu dia membawa gadis itu masuk, dan membentuknya menjadi pedang yang setia dan penuh kepercayaan.",
  ui_story_5089_50890700_143_dialog_content = "I-Ini kamu selama ini—!",
  ui_story_5089_50890700_144_dialog_content = "<color=#e8d9bb>Mata Jiu berubah merah saat dia berusaha keras mengangkat tubuhnya. Jaring kawat yang menindihnya mengeluarkan suara erangan tajam, seolah-olah akan patah.</color>",
  ui_story_5089_50890700_145_dialog_content = "Sudah saatnya bagi saya untuk mengungkap kebenaran.",
  ui_story_5089_50890700_146_dialog_content = "Sekarang katakan padaku, apakah kamu masih berniat membalas kematian keluargamu?",
  ui_story_5089_50890700_147_dialog_content = "Ataukah kamu akan mengungkapkan rasa terima kasih kepadaku karena telah menerima dan membesarkanmu selama bertahun-tahun ini?",
  ui_story_5089_50890700_148_dialog_content = "Aku…",
  ui_story_5089_50890700_149_dialog_content = "<color=#e8d9bb>Untuk pertama kalinya, pedang Jiu bergetar di tangannya.</color>",
  ui_story_5089_50890700_150_dialog_content = "Untuk apa kamu hidup selama ini, Jiu? Apa tujuanmu?",
  ui_story_5089_50890700_151_dialog_content = "Hraaagh—!",
  ui_story_5089_50890700_152_dialog_content = "<color=#e8d9bb>Seberkas cahaya berkilauan lewat.</color>",
  ui_story_5089_50890700_153_dialog_content = "<color=#e8d9bb>Kawat logam putus dan terbang ke segala arah. Di tengah reruntuhan yang jatuh, Jiu melepaskan serangan pamungkasnya.</color>",
  ui_story_5089_50890700_154_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5089_50890700_155_dialog_content = "<color=#e8d9bb>Dia mengayunkan pedangnya yang terisi Lumina, dan gelombang kejut yang dihasilkan membelah istana menjadi dua, meninggalkan parit dalam di lantai batu.</color>",
  ui_story_5089_50890700_156_dialog_content = "<color=#e8d9bb>Namun, Raja Ye dengan mudah menghindari serangan dan muncul tanpa cedera.</color>",
  ui_story_5089_50890700_157_dialog_content = "Apakah Anda benar-benar begitu ragu sehingga Anda bahkan tidak bisa memegang pedang Anda dengan mantap?",
  ui_story_5089_50890700_158_dialog_content = "<color=#e8d9bb>Memukul—</color>",
  ui_story_5089_50890700_159_dialog_content = "<color=#e8d9bb>Raja memukul pedang Jiu keluar dari tangannya dan jatuh ke sudut ruangan.</color>",
  ui_story_5089_50890700_160_dialog_content = "<color=#e8d9bb>Beberapa saat yang lalu.</color>",
  ui_story_5089_50890700_161_dialog_content = "Yang Mulia, jika Anda bersikeras untuk pergi, kami tidak punya pilihan selain menahan Anda dengan paksa.",
  ui_story_5089_50890700_162_dialog_content = "Saya tidak pernah berpikir akan melihat hari dimana saya harus bertempur melawan pengawal istana saya di Kerajaan Ye.",
  ui_story_5089_50890700_163_dialog_content = "Sayangnya untukmu, mundur bukan lagi pilihan untukku.",
  ui_story_5089_50890700_164_dialog_content = "Saya masih punya seseorang yang menungguku di luar sana.",
  ui_story_5089_50890700_165_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5089_50890700_166_dialog_content = "<color=#e8d9bb>Tiba-tiba, balai utama terdekat dihancurkan oleh gelombang Lumina yang kuat.</color>",
  ui_story_5089_50890700_167_dialog_content = "<color=#e8d9bb>Segera setelah itu, kilatan cahaya mengisi ruangan saat gelombang Lumina langsung menuju mereka!</color>",
  ui_story_5089_50890700_168_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5089_50890700_169_dialog_content = "<color=#e8d9bb>Tower istana terbelah di tengah, menciptakan jurang antara pengawal kerajaan dan Dantang.</color>",
  ui_story_5089_50890700_170_dialog_content = "<color=#e8d9bb>Suatu kilatan cahaya tiba-tiba menerangi jalan keluar dari istana.</color>",
  ui_story_5089_50890700_171_dialog_content = "Arah itu... Menteri Armilla?",
  ui_story_5089_50890700_172_dialog_content = "Saya memiliki firasat bahwa dia tidak akan pernah diam di sel penjaranya.",
  ui_story_5089_50890700_173_dialog_content = "Jadi kamu pikir saya juga harus melarikan diri dari istana?",
  ui_story_5089_50890700_174_dialog_content = "Yang mulia.",
  ui_story_5089_50890700_175_dialog_content = "Ada apa?",
  ui_story_5089_50890700_176_dialog_content = "Maafkan kami, tapi Putri telah melarikan diri dari istana.",
  ui_story_5089_50890700_177_dialog_content = "Status orang yang masuk istana bersama sang putri juga tidak diketahui, begitu pula keberadaannya.",
  ui_story_5089_50890700_178_dialog_content = "Pengawal kami mengklaim telah melihatnya menyelam ke semak-semak, tetapi ketika mereka pergi untuk menyelidiki, yang mereka temukan hanyalah patung gula.",
  ui_story_5089_50890700_179_dialog_content = "Lalu…",
  ui_story_5089_50890700_180_dialog_content = "Apa lagi? Bicaralah sekarang juga.",
  ui_story_5089_50890700_181_dialog_content = "Sepertinya \"mereka\" berencana untuk segera bertindak.",
  ui_story_5089_50890700_182_dialog_content = "Mereka menekankan bahwa kita harus mengirim senjata dalam tiga hari ke depan.",
  ui_story_5089_50890700_183_dialog_content = "Namun, bengkel mengklaim tidak memiliki kapasitas untuk memenuhi pesanan besar dalam waktu yang sangat singkat. Kerajaan Ji juga mendesak kami untuk menyelesaikan transaksi sebelumnya...",
  ui_story_5089_50890700_184_dialog_content = "Aku mengerti.",
  ui_story_5089_50890700_185_dialog_content = "Kita akan membahas ini nanti.",
  ui_story_5089_50890700_186_dialog_content = "Untuk saat ini, tahan mantan pemimpinmu sampai dia mendapatkan kembali ketenangannya.",
  ui_story_5089_50890700_187_dialog_content = "Baik, Yang Mulia.",
  ui_story_5089_50890700_188_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5089_50890700_189_dialog_content = "<color=#e8d9bb>Penjaga bayangan melempar Jiu ke dalam ruangan kosong dan pergi.</color>",
  ui_story_5089_50890700_190_dialog_content = "Nah, kalau bukan Nona Jiu!",
  ui_story_5089_50890700_191_dialog_content = "Apakah kamu datang untuk menemaniku?",
  ui_story_5089_50890700_192_dialog_content = "...",
  ui_story_5089_50890802_1_dialog_content = "Berikan peringatan kepada setiap penjaga di kota! Tuan Putri telah diculik!",
  ui_story_5089_50890802_2_dialog_content = "Telusuri setiap sudut kota! Laporkan setiap karakter mencurigakan segera!",
  ui_story_5089_50890802_3_dialog_content = "Paham!",
  ui_story_5089_50890802_4_dialog_content = "Begitu banyak penjaga... Rasanya seperti suasana seluruh Kota Jingliang tiba-tiba berubah.",
  ui_story_5089_50890802_5_dialog_content = "Dan sesuatu memberitahu saya bahwa saya adalah salah satu \"karakter mencurigakan\" yang mereka cari.",
  ui_story_5089_50890802_6_dialog_content = "Siapa di sana? Tunjukkan dirimu!",
  ui_story_5089_50890802_7_dialog_content = "Uh-oh—Urk! L-Lepaskan saya...!",
  ui_story_5089_50890802_8_dialog_content = "Sst, hanya aku.",
  ui_story_5089_50890802_9_dialog_content = "Dantang?!",
  ui_story_5089_50890802_10_dialog_content = "Ya, sekarang ikuti aku.",
  ui_story_5089_50890802_11_dialog_content = "Tempat apa ini?",
  ui_story_5089_50890802_12_dialog_content = "Ini adalah ruangan aman yang disiapkan oleh pengawal bersenjata yang kami sewa untuk mengembalikan emas pangeran mahkota.",
  ui_story_5089_50890802_13_dialog_content = "Karena mereka sering bekerja dengan dunia bawah tanah kriminal, tentu saja mereka membutuhkan ruang seperti ini.",
  ui_story_5089_50890802_14_dialog_content = "Dan karena kami telah melakukan pesanan yang sangat mahal, sangat normal jika mereka memberikan kami beberapa fasilitas tambahan.",
  ui_story_5089_50890802_15_dialog_content = "Apakah kamu merencanakan ini jauh-jauh hari sejak awal?!",
  ui_story_5089_50890802_16_dialog_content = "Jadi ada alasan meninggalkan kami di penginapan!",
  ui_story_5089_50890802_17_dialog_content = "Aku tidak sepenuhnya yakin akan kebenaran itu waktu itu. Yang aku miliki hanyalah petunjuk samar dari Ministress Armilla untuk membimbingku.",
  ui_story_5089_50890802_18_dialog_content = "Meskipun peluangnya tipis, kemungkinan adanya permainan kotor merupakan ancaman besar bagi seluruh Kerajaan Ye.",
  ui_story_5089_50890802_19_dialog_content = "Bukan hanya itu... Tapi harga keuntungan juga terlalu tinggi.",
  ui_story_5089_50890802_20_dialog_content = "Paman Li juga memberi tahu kami bahwa para pedagang dari Kerajaan Ji terus membeli makanan meskipun harga belakangan ini tinggi.",
  ui_story_5089_50890802_21_dialog_content = "... Kerusuhan di awal musim semi juga sebagian disebabkan oleh keengganan Kerajaan Ye untuk mengirimkan meriam ke pantai.",
  ui_story_5089_50890802_22_dialog_content = "Kerajaan Ji tidak akan pernah menanggung kerugian ini tanpa mendapatkan sesuatu sebagai gantinya.",
  ui_story_5089_50890802_23_dialog_content = "Apakah kamu sedang mengatakan... bahwa Kerajaan Ji sengaja menaikkan harga biji-bijian?",
  ui_story_5089_50890802_24_dialog_content = "Warga biasa paling terluka ketika harga dinaikkan seperti ini. Ketika itu terjadi, mereka lebih cenderung pergi dan mencari cara lain untuk bertahan hidup.",
  ui_story_5089_50890802_25_dialog_content = "Dalam beberapa tahun terakhir, Kerajaan Ye telah mendirikan banyak bengkel berbagai ukuran. Dengan melakukan itu, mereka telah menarik banyak warga muda dan sehat kerajaan, memaksa mereka untuk meninggalkan ladang mereka dengan harapan mendapatkan pekerjaan yang lebih baik dibayar.",
  ui_story_5089_50890802_26_dialog_content = "Persediaan biji-bijian kami sudah tidak cukup untuk menangani pergeseran populasi sebesar ini.",
  ui_story_5089_50890802_27_dialog_content = "Kenaikan harga biji-bijian juga meningkatkan biaya untuk sektor lainnya. Singkatnya, perekonomian kerajaan terjebak dalam lingkaran setan.",
  ui_story_5089_50890802_28_dialog_content = "Namun, Kerajaan Ji sama sekali tidak kekurangan dana. Jika mereka memutuskan untuk menantang kami dalam perang atrisi, saya khawatir kami tidak memiliki peluang untuk menang.",
  ui_story_5089_50890802_29_dialog_content = "Namun, saya tidak yakin bahwa Kerajaan Ji ingin memutuskan hubungan sepenuhnya. Jika ada, mereka kemungkinan besar ingin memanfaatkan kelemahan kita untuk terus mengeksploitasi kita.",
  ui_story_5089_50890802_30_dialog_content = "... Waktu mereka tidak bisa lebih buruk.",
  ui_story_5089_50890802_31_dialog_content = "Waktu mereka?",
  ui_story_5089_50890802_32_dialog_content = "Beritahu saya, PlayerName: apa sebenarnya yang kamu anggap sebagai \"negara\"?",
  ui_story_5089_50890802_33_dialog_content = "Hah? Yah... Saya rasa itu adalah sekelompok orang yang berkumpul dalam pencarian kehidupan yang lebih baik.",
  ui_story_5089_50890802_34_dialog_content = "Selain memajukan kepentingan mereka, mereka juga bekerja keras untuk semua orang lainnya dalam grup.",
  ui_story_5089_50890802_35_dialog_content = "Apakah itulah cara orang-orang Eraveil mendefinisikan sebuah negara? Saya harus bilang, itu terdengar seperti kehidupan utopia yang cukup.",
  ui_story_5089_50890802_36_dialog_content = "A-Apakah aku salah?",
  ui_story_5089_50890802_37_dialog_content = "Sama sekali tidak, PlayerName.",
  ui_story_5089_50890802_38_dialog_content = "Meskipun setiap kerajaan vasal di Longzhou berada di bawah aturan Kekaisaran Zhao, mereka masing-masing memiliki pandangan mereka sendiri tentang apa artinya menjadi sebuah bangsa.",
  ui_story_5089_50890802_39_dialog_content = "Misalnya, Kerajaan Ji percaya bahwa memerintah sebuah negara tidak berbeda dengan menjalankan bisnis. Sebaliknya, Kerajaan Ye melihat hal-hal secara berbeda.",
  ui_story_5089_50890802_40_dialog_content = "Di mata kami, sebuah negara adalah mekanisme besar yang tak berbentuk. Siang dan malam, ia beroperasi tanpa henti.",
  ui_story_5089_50890802_41_dialog_content = "Kamu adalah poros, saya adalah roda gigi, pengrajin adalah minyak, dan massa adalah tenaga penggeraknya.",
  ui_story_5089_50890802_42_dialog_content = "Selama setiap bagian dari mesin menjalankan perannya dengan setia dan normal, negara kita akan berkembang dengan alami.",
  ui_story_5089_50890802_43_dialog_content = "Jadi bagaimana dengan sekarang?",
  ui_story_5089_50890802_44_dialog_content = "Raja kami adalah penipu, konflik kepentingan menandai pengadilannya, para pengrajin tidak bebas, dan rakyat jelata berada di ambang penderitaan yang lebih besar. Inilah keadaan negara kami saat ini.",
  ui_story_5089_50890802_45_dialog_content = "Daripada mencoba menyelesaikan setiap masalah ini secara individu, saya memutuskan untuk langsung ke inti konflik.",
  ui_story_5089_50890802_46_dialog_content = "Dan jadi saya secara sukarela kembali ke istana, berharap menemukan kelemahan di inti penderitaan bangsa kita.",
  ui_story_5089_50890802_47_dialog_content = "Melakukannya juga memungkinkan kamu dan Jiu untuk terus mencari bukti tanpa dikejar oleh prajurit raja.",
  ui_story_5089_50890802_48_dialog_content = "Secara jujur, saya tahu bahwa Jiu tidak akan pernah setuju dengan ini, yang membuat saya tidak punya pilihan selain menggunakan penipuan. Tolong jangan simpan dendam terhadap saya, PlayerName.",
  ui_story_5089_50890802_49_dialog_content = "Saya tidak menyalahkanmu untuk itu, Dantang. Setelah waktu kita bersama, saya belajar betapa keras kepalanya dia juga.",
  ui_story_5089_50890802_50_dialog_content = "Itulah sebabnya aku harus melakukan sesuatu yang serupa dengannya...",
  ui_story_5089_50890802_51_dialog_content = "Maaf mengganggu, tuan muda, tetapi pengiriman Anda telah tiba dengan selamat. May Bolehkah saya minta tanda tangan Anda?",
  ui_story_5089_50890802_52_dialog_content = "Ya, tentu. Terima kasih banyak atas bantuanmu.",
  ui_story_5089_50890802_53_dialog_content = "Juga, Yang Mulia, kita telah membuat kemajuan dalam hal ini sejak percakapan terakhir kita.",
  ui_story_5089_50890802_54_dialog_content = "Orang-orang saya di luar kota telah memberi tahu saya bahwa memang ada Huolong Carriers yang bergerak ke arah itu, dan tampaknya mereka sedang mengangkut sejumlah besar barang.",
  ui_story_5089_50890802_55_dialog_content = "Dipahami. Terima kasih atas semua bantuanmu.",
  ui_story_5089_50890802_56_dialog_content = "Hanya melakukan pekerjaan kami. Sampai jumpa.",
  ui_story_5089_50890802_57_dialog_content = "Apakah dia berbicara tentang workshop rahasia?",
  ui_story_5089_50890802_58_dialog_content = "Memang. Selama waktu saya di istana, saya mengumpulkan cukup banyak informasi.",
  ui_story_5089_50890802_59_dialog_content = "Raja palsu telah mengeksploitasi sumber daya Kerajaan Ye untuk memproduksi senjata bagi Fate Riders.",
  ui_story_5089_50890802_60_dialog_content = "Kerajaan Ji juga telah menunda pengiriman meriam pantainya. Saya curiga mereka juga bersekongkol dengan Fate Riders, yang ingin mengklaim meriam tersebut untuk diri mereka sendiri.",
  ui_story_5089_50890802_61_dialog_content = "Dan baru-baru ini mereka sekali lagi meningkatkan permintaan untuk senjata api.",
  ui_story_5089_50890802_62_dialog_content = "Mereka telah menekankan masalah ini beberapa kali sekarang, dan bahkan telah mengancam raja palsu jika dia gagal untuk memberikan.",
  ui_story_5089_50890802_63_dialog_content = "Ketika kamu menyebutkan adanya sebuah workshop tersembunyi, aku langsung mengirimkan orang-orang ini untuk menyelidiki.",
  ui_story_5089_50890802_64_dialog_content = "Namun, aku tak menyangka mereka akan bertindak secepat ini...",
  ui_story_5089_50890802_65_dialog_content = "Kita tidak bisa berdiri di sini dan membiarkan Fate Riders mendapatkan semua senjata itu!",
  ui_story_5089_50890802_66_dialog_content = "Aku sangat setuju dengan kamu.",
  ui_story_5089_50890802_67_dialog_content = "Tetapi mengingat situasi sulit kita saat ini, sangat sulit bagi kita untuk mengambil tindakan dalam cara apapun.",
  ui_story_5089_50890802_68_dialog_content = "Meski dengan bantuanmu, mengungkap kebenaran sama sekali tidak mudah. Andai saja aku bisa mempersiapkan diri lebih awal...",
  ui_story_5089_50890802_69_dialog_content = "Itu sama sekali tidak terlihat atau terdengar seperti Anda, Dantang.",
  ui_story_5089_50890802_70_dialog_content = "PlayerName?",
  ui_story_5089_50890802_71_dialog_content = "Dantang yang aku kenal, tidak akan pernah meragukan dirinya sendiri dalam menghadapi situasi seperti ini, terutama jika takdir seolah-olah memiliki andil dalam hal ini.",
  ui_story_5089_50890802_72_dialog_content = "Dantang yang aku kenal itu berani, hingga hampir menakutkan.",
  ui_story_5089_50890802_73_dialog_content = "... Kamu memuji saya, temanku. Tetapi sayangnya, masalah kita tidak bisa diatasi hanya dengan keberanian saja.",
  ui_story_5089_50890802_74_dialog_content = "Tapi jika kita bisa membawa cukup banyak chip ke meja perundingan...",
  ui_story_5089_50890802_75_dialog_content = "Itu seharusnya tidak menjadi masalah.",
  ui_story_5089_50890802_76_dialog_content = "Apa?",
  ui_story_5089_50890802_77_dialog_content = "Jika kamu khawatir tentang alat tawar-menawar, kita punya banyak.",
  ui_story_5089_50890802_78_dialog_content = "Sebagai contoh... Kami memiliki cukup emas di tangan kami untuk membeli seluruh kota.",
  ui_story_5089_50890802_79_dialog_content = "!",
  ui_story_5089_50890802_80_dialog_content = "Tapi itu adalah hadiah dari pangeran mahkota untuk kamu, yang rencananya akan kamu kembalikan!",
  ui_story_5089_50890802_81_dialog_content = "Nah, tidak mudah bagi kita untuk sampai di sini. Akan sia-sia jika tidak memanfaatkan semua yang kita miliki.",
  ui_story_5089_50890802_82_dialog_content = "Tapi, meskipun dengan semua emas ini, mencoba mengumpulkan tenaga kerja yang cukup dalam waktu yang sangat terbatas—",
  ui_story_5089_50890802_83_dialog_content = "Saya juga punya ide untuk itu.",
  ui_story_5089_50890802_84_dialog_content = "Saya tidak mengerti tentang kerumitan politik pengadilan, jadi saya tidak bisa memberikan banyak pendapat.",
  ui_story_5089_50890802_85_dialog_content = "Tapi saya pikir kita bisa menyederhanakan hal-hal sedikit dengan emas ini.",
  ui_story_5089_50890802_86_dialog_content = "Lagipula, uang memang ditujukan untuk dibelanjakan, 'kan?",
  ui_story_5089_50890802_87_dialog_content = "Lalu... Apa sebenarnya yang ingin kamu beli PlayerName?",
  ui_story_5089_50890802_88_dialog_content = "Saya menduga orang-orang itu belum pernah mengemudikan Huolong Carrier sebelumnya, benar?",
  ui_story_5089_50890802_89_dialog_content = "Dan dengan semua pengangkut yang bergerak bolak-balik dari workshop rahasia, tidak mungkin penduduk desa terdekat tidak melihat atau mendengar apa-apa. Dengan kata lain, tidak ada cara orang akan percaya itu ditinggalkan, setidaknya tidak baru-baru ini.",
  ui_story_5089_50890802_90_dialog_content = "Dan namun, entah bagaimana, tampaknya tidak ada yang tahu apa-apa tentang itu sampai sekarang.",
  ui_story_5089_50890802_91_dialog_content = "Itu hanya bisa berarti bahwa bengkel telah memastikan kerahasiaannya dengan menerima pengiriman kecil melalui beberapa pengiriman.",
  ui_story_5089_50890802_92_dialog_content = "Tapi sekarang, karena pesanan besar dari Fate Riders, mereka tampaknya menggunakan beberapa operator untuk mengangkut material yang diperlukan.",
  ui_story_5089_50890802_93_dialog_content = "Guild Artisan mengawasi penggunaan Huolong Carriers.",
  ui_story_5089_50890802_94_dialog_content = "Asosiasi itu sendiri terdiri dari pejabat dari kedua sekte utama, serta administrator yang ditunjuk oleh pengadilan kerajaan. Bersama-sama, mereka mengatur penggunaan Huolong Carriers.",
  ui_story_5089_50890802_95_dialog_content = "Bahkan raja sekalipun tidak bisa mengabaikan protokol mereka atau menggunakannya dengan bebas.",
  ui_story_5089_50890802_96_dialog_content = "Namun, mereka tidak memantau secara ketat orang-orang yang menyewa operator.",
  ui_story_5089_50890802_97_dialog_content = "Dengan kata lain, Fate Riders mungkin tidak mengalami kesulitan meminjam hak atas operator melalui salah satu bengkel tersebut, 'kan?",
  ui_story_5089_50890802_98_dialog_content = "Apakah kamu mengatakan bahwa kamu ingin menyelidiki setiap workshop?",
  ui_story_5089_50890802_99_dialog_content = "Tidak.",
  ui_story_5089_50890802_100_dialog_content = "Tidak perlu bagi kita untuk berhadapan langsung dengan mereka. Lagipula, Fate Riders lah yang kita incar.",
  ui_story_5089_50890802_101_dialog_content = "Sekarang setelah saya melihat dari luar, saya pikir saya mulai memahami \"momentum\" yang Xuan Ji bicarakan.",
  ui_story_5089_50890802_102_dialog_content = "Dantang! Guild Artisan hanya bertanggung jawab atas penyewaan pembawa, bukan?",
  ui_story_5089_50890802_103_dialog_content = "Ya, benar sekali.",
  ui_story_5089_50890802_104_dialog_content = "Lalu apa yang ingin aku beli...",
  ui_story_5089_50890802_105_dialog_content = "Apakah jejak-jejak itu sendiri.",
  ui_story_5089_50890802_106_dialog_content = "... Kamu benar-benar seorang jenius, PlayerName!",
  ui_story_5089_50890802_107_dialog_content = "<color=#e8d9bb>Workshop Rahasia</color>",
  ui_story_5089_50890802_108_dialog_content = "Apa masalah dengan Pembawa Huolong ini? Siapa yang memberi kalian izin untuk bertindak sendiri?!",
  ui_story_5089_50890802_109_dialog_content = "Perhatikan nada bicaramu. Aku malah baru mau menanyakan pertanyaan yang sama.",
  ui_story_5089_50890802_110_dialog_content = "Kalian terus mendesak kami untuk mengirimkan senjata, tetapi apa yang telah kalian lakukan selama ini?",
  ui_story_5089_50890802_111_dialog_content = "Jika kita tidak bisa memproduksi cukup banyak tepat waktu, kirim saja batch yang ditujukan untuk Kerajaan Ji. Itu tidak seharusnya terlalu sulit untukmu, bukan?",
  ui_story_5089_50890802_112_dialog_content = "... Jika kita gagal memenuhi pesanan Kerajaan Ji, itu mungkin mempengaruhi hubungan antara kedua negara kita.",
  ui_story_5089_50890802_113_dialog_content = "Ha, bahkan anak berusia tiga tahun pun tidak akan sepolos ini.",
  ui_story_5089_50890802_114_dialog_content = "Kami semua sekarang bersekutu dengan Fate Riders. Apakah saya benar-benar perlu memberitahu Anda perintah siapa yang harus diikuti? Hubungan antara dua kerajaan bukan lagi urusan kita.",
  ui_story_5089_50890802_115_dialog_content = "Kecuali... Jangan bilang kalau \"raja\" yang disebut-sebut itu menganggap dirinya sebagai penguasa sejati Kerajaan Ye?",
  ui_story_5089_50890802_116_dialog_content = "Tentu saja tidak.",
  ui_story_5089_50890802_117_dialog_content = "Baik. Saya mengerti bahwa dia pernah dihukum mati, tetapi kesetiaannya kepada Fate Riders adalah satu-satunya hal yang membuatnya tetap hidup sebagai raja hingga hari ini.",
  ui_story_5089_50890802_118_dialog_content = "Jika dia berani mengkhianati mereka, dia akan kehilangan segalanya secepat dia mendapatkannya.",
  ui_story_5089_50890802_119_dialog_content = "Namun lagi, dengan pemberontakan hampir di tangan, setiap kekacauan yang disebabkan oleh ketidakpatuhan negara-negara vasal juga akan bekerja untuk keuntungan kita.",
  ui_story_5089_50890802_120_dialog_content = "Tentu kamu mengerti sejauh itu, 'kan?",
  ui_story_5089_50890802_121_dialog_content = "... Tentu saja.",
  ui_story_5089_50890802_122_dialog_content = "Bagus, sekarang cepat dan muat barang-barangnya.",
  ui_story_5089_50890802_123_dialog_content = "Lady Zhui Hu, kami telah menemui masalah.",
  ui_story_5089_50890802_124_dialog_content = "Hah?",
  ui_story_5089_50890802_125_dialog_content = "Tampaknya kita tidak dapat menggunakan Carrier Huolong saat ini.",
  ui_story_5089_50890802_126_dialog_content = "Apa? Bukankah kita sudah membayar bengkel untuk memastikan penggunaan eksklusif dari carrier?!",
  ui_story_5089_50890802_127_dialog_content = "I-Itu bukan masalahnya. Hanya saja...",
  ui_story_5089_50890802_128_dialog_content = "Jalannya telah ditutup.",
  ui_story_5089_50890802_129_dialog_content = "Apa?!",
  ui_story_5089_50890901_1_dialog_content = "Kontribusi murah hati Anda telah membuat segalanya menjadi lebih sederhana, PlayerName.",
  ui_story_5089_50890901_2_dialog_content = "Setelah sementara waktu menyewa tanah di sekitar jalur, saya telah meminta orang-orang untuk menghalangi jalan menuju bengkel rahasia.",
  ui_story_5089_50890901_3_dialog_content = "Kami telah berhasil menghentikan Fate Riders di jejak mereka.",
  ui_story_5089_50890901_4_dialog_content = "Tapi tampaknya blokade kami mulai menimbulkan masalah bagi beberapa pedagang yang sedang bepergian—",
  ui_story_5089_50890901_5_dialog_content = "Tolong, teman-teman! Saya hanya di sini untuk mendapatkan beberapa biji-bijian. Saya tidak melakukan apa-apa yang salah!",
  ui_story_5089_50890901_6_dialog_content = "Tidak bisakah kamu membiarkan karavan kami lewat?",
  ui_story_5089_50890901_7_dialog_content = "Kamu berasal dari Kerajaan Ji, bukan?",
  ui_story_5089_50890901_8_dialog_content = "Kenapa, ya, aku. Apakah itu masalah? Aku bisa meyakinkan kamu bahwa semua dokumen bisnisku sudah beres...",
  ui_story_5089_50890901_9_dialog_content = "(Dantang.)",
  ui_story_5089_50890901_10_dialog_content = "(Benar.)",
  ui_story_5089_50890901_11_dialog_content = "Ehem, kau sadar dengan siapa kau sedang berbicara sekarang?",
  ui_story_5089_50890901_12_dialog_content = "Er, tidak... Aku tidak bisa bilang bahwa aku tahu...",
  ui_story_5089_50890901_13_dialog_content = "Ini adalah PlayerName, Tuhan dari Eraveil. Dia adalah utusan khusus dari tanah Astra dan pejabat terhormat yang ditunjuk secara pribadi oleh Raja Ji.",
  ui_story_5089_50890901_14_dialog_content = "Diberkati oleh Maiden Naga, dia adalah sekutu dekat dari Lin Guild, dan subjek dari pendekatan serius pangeran mahkota...",
  ui_story_5089_50890901_15_dialog_content = "(Baiklah, kamu sudah membuat poinmu! Kamu bisa melihat dia sudah yakin dari tatapan matanya, jadi cukuplah sudah!)",
  ui_story_5089_50890901_16_dialog_content = "Ah, ya, saya ingat sekarang! Melihat Anda sekali lagi adalah kehormatan terbesar yang bisa saya harapkan, Tuanku!",
  ui_story_5089_50890901_17_dialog_content = "Katakan padaku, bagaimana saya bisa membantu kamu? Saya akan melakukan apa saja yang kamu minta dari saya, selama itu dalam batas kemampuan saya... Tunggu, kamu adalah orang yang menyegel jalan itu, bukan?",
  ui_story_5089_50890901_18_dialog_content = "Maafkan saya atas ketidaktahuan saya, tuanku! Meskipun Anda mengusir saya sampai akhir waktu, saya tidak akan menyimpan rasa dendam!",
  ui_story_5089_50890901_19_dialog_content = "I-Ini bukan apa-apa yang serius. Saya hanya punya proposisi bisnis untukmu, itu saja.",
  ui_story_5089_50890901_20_dialog_content = "Dengan segala cara, tuanku! Saya akan menawarkan harga terbaik untuk apa pun yang Anda inginkan!",
  ui_story_5089_50890901_21_dialog_content = "Berapa banyak emas yang tersisa, Dantang?",
  ui_story_5089_50890901_22_dialog_content = "Setelah membayar untuk jalur, tanah di sekitarnya, dan upah para pengrajin... Kami hanya menggunakan sebagian kecil dari dana kami.",
  ui_story_5089_50890901_23_dialog_content = "Berikan dia istirahat, kalau begitu.",
  ui_story_5089_50890901_24_dialog_content = "Maaf…?",
  ui_story_5089_50890901_25_dialog_content = "Aku ingin menggunakan emas ini untuk membeli semua makanan yang telah kamu dapatkan dari Kerajaan Ye.",
  ui_story_5089_50890901_26_dialog_content = "Ah, tuanku... Ini merupakan tantangan yang cukup besar, kamu tahu...",
  ui_story_5089_50890901_27_dialog_content = "Aku tahu kamu bekerja untuk Raja Ji.",
  ui_story_5089_50890901_28_dialog_content = "!",
  ui_story_5089_50890901_29_dialog_content = "Kamu bisa bilang padanya bahwa kami memaksamu melakukannya, jika harus. Aku akan bertanggung jawab penuh atas semua ini.",
  ui_story_5089_50890901_30_dialog_content = "Saya mengerti... Saya kira saya bisa membuat pengecualian untuk Anda, Tuanku.",
  ui_story_5089_50890901_31_dialog_content = "Baik. Dan jangan khawatir, aku selalu menepati janjiku.",
  ui_story_5089_50890901_32_dialog_content = "Fiuh, akhirnya mereka pergi juga.",
  ui_story_5089_50890901_33_dialog_content = "Heheh.",
  ui_story_5089_50890901_34_dialog_content = "Ya, ya, silakan tertawa. Saya yakin akting \"bangsawan\" saya pasti menyenangkan untuk ditonton...",
  ui_story_5089_50890901_35_dialog_content = "Sama sekali tidak, PlayerName. Penampilanmu sangat memikat.",
  ui_story_5089_50890901_36_dialog_content = "Hmm?",
  ui_story_5089_50890901_37_dialog_content = "Orang-orang di sana itu...",
  ui_story_5089_50890901_38_dialog_content = "<color=#e8d9bb>Beberapa saat lalu-</color>",
  ui_story_5089_50890901_39_dialog_content = "Ketuk, ketuk, ketuk.",
  ui_story_5089_50890901_40_dialog_content = "Hah? Siapa mungkin itu di saat seperti ini?",
  ui_story_5089_50890901_41_dialog_content = "...",
  ui_story_5089_50890901_42_dialog_content = "Sister Xuan Ji! Saudara kita dari Guild Artisan mengatakan bahwa Caelestite itu adalah—",
  ui_story_5089_50890901_43_dialog_content = "Huh, berapa kali harus kubilang padamu, Qian Ji? Berhenti menyebut kita sebagai saudara ketika kita berada di istana.",
  ui_story_5089_50890901_44_dialog_content = "Meski kami tidak berniat untuk memihak, bukan ide yang baik untuk memberi mereka alasan untuk salah paham tentang kita.",
  ui_story_5089_50890901_45_dialog_content = "Ini yang menyebabkan Master Houfeng divonis waktu itu, ingat?",
  ui_story_5089_50890901_46_dialog_content = "Master Houfeng... Kamu maksud penemu dari sepuluh tahun lalu?",
  ui_story_5089_50890901_47_dialog_content = "Dari yang saya ingat, dia adalah seorang pengrajin \"rogue\" yang menolak untuk berpihak pada faksi mana pun, dan malah mencoba belajar dari setiap sumber yang bisa dibayangkan.",
  ui_story_5089_50890901_48_dialog_content = "Dia dikabarkan sangat berbakat, tetapi juga agak sombong karena itu. Meskipun kedua faksi berusaha memaksanya untuk bergabung dengan mereka, dia selalu menolak mereka.",
  ui_story_5089_50890901_49_dialog_content = "Dan setelah dia bergabung dengan pengadilan sebagai penasihat, dia dikenal karena mengusulkan banyak ide reformasi radikal.",
  ui_story_5089_50890901_50_dialog_content = "Dia mengusulkan untuk menghapus pembatasan perdagangan pada ciptaan jam mekanik dan menerapkan kontrol pengadilan atas sumber daya untuk semua faksi.",
  ui_story_5089_50890901_51_dialog_content = "Antusiasme dia untuk melayani negaranya tidak dapat disangkal, tetapi tindakannya terlalu ekstrem dan gagal mempertimbangkan realitas.",
  ui_story_5089_50890901_52_dialog_content = "Kamu tidak bisa menyalahkan orang lain jika kamu berakhir seperti dia, Lady Xuan Ji. Contohnya tidak seharusnya diikuti.",
  ui_story_5089_50890901_53_dialog_content = "Aku tahu, tetapi aku adalah warga kerajaan yang sangat patuh pada hukum. Apakah kamu tidak ingat betapa patuhnya aku ketika raja memutuskan untuk memenjarakanku?",
  ui_story_5089_50890901_54_dialog_content = "Sepertinya Anda lupa alasan Anda ditahan sejak awal.",
  ui_story_5089_50890901_55_dialog_content = "Apapun alasannya, saya yakin itu tidak ada hubungannya dengan saya yang mengutak-atik blaster arcane yang saya bantu desain sendiri.",
  ui_story_5089_50890901_56_dialog_content = "Oke, sekarang biarkan saya melihat surat itu.",
  ui_story_5089_50890901_57_dialog_content = "... Hahaha! Sungguh menarik. Seharusnya aku sudah mengharapkan ini dari PlayerName.",
  ui_story_5089_50890901_58_dialog_content = "Strateginya sedikit tidak ortodoks, tetapi sangat mengejutkan saya, tampaknya itu adalah langkah terbaik yang diberikan situasinya.",
  ui_story_5089_50890901_59_dialog_content = "Sepertinya dia akhirnya melihat segalanya dengan jelas.",
  ui_story_5089_50890901_60_dialog_content = "Dan apa sebenarnya itu?",
  ui_story_5089_50890901_61_dialog_content = "Tidak ada yang perlu dikhawatirkan. Bagaimanapun, aku akan membutuhkan bantuanmu untuk menyampaikan pesan sebentar lagi.",
  ui_story_5089_50890901_62_dialog_content = "Sebagai seorang pengrajin biasa yang tidak terlibat dalam politik, akan salah jika saya ikut campur dalam urusan ini.",
  ui_story_5089_50890901_63_dialog_content = "Tapi sebagai anggota Guild, sudah sepatutnya bagi saya untuk memberikan informasi jika itu berarti mengungkap pengkhianat di tengah kita.",
  ui_story_5089_50890901_64_dialog_content = "Jadi, berusahalah sebaik mungkin, saudara.",
  ui_story_5089_50890901_65_dialog_content = "Baiklah.",
  ui_story_5089_50890901_66_dialog_content = "Nah... Bagaimana kabarmu di sana, tetangga?",
  ui_story_5089_50890901_67_dialog_content = "...",
  ui_story_5089_50890901_68_dialog_content = "Itu aneh, kukira membicarakan tentang Master Houfeng akan membuatmu lebih terbuka.",
  ui_story_5089_50890901_69_dialog_content = "Bagaimanapun, latar belakangnya sekarang tampak begitu akrab. Seorang pria yang ditunjuk ke pengadilan kerajaan sepuluh tahun lalu, tetapi kemudian terlibat dalam pertarungan kekuasaannya dan, jatuh dari anugerah, tidak pernah terlihat atau terdengar lagi.",
  ui_story_5089_50890901_70_dialog_content = "Saya hanya bisa memikirkan satu orang yang memenuhi semua kriteria tersebut.",
  ui_story_5089_50890901_71_dialog_content = "... Itu sudah bukan urusanku lagi.",
  ui_story_5089_50890901_72_dialog_content = "Obsesi seumur hidupku tentang rasa syukur dan balas dendam hanyalah lelucon sekarang.",
  ui_story_5089_50890901_73_dialog_content = "Aku tidak lagi tahu cara menggunakan pedangku, yang berarti aku tidak lagi memiliki tujuan.",
  ui_story_5089_50890901_74_dialog_content = "Jadi tolong berhenti khawatir untukku, Lady Xuan Ji.",
  ui_story_5089_50890901_75_dialog_content = "Hidup untuk satu tujuan, dan pantas ditinggalkan jika kamu tidak lagi bisa mencapainya.",
  ui_story_5089_50890901_77_dialog_content = "Saya punya pertanyaan untuk Anda, Nona Jiu.",
  ui_story_5089_50890901_79_dialog_content = "...",
  ui_story_5089_50890901_80_dialog_content = "Apakah benar-benar ada perbedaan?",
  ui_story_5089_50890901_81_dialog_content = "Huh... Sepertinya saya tidak akan membuat banyak kemajuan di sini dalam waktu dekat.",
  ui_story_5089_50890901_82_dialog_content = "Sekarang terserah padamu, temanku.",
  ui_story_5089_50890901_83_dialog_content = "...",
  ui_story_5089_50890901_84_dialog_content = "Apakah ada yang mengganggu Anda, PlayerName?",
  ui_story_5089_50890901_86_dialog_content = "Maaf?",
  ui_story_5089_50890901_87_dialog_content = "Er, tidak ada apa-apa. Apakah kamu baru saja mengatakan sesuatu?",
  ui_story_5089_50890901_88_dialog_content = "Ya. Saya mengatakan bahwa jika Fate Riders benar-benar ingin menerobos rintangan kita, kita tidak akan bisa menghentikan mereka.",
  ui_story_5089_50890901_89_dialog_content = "Inilah mengapa saya sarankan kita memanggil bala bantuan.",
  ui_story_5089_50890901_90_dialog_content = "Kota Jingliang hanya dapat menampung sejumlah prajurit di dalam temboknya, jadi sebagian besar dari mereka ditempatkan di luar kota.",
  ui_story_5089_50890901_91_dialog_content = "Mereka mungkin tidak sekuat prajurit di dalam kota, tapi kami masih jelas kalah jumlah.",
  ui_story_5089_50890901_92_dialog_content = "Jadi, kau berpikir untuk menggunakan wewenangmu sebagai putri untuk membawa sebagian dari mereka ke pihak kita?",
  ui_story_5089_50890901_93_dialog_content = "Tidak, PlayerName.",
  ui_story_5089_50890901_94_dialog_content = "Tunggu... Kenapa tiba-tiba kamu memberikan belati ini padaku?!",
  ui_story_5089_50890901_95_dialog_content = "Mereka mungkin ditempatkan di luar kota, tetapi itu tidak membuat mereka kurang bersatu sebagai prajurit. Sampai sekarang, berita dari dalam kota pasti sudah sampai kepada mereka.",
  ui_story_5089_50890901_96_dialog_content = "Kita berdua tahu bahwa, pada titik ini, \"paman\"ku tidak memiliki alasan untuk tetap menentangku.",
  ui_story_5089_50890901_97_dialog_content = "Aman untuk diasumsikan bahwa mereka tidak akan menurutiku jika aku menunjukkan diriku kepada mereka.",
  ui_story_5089_50890901_98_dialog_content = "Jadi, kenapa kita di sini lalu?",
  ui_story_5089_50890901_99_dialog_content = "Untuk ini.",
  ui_story_5089_50890901_100_dialog_content = "... Kenapa kau memberiku belati?",
  ui_story_5089_50890901_101_dialog_content = "Kita tidak bisa yakin tentang perintah yang diberikan kepada prajurit di tempat ini.",
  ui_story_5089_50890901_102_dialog_content = "Tapi selama \"paman\"ku peduli tentang statusnya, dia tidak akan secara terbuka mengirim seseorang untuk membunuhku.",
  ui_story_5089_50890901_103_dialog_content = "Jika itu masalahnya, maka saya harus tetap dilihat sebagai seseorang yang membutuhkan perlindungan mereka. Oleh karena itu...",
  ui_story_5089_50890901_104_dialog_content = "Kamu ingin aku berpura-pura menculikmu dan membawa mereka semua ke bengkel?",
  ui_story_5089_50890901_105_dialog_content = "Tapi itu terlalu berisiko! Tidak ada yang bisa menebak apa yang bisa salah!",
  ui_story_5089_50890901_106_dialog_content = "Bagaimana jika mereka berhasil menangkap kita berdua sekaligus? Atau lebih buruk lagi, bagaimana jika raja palsu sudah memutuskan bahwa kamu tidak layak untuk tetap hidup?!",
  ui_story_5089_50890901_107_dialog_content = "Kita harus kembali dan memikirkan kembali strategi kita sebelum-",
  ui_story_5089_50890901_108_dialog_content = "<color=#e8d9bb>Tiba-tiba, Dantang meraih tangan yang aku gunakan untuk memegang belati, dan dengan cepat membawanya ke lehernya.</color>",
  ui_story_5089_50890901_109_dialog_content = "Dantang?!",
  ui_story_5089_50890901_110_dialog_content = "<color=#e8d9bb>Aku mencoba keras untuk menariknya, tapi belati itu masih meninggalkan bekas merah di lehernya.</color>",
  ui_story_5089_50890901_111_dialog_content = "Tolong perhatikan saya, PlayerName.",
  ui_story_5089_50890901_112_dialog_content = "<color=#e8d9bb>Sebutir darah meluncur turun di bilah pedang hingga ke telapak tanganku, tapi Dantang hanya tertawa kecil di bawah sinar matahari, yang menyaring melalui dedaunan hutan.</color>",
  ui_story_5089_50890901_113_dialog_content = "Saya percaya kamu.",
  ui_story_5089_50890901_114_dialog_content = "... Aku tahu.",
  ui_story_5089_50890901_115_dialog_content = "Siapa yang pergi ke sana?",
  ui_story_5089_50890901_116_dialog_content = "M-Mundur!",
  ui_story_5089_50890901_117_dialog_content = "Putri Zhuohua-mu kini ada di tangan saya!",
  ui_story_5089_50890901_118_dialog_content = "!",
  ui_story_5089_50890901_119_dialog_content = "Putri telah diculik! Semua prajurit berkumpul!",
  ui_story_5089_50890901_120_dialog_content = "Lepaskan Tuan Putri segera, dan mungkin nyawamu masih bisa diselamatkan!",
  ui_story_5089_50890901_121_dialog_content = "Kalian tidak menakutkanku! Dan selain itu, kalian benar-benar berpikir aku akan menyerah begitu saja?!",
  ui_story_5089_50890901_122_dialog_content = "Saya adalah anggota Fate Riders, dan benteng kami tidak terlalu jauh dari sini! Kami memiliki lebih banyak pejuang dan senjata daripada yang bisa kamu tangani!",
  ui_story_5089_50890901_123_dialog_content = "Jadi jangan membuat gerakan tiba-tiba, atau kita akan memiliki perang di tangan kita!",
  ui_story_5089_50890901_124_dialog_content = "Pemanah! Bidik!",
  ui_story_5089_50890901_125_dialog_content = "Force Boost!",
  ui_story_5089_50890901_126_dialog_content = "Urgh—",
  ui_story_5089_50890901_127_dialog_content = "Jangan biarkan dia kabur!",
  ui_story_5089_50890901_128_dialog_content = "Kami telah kehilangan jejak sang putri dan penculiknya, tuan!",
  ui_story_5089_50890901_129_dialog_content = "Lalu bubar dan carilah mereka, kau bodoh! Kita tidak bisa membiarkan apa pun terjadi pada sang putri!",
  ui_story_5089_50890901_130_dialog_content = "Tapi kita tidak memiliki petunjuk—Tunggu! Ada begonia di tanah di sini!",
  ui_story_5089_50890901_131_dialog_content = "Ini pasti petunjuk yang ditinggalkan oleh Tuan Putri. Cepat, cari lebih banyak lagi!",
  ui_story_5089_50890901_132_dialog_content = "Mereka mungkin bisa membawa kita ke tempat persembunyian mereka!",
  ui_story_5089_50890901_133_dialog_content = "Tuan saya, sekelompok prajurit dari luar kota sedang mendekati bengkel.",
  ui_story_5089_50890901_134_dialog_content = "Untuk alasan apa?",
  ui_story_5089_50890901_135_dialog_content = "Mereka mengatakan mereka bertemu dengan seorang pidana yang telah menculik tuan putri.",
  ui_story_5089_50890901_136_dialog_content = "Tidak berani kehilangan jejak mereka, kapten skuad mereka mengikuti jejak mereka ke lokasi ini.",
  ui_story_5089_50890901_137_dialog_content = "Jadi tidak hanya jalan-jalan yang diblokir, kami juga dikelilingi oleh pengawal kota.",
  ui_story_5089_50890901_138_dialog_content = "Kemungkinan besar pengepungan akan segera pecah.",
  ui_story_5089_50890901_139_dialog_content = "Jika itu terjadi, orang-orang kita harus mampu mempertahankan bengkel. Saya sarankan kita tetap menjaga mereka di posisi untuk saat ini.",
  ui_story_5089_50890901_140_dialog_content = "Namun, mereka masih tetap bersikeras untuk melihat apa yang sedang terjadi di sini.",
  ui_story_5089_50890901_141_dialog_content = "Heheh.",
  ui_story_5089_50890901_142_dialog_content = "Jadi itu strategi mereka, ya? Menyedihkan.",
  ui_story_5089_50890901_143_dialog_content = "Pergi.",
  ui_story_5089_50890901_144_dialog_content = "Jika mereka menginginkan saya untuk menunjukkan diri, maka sebagai raja, saya dengan senang hati akan menghadapi mereka.",
  ui_story_5089_50890901_145_dialog_content = "<color=#e8d9bb>Beberapa saat kemudian—</color>",
  ui_story_5089_50890901_146_dialog_content = "Syukurlah, mereka akhirnya pergi.",
  ui_story_5089_50890901_147_dialog_content = "Mereka bilang tempat tergelap adalah di bawah lampu, tetapi saya menemukan bahwa bersembunyi tepat di bawah hidung musuh selalu menjadi pilihan yang paling aman.",
  ui_story_5089_50890901_148_dialog_content = "Namun, saya tidak pernah mengira dia hanya akan duduk dan merenung sepanjang hari. Meski istana dalam keadaan yang sangat memprihatinkan, dia tidak pernah meminta siapa pun untuk memperbaikinya.",
  ui_story_5089_50890901_149_dialog_content = "Tapi berkat balok-balok lebar ini, saya bisa tetap tersembunyi tanpa membebani tulang-tulang tua saya terlalu banyak.",
  ui_story_5089_50890901_150_dialog_content = "Sekarang mereka sudah pergi, saya seharusnya bisa meninggalkan istana tanpa masalah.",
  ui_story_5089_50890901_151_dialog_content = "Hm? Bukankah ini... pedang milik Nona Jiu?",
  ui_story_5089_50890901_152_dialog_content = "Kurasa aku harus mengembalikannya padanya.",
  ui_story_5089_50890901_153_dialog_content = "*terengah-engah* Ya ampun... Selama ini... Aku berlari secepat yang kubisa...",
  ui_story_5089_50890901_154_dialog_content = "Bagaimana para prajurit itu bisa mengejar dengan begitu cepat?!",
  ui_story_5089_50890901_155_dialog_content = "Saya mencoba mengalihkan mereka dengan begonia saya sebaik mungkin, tetapi mereka melihat melaluinya lebih cepat dari yang saya bayangkan.",
  ui_story_5089_50890901_156_dialog_content = "Selain itu, pengejaran tanpa henti mereka membuktikan bahwa latihan mereka tidak kurang, bahkan di luar kota.",
  ui_story_5089_50890901_157_dialog_content = "Untuk \"paman\" saya yang memiliki tentara terlatih dengan baik di bawah komandonya dan gudang senjata itu...",
  ui_story_5089_50890901_158_dialog_content = "Apa yang mungkin direncanakan oleh Fate Riders...?",
  ui_story_5089_50890901_159_dialog_content = "Tidak ada gunanya memikirkannya sekarang. Kami sudah melakukan segala yang bisa kami lakukan.",
  ui_story_5089_50890901_160_dialog_content = "Mari kita ambil napas di sini sebentar.",
  ui_story_5089_50890901_161_dialog_content = "Saya belum melihat ada gerakan dari bengkel, tapi tidak ada yang bisa menebak bagaimana reaksi mereka saat melihat kita.",
  ui_story_5089_50890901_162_dialog_content = "<color=#e8d9bb>Di belakang kami, prajurit yang terlatih dengan baik menyebar dan mengelilingi kami. Obor di tangan mereka mewarnai langit malam dengan merah yang menyala-nyala.</color>",
  ui_story_5089_50890901_163_dialog_content = "<color=#e8d9bb>Di depan kami, workshop menunjukkan tanda-tanda aktivitas meskipun tidak ada orang yang terlihat. Tempat itu menggantung menyeramkan di atas kami, seperti binatang raksasa yang sedang bersiap untuk melompat.",
  ui_story_5089_50890901_164_dialog_content = "Aku tidak pernah punya kesempatan untuk memberitahumu ini sebelumnya, PlayerName.",
  ui_story_5089_50890901_165_dialog_content = "Meskipun dengan tidak malu-malu saya meminta bantuan Anda, saya sama sekali tidak berniat menempatkan Anda dalam situasi berbahaya seperti hari ini.",
  ui_story_5089_50890901_166_dialog_content = "Untuk ini, saya sangat menyesal.",
  ui_story_5089_50890901_167_dialog_content = "Jangan khawatir, Dantang. Saya memiliki perasaan kita akan baik-baik saja.",
  ui_story_5089_50890901_168_dialog_content = "Setelah semua, aku juga percaya padamu.",
  ui_story_5089_50890901_169_dialog_content = "Hah? Ada sesuatu yang terjadi dengan para prajurit...",
  ui_story_5089_50890901_170_dialog_content = "Raja telah tiba—",
  ui_story_5089_50890901_171_dialog_content = "Lihat, itu...",
  ui_story_5089_50890901_172_dialog_content = "Paman yang disebut-sebut itu.",
  ui_story_5089_50890901_173_dialog_content = "Oh Dantang, saya pikir Anda akan lebih pintar dari ini.",
  ui_story_5089_50890901_174_dialog_content = "Tidakkah kamu tahu bahwa dengan satu perintah dariku, workshop itu akan tetap sama sekali tidak tersentuh?",
  ui_story_5089_50890901_175_dialog_content = "Kalian adalah satu-satunya yang akan menemui ajal di sini, di tempat dimana tak seorang pun yang akan menemukan kalian.",
  ui_story_5089_50890901_176_dialog_content = "Kamu telah berjalan tepat ke dalam kuburanmu sendiri.",
  ui_story_5089_50890901_177_dialog_content = "Jika kau benar-benar paman saya, kau akan memiliki wewenang untuk membuang kami seperti itu.",
  ui_story_5089_50890901_178_dialog_content = "Tapi, kau tak berhak melakukannya sebagai penipu dan boneka!",
  ui_story_5089_50890901_179_dialog_content = "Di depan semua orang ini, kami akan mengungkap siapa diri Anda yang sebenarnya—Master Houfeng!",
  ui_story_5089_50890902_1_dialog_content = "Sekarang, PlayerName!",
  ui_story_5089_50890902_2_dialog_content = "Force Boost!",
  ui_story_5089_50890902_3_dialog_content = "Argh…",
  ui_story_5089_50890902_4_dialog_content = "(Para prajurit ini bukan target kita, jadi kita tidak seharusnya membuang waktu untuk melawan mereka.)",
  ui_story_5089_50890902_5_dialog_content = "(Para Fate Riders menggunakan topeng yang mirip daging untuk menyembunyikan diri mereka.)",
  ui_story_5089_50890902_6_dialog_content = "(Semua yang aku butuhkan adalah satu celah saja... Untuk merobek topengnya—!)",
  ui_story_5089_50890902_7_dialog_content = "Apa?!",
  ui_story_5089_50890902_8_dialog_content = "<color=#e8d9bb>Belati menemukan sasarannya di sisi wajah raja palsu.</color>",
  ui_story_5089_50890902_9_dialog_content = "<color=#e8d9bb>Tapi yang dipotong bukanlah topeng anorganik yang mereka harapkan.</color>",
  ui_story_5089_50890902_10_dialog_content = "<color=#e8d9bb>Sebaliknya, darah mulai merembes keluar dari luka, menunjukkan bahwa wajah target sepenuhnya nyata.</color>",
  ui_story_5089_50890902_11_dialog_content = "Bagaimana ini mungkin...?",
  ui_story_5089_50890902_12_dialog_content = "Sekarang hampir semua sudah terkonfirmasi.",
  ui_story_5089_50890902_13_dialog_content = "Beritahu saya, apakah Anda menyukai hasilnya?",
  ui_story_5089_50891001_1_dialog_content = "Y-Yang Mulia...! Jangan hanya berdiri di sana, kalian bodoh! Lindungi raja!",
  ui_story_5089_50891001_2_dialog_content = "Berhenti, semua kalian. Ini hanyalah seorang anak kecil yang sedang membuat keributan.",
  ui_story_5089_50891001_3_dialog_content = "Tidak... Anda tidak mungkin menjadi Raja Ye yang sejati, jadi mengapa...?",
  ui_story_5089_50891001_4_dialog_content = "Jika semua rencanamu hanya untuk momen ini, maka kebodohanmu bahkan lebih besar dari yang saya bayangkan.",
  ui_story_5089_50891001_5_dialog_content = "Saya telah menggunakan identitas ini selama bertahun-tahun, dan tidak ada yang melihat sesuatu yang tidak biasa.",
  ui_story_5089_50891001_6_dialog_content = "Apakah kamu benar-benar berpikir bahwa ini bisa diselesaikan dengan sesuatu yang sederhana seperti topeng?",
  ui_story_5089_50891001_7_dialog_content = "!",
  ui_story_5089_50891001_8_dialog_content = "Tentu saja tidak. Selama sepuluh tahun terakhir, saya telah membuat penyesuaian kecil dan bertahap pada penampilan saya.",
  ui_story_5089_50891001_9_dialog_content = "Memotong dan mengukir daging dan tulangku sendiri, semua demi mendapatkan penyamaran yang sempurna.",
  ui_story_5089_50891001_10_dialog_content = "Ketika lengan saya tidak cukup panjang, saya membiarkannya patah agar bisa tumbuh lebih panjang.",
  ui_story_5089_50891001_11_dialog_content = "Ketika suaraku tidak cukup cocok, aku berkumur dengan racun untuk membentuk ulang tenggorokan dan pita suaraku.",
  ui_story_5089_50891001_12_dialog_content = "Saya diberitahu bahwa sebelum dia naik ke tahta, paman saya sering menjadi sasaran pembunuhan... Saya mengerti sekarang.",
  ui_story_5089_50891001_13_dialog_content = "Anda tentu saja telah berbuat lebih dari yang seharusnya untuk Fate Riders.",
  ui_story_5089_50891001_14_dialog_content = "The Fate Riders, kata kamu? Ha! Pengecut-pengecut itu tidak berbeda dengan tikus-tikus yang menginfestasi bayangan kerajaan.",
  ui_story_5089_50891001_15_dialog_content = "Serangga yang tidak tahu diri itu sangat salah jika mereka berpikir mereka bisa menantang raja yang sah dari Kerajaan Ye!",
  ui_story_5089_50891001_16_dialog_content = "Kamu...",
  ui_story_5089_50891001_17_dialog_content = "Ritual tahunan penindasan kami mulai gagal, dan kaisar baru terlalu muda dan tidak berpengalaman untuk membimbing kami melewati badai yang akan datang. Jika tidak ada perubahan, tanah kami akan segera tenggelam dalam kegelapan.",
  ui_story_5089_50891001_18_dialog_content = "Awalnya, saya berniat untuk berhati-hati dalam bertindak untuk menjaga hubungan kita dengan Kerajaan Ji.",
  ui_story_5089_50891001_19_dialog_content = "Tetapi dengan keadaan seperti sekarang, saya tidak melihat masalah dengan menyerahkan semua senjata kita kepada Fate Riders.",
  ui_story_5089_50891001_20_dialog_content = "Dengan senjata api di tangan mereka, pemberontakan mereka akan dimulai lebih cepat.",
  ui_story_5089_50891001_21_dialog_content = "Selama bertahun-tahun, Fate Riders telah menyusup ke pengadilan berbagai kerajaan Longzhou. Banjir di Haojin hanya menunjukkan apa yang akan menimpa negara-negara vasal lainnya. Begitu mereka sibuk dengan krisis mereka sendiri, Fate Riders akan sekali lagi menargetkan ibu kota kekaisaran Yangjing.",
  ui_story_5089_50891001_22_dialog_content = "Saat belalang sembah mengintai jangkrik, burung pipit menunggu dengan sabar untuk mengklaim rampasan dari pertempuran mereka.",
  ui_story_5089_50891001_23_dialog_content = "Selama bertahun-tahun, aku menunggu waktu yang tepat, menunggu hembusan angin yang sempurna, tapi itu tidak pernah datang.",
  ui_story_5089_50891001_24_dialog_content = "Aku menolak untuk menunggu lebih lama. Aku akan menjadi angin yang membawaku menuju kemenangan!",
  ui_story_5089_50891001_25_dialog_content = "Selama sepuluh tahun yang panjang, saya telah melatih pasukan saya tanpa lelah sehingga mereka akan siap untuk perang kapan saja.",
  ui_story_5089_50891001_26_dialog_content = "Ketika kekuatan dari tanah-tanah ini akhirnya bertabrakan, pemenangnya tidak selalu ditentukan oleh kekuatan dari Fate Riders.",
  ui_story_5089_50891001_27_dialog_content = "Kamu telah mengungkap rahasiaku, Dantang.",
  ui_story_5089_50891001_28_dialog_content = "Tapi meskipun kebodohanmu, bakatmu masih sangat berharga bagi kerajaan. Apakah kamu bersedia untuk terus mengikutiku sebagai raja mu?",
  ui_story_5089_50891001_29_dialog_content = "Cukup anggukkan kepalamu, dan aku jamin bahwa kamu akan tetap menjadi Putri Zhuohua dari Kerajaan Ye.",
  ui_story_5089_50891001_30_dialog_content = "Sebagai Caelestite, keterampilanmu juga tidak diragukan lagi akan sangat berguna untukku dalam pertempuran. Apakah kamu akan menyelaraskan dirimu dengan tujuan noble ku?",
  ui_story_5089_50891001_31_dialog_content = "Sebentar lagi, tujuh kerajaan di Longzhou akan jatuh di bawah kekuasaan saya...",
  ui_story_5089_50891001_32_dialog_content = "Apakah kamu sadar bahwa Fate Riders telah bersekongkol dengan roh-roh jahat, dan bahwa banyak nyawa telah hilang akibat pengkhianatan mereka?",
  ui_story_5089_50891001_33_dialog_content = "Tentu saja. Saya sangat paham metode mereka, mengingat Kerajaan Ye adalah sumber utama senjata mereka.",
  ui_story_5089_50891001_34_dialog_content = "Tapi mengapa saya harus peduli dengan kehidupan orang lain jika mereka tidak bisa berguna bagi saya? Mencemaskan subjek dari musuh bebuyutan saya adalah menunjukkan kelemahan sebagai penakluk.",
  ui_story_5089_50891001_35_dialog_content = "Adapun roh-roh jahat, mereka tidak berbeda dengan binatang liar. Jika Fate Riders cukup tidak tahu malu untuk memanfaatkan mereka dalam metode mereka, maka biarlah begitu.",
  ui_story_5089_50891001_36_dialog_content = "Saya selalu bisa membuangnya nanti, jika keadaan memaksa.",
  ui_story_5089_50891001_37_dialog_content = "Aku mengerti pandanganmu, tapi sepertinya—",
  ui_story_5089_50891001_38_dialog_content = "Bahwa jalur kami terlalu berbeda untuk bisa sejajar.",
  ui_story_5089_50891001_39_dialog_content = "Saya sangat menyarankan agar kamu tidak menentang saya, Tuan Putri.",
  ui_story_5089_50891001_40_dialog_content = "Uh... Bolehkah saya bertanya sesuatu?",
  ui_story_5089_50891001_41_dialog_content = "Apakah benar-benar baik-baik saja bagi kamu untuk mengatakan semua ini dengan lantang?",
  ui_story_5089_50891001_42_dialog_content = "Ada sebuah workshop penuh dengan Fate Riders tepat di sebelah kita.",
  ui_story_5089_50891001_43_dialog_content = "Saya sudah memerintahkan orang-orangku untuk mengunci bengkel itu. Tidak seperti kamu, saya berusaha keras untuk mempersiapkan langkah selanjutnya.",
  ui_story_5089_50891001_44_dialog_content = "Para Fate Riders berambisi untuk mencapai hal-hal besar tetapi masih mengandalkan kekuatan tembakan saya.",
  ui_story_5089_50891001_45_dialog_content = "Setelah senjata telah disampaikan, saya tidak punya alasan untuk peduli apakah orang-orang di bengkel itu hidup atau mati.",
  ui_story_5089_50891001_46_dialog_content = "Jadi apa yang akan terjadi jika kamu tidak bisa mengirim senjata-senjatamu dalam tiga hari ke depan?",
  ui_story_5089_50891001_47_dialog_content = "... Bagaimana Anda mengetahui tentang itu?",
  ui_story_5089_50891001_48_dialog_content = "Nah, aku telah diberitahu bahwa kemampuanku sebagai seorang Caelestite sangat berguna tanpa diragukan lagi.",
  ui_story_5089_50891001_49_dialog_content = "Tapi lebih penting lagi, saya cukup yakin Anda tidak akan bisa memenuhi tenggat waktu Anda lagi.",
  ui_story_5089_50891001_50_dialog_content = "Apa yang telah kau lakukan?",
  ui_story_5089_50891001_51_dialog_content = "Raja Agung! Ada masalah—",
  ui_story_5089_50891001_52_dialog_content = "Bicaralah!",
  ui_story_5089_50891001_53_dialog_content = "Ini adalah Artisan's Guild! Orang-orang mereka sedang membongkar jalur pembawa Huolong saat ini! Semua rute transportasi yang kami rencanakan sebelumnya tidak dapat digunakan!",
  ui_story_5089_50891001_54_dialog_content = "Siapa yang membiarkan hal seperti itu terjadi?!",
  ui_story_5089_50891001_55_dialog_content = "Guild mengklaim bahwa—",
  ui_story_5089_50891001_56_dialog_content = "Seorang filantropis kaya membuat donasi yang murah hati untuk beberapa perbaikan yang sangat dibutuhkan, itu saja.",
  ui_story_5089_50891001_57_dialog_content = "Rel sepenuhnya aus karena diabaikan dan disalahgunakan oleh operator pengangkut.",
  ui_story_5089_50891001_58_dialog_content = "Syarat satu-satunya adalah menentukan urutan perbaikan trek. Permintaan yang cukup sederhana, bukan?",
  ui_story_5089_50891001_59_dialog_content = "Bahkan membantu kami mengalihkan perhatian Anda ke masalah serius yang mempengaruhi kerajaan Anda.",
  ui_story_5089_50891001_60_dialog_content = "Mereka sudah menyelesaikan sebagian besar pekerjaan pembongkaran. Bahkan jika kamu mulai membangun kembali jalur sekarang, akan membutuhkan waktu lebih dari tiga hari untuk menyelesaikannya.",
  ui_story_5089_50891001_61_dialog_content = "Dari awal, ini adalah \"jalan\" yang ingin saya tempuh... Jika kamu memaafkan leluconnya.",
  ui_story_5089_50891001_62_dialog_content = "Tipu daya licikmu tidak akan pernah berhasil! Semua yang dibutuhkan hanyalah perintah dari raja untuk—",
  ui_story_5089_50891001_63_dialog_content = "Diam, bodoh!",
  ui_story_5089_50891001_64_dialog_content = "Mungkin kamu benar: mungkin taktikku memang licik.",
  ui_story_5089_50891001_65_dialog_content = "Tapi kamu seharusnya tahu sekarang bahwa kita tidak lagi fokus pada cara-cara tersebut.",
  ui_story_5089_50891001_66_dialog_content = "Untuk Persekutuan Artisan berpihak padamu... Apakah ini ulah Ministress Armilla?",
  ui_story_5089_50891001_67_dialog_content = "Dia tidak dipenjara karena mengutak-atik blaster arcane, tetapi karena membongkar rahasia Anda. Bukankah begitu, \"Yang Mulia\"?",
  ui_story_5089_50891001_68_dialog_content = "Sejak saat kamu gagal mengurungnya sepenuhnya, kamu kalah.",
  ui_story_5089_50891001_69_dialog_content = "Bahkan jika kau berhasil mempertahankan takhta Kerajaan Ye—",
  ui_story_5089_50891001_70_dialog_content = "Setiap pejabat pengadilan dan pengrajin di Longzhou mungkin sedang mengawasi setiap gerakan Anda dari bayangan sekarang.",
  ui_story_5089_50891001_71_dialog_content = "Hari ini, jalur carrier sedang dibongkar, tetapi besok, mungkin ada kerusakan pada lembu kayu.",
  ui_story_5089_50891001_72_dialog_content = "Meski kamu beralih ke kereta kuda, kuda-kuda tersebut mungkin tidak cukup kuat untuk terus bergerak.",
  ui_story_5089_50891001_73_dialog_content = "Tanpa Carrier Huolong, saya bayangkan akan mustahil untuk mengangkut jumlah barang besar dengan cepat.",
  ui_story_5089_50891001_74_dialog_content = "Tapi, yang paling penting tentu saja...",
  ui_story_5089_50891001_75_dialog_content = "Seberapa sulitkah menjelaskan kepada kerajaanmu mengapa kamu mengirim begitu banyak senjata api keluar negeri?",
  ui_story_5089_50891001_76_dialog_content = "...",
  ui_story_5089_50891001_77_dialog_content = "Saya minta maaf, \"Yang Mulia\".",
  ui_story_5089_50891001_78_dialog_content = "Terlepas dari apa yang terjadi selanjutnya...",
  ui_story_5089_50891001_79_dialog_content = "\"Momentum\" saat ini sedang menguntungkan saya.",
  ui_story_5089_50891001_80_dialog_content = "Aku tahu.",
  ui_story_5089_50891001_81_dialog_content = "Jalan yang kamu halangi bukanlah takdir, tapi milikku.",
  ui_story_5089_50891001_82_dialog_content = "Ketika kamu bilang kami sedang masuk ke dalam jebakan, pernahkah kamu pertimbangkan bahwa sebenarnya kami yang sedang menjebakmu?",
  ui_story_5089_50891001_83_dialog_content = "Kamu sudah tidak punya pilihan lagi, Master Houfeng.",
  ui_story_5089_50891001_84_dialog_content = "Jika kamu gagal mengirimkan senjata tepat waktu, Fate Riders pasti akan datang untuk menyelidiki.",
  ui_story_5089_50891001_85_dialog_content = "Berdasarkan apa yang baru saja Anda katakan, kesetiaan Anda kepada Junming sangat dipertanyakan. Tindakan Anda, saya khawatir, mungkin tidak dapat menahan pemeriksaan mereka.",
  ui_story_5089_50891001_86_dialog_content = "Sekarang bisakah kita duduk dan berdiskusi dengan sopan?",
  ui_story_5089_50891001_88_dialog_content = "Diskusi sipil, kata kamu? Hahaha! Apakah kamu lupa bahwa aku masih raja?",
  ui_story_5089_50891001_89_dialog_content = "Nasib Kerajaan Ye sepenuhnya ada di tanganku!",
  ui_story_5089_50891001_90_dialog_content = "Aku menolak membiarkan salah satu dari kalian menghalangi ku—!",
  ui_story_5089_50891001_91_dialog_content = "<color=#e8d9bb>Menyembur—</color>",
  ui_story_5089_50891001_92_dialog_content = "<color=#e8d9bb>Terheard suara tumpul pedang menembus daging.</color>",
  ui_story_5089_50891001_93_dialog_content = "<color=#e8d9bb>Tak lama kemudian, darah mulai memercik ke semua arah.</color>",
  ui_story_5089_50891001_94_dialog_content = "Houfeng—!",
  ui_story_5089_50891001_95_dialog_content = "<color=#e8d9bb>Dari belakang, sebuah kait logam yang tajam menembus tubuh raja palsu.</color>",
  ui_story_5089_50891001_96_dialog_content = "Itu... Sebuah Stinger!",
  ui_story_5089_50891001_97_dialog_content = "*Huff* Kenapa kau tidak bisa diam saja dan mengikuti perintah?",
  ui_story_5089_50891001_98_dialog_content = "Tidak seperti ciptaan mesin jam yang indah milikku, yang merupakan hasil dari penelitian ekstensif dan perencanaan yang sabar...",
  ui_story_5089_50891001_99_dialog_content = "Ambisi gegabah dan tidak realistis seperti milikmu bisa menjadi mematikan.",
  ui_story_5089_50891001_100_dialog_content = "Kamu... Beraninya kamu...!",
  ui_story_5089_50891001_101_dialog_content = "Putri membuat poin yang valid.",
  ui_story_5089_50891001_102_dialog_content = "Kamu terlalu meremehkan Fate Riders.",
  ui_story_5089_50891001_103_dialog_content = "Masterku telah menetapkan bahwa Kerajaan Ye tidak lagi berfungsi bagi kami.",
  ui_story_5089_50891001_104_dialog_content = "Saya telah diberi kebebasan penuh atas tanahmu, dan saya akan mulai dengan menguji kekuatan penuh dari Stinger saya!",
  ui_story_5089_50891001_105_dialog_content = "Dan saya berhutang semuanya kepada Anda, raja yang perkasa. Jika Anda tidak memberi saya Zhuyin Flame, tidak ada dari ini yang akan terjadi! Hahaha!",
  ui_story_5089_50891001_106_dialog_content = "Nah... Saya percaya perintahku adalah meratakan gunung di sana.",
  ui_story_5089_50891001_107_dialog_content = "Sesuaikan target dan mulai mengisi daya, Stinger. Kita masih memiliki banyak pekerjaan yang harus dilakukan.",
  ui_story_5089_50891001_108_dialog_content = "<color=#e8d9bb>Stinger dengan ganas mencabut ekornya dari raja palsu, yang jatuh terguling ke tanah.</color>",
  ui_story_5089_50891001_109_dialog_content = "Benar, aku hampir lupa tentang pengkhianat yang tidak berguna ini...",
  ui_story_5089_50891001_110_dialog_content = "Atas perintah dari Fate Riders, eksekusi pria ini!",
  ui_story_5089_50891001_111_dialog_content = "Yang Mulia—",
  ui_story_5089_50891001_112_dialog_content = "<color=#e8d9bb>Pengawal kerajaan bersiap untuk menerobos masuk, tetapi sesuatu membuat barisan mereka menjadi kacau balau.</color>",
  ui_story_5089_50891001_113_dialog_content = "<color=#e8d9bb>Untuk kejutan mereka, beberapa prajurit mengangkat senjata mereka dan mulai menyerang kawan-kawan mereka!</color>",
  ui_story_5089_50891001_114_dialog_content = "Ini tidak baik! Raja berada di—",
  ui_story_5089_50891001_115_dialog_content = "Begonia yang Bersinar!",
  ui_story_5089_50891001_116_dialog_content = "Kamu...",
  ui_story_5089_50891001_117_dialog_content = "Jangan salah paham, aku tidak berniat bersekutu denganmu.",
  ui_story_5089_50891001_118_dialog_content = "Tapi selama kamu hidup, kita bisa melawan para Fate Riders.",
  ui_story_5089_50891001_119_dialog_content = "Ada juga masalah menuntut Anda bertanggung jawab atas kejahatan Anda.",
  ui_story_5089_50891001_120_dialog_content = "Uhuk... Memangnya kenapa repot-repot...",
  ui_story_5089_50891001_121_dialog_content = "Jika kamu tidak kabur sekarang... Kamu tidak akan hidup... Untuk menyesalinya.",
  ui_story_5089_50891001_122_dialog_content = "Penyesalan satu-satunya adalah saya tidak mempertaruhkan segalanya dan menggantikanmu lebih cepat.",
  ui_story_5089_50891001_123_dialog_content = "Di kaki gunung itu ada banyak warga sipil yang tak bersalah, serta ladang yang memberi mereka makan dan hidup.",
  ui_story_5089_50891001_124_dialog_content = "Jika aku melarikan diri sekarang, aku tidak akan pernah bisa menyebut diriku sebagai Tuan Putri Kerajaan Ye lagi.",
  ui_story_5089_50891001_125_dialog_content = "Jadi di sinilah aku berdiri, dan PlayerName tidak berbeda. Sudah terlambat untuk berbalik dan lari sekarang!",
  ui_story_5089_50891001_126_dialog_content = "Heh... Sungguh mengejutkan... Aku tak pernah tahu...",
  ui_story_5089_50891001_127_dialog_content = "Bahkan kamu lebih sombong daripada aku.",
  ui_story_5089_50891001_128_dialog_content = "Tapi kata-kata tidak berarti apa-apa... Jika kamu tidak berhasil bertahan hidup.",
  ui_story_5089_50891001_129_dialog_content = "<color=#e8d9bb>Saat para pengawal kerajaan terus berperang satu sama lain, sekelompok lain dari pembunuh Fate Rider bergegas keluar dari bengkel!</color>",
  ui_story_5089_50891002_1_dialog_content = "Jika pertempuran terus berlanjut seperti ini, aku khawatir peluang akan berpihak kepada mereka.",
  ui_story_5089_50891002_2_dialog_content = "Nona Jiu.",
  ui_story_5089_50891002_3_dialog_content = "Apakah kamu benar-benar tidak punya apa-apa untuk dikatakan tentang semua ini?",
  ui_story_5089_50891002_4_dialog_content = "...",
  ui_story_5089_50891002_5_dialog_content = "Hah…?",
  ui_story_5089_50891002_6_dialog_content = "Siapa di sana?!",
  ui_story_5089_50891002_7_dialog_content = "Penguasa kita telah memerintahkan kami untuk membasmi mereka yang menghalangi jalan kami.",
  ui_story_5089_50891002_8_dialog_content = "Hmph, jadi mereka juga telah menyusup ke istana.",
  ui_story_5089_50891002_9_dialog_content = "Kilat Flash!",
  ui_story_5089_50891002_10_dialog_content = "...",
  ui_story_5089_50891002_11_dialog_content = "!",
  ui_story_5089_50891002_12_dialog_content = "Minggir!",
  ui_story_5089_50891002_13_dialog_content = "Nyonya Jiu, meskipun kamu memutuskan untuk mengabaikan segala hal lain yang terjadi di sekitarmu...",
  ui_story_5089_50891002_14_dialog_content = "Apakah kamu benar-benar akan membiarkan dirimu dibunuh oleh tikus-tikus pengecut ini yang terlalu takut untuk menunjukkan wajah mereka sendiri?!",
  ui_story_5089_50891002_15_dialog_content = "...",
  ui_story_5089_50891101_1_dialog_content = "Eurgh—",
  ui_story_5089_50891101_2_dialog_content = "Tetap semangat, Dantang! Kita hampir—Ugh...",
  ui_story_5089_50891101_3_dialog_content = "PlayerName! Gawat... Kamu terbakar!",
  ui_story_5089_50891101_4_dialog_content = "Tidak apa-apa; aku hanya terlalu memaksakan kemampuanku. Aku akan baik-baik saja sebentar lagi...",
  ui_story_5089_50891101_5_dialog_content = "Tentu saja, bagi saya tidak terlihat begitu!",
  ui_story_5089_50891101_6_dialog_content = "... Tunggu.",
  ui_story_5089_50891101_7_dialog_content = "Kita sudah cukup lama saling kenal hingga saya cukup mengerti kemampuan Anda.",
  ui_story_5089_50891101_8_dialog_content = "Kita mungkin kalah jumlah, tapi bahkan pertempuran dengan intensitas seperti ini seharusnya tidak cukup untuk membuat kamu kelelahan seperti ini.",
  ui_story_5089_50891101_9_dialog_content = "Apa lagi yang sudah kaulakukan?",
  ui_story_5089_50891101_10_dialog_content = "... Sepertinya jig sudah habis.",
  ui_story_5089_50891101_11_dialog_content = "Maaf, sebenarnya aku ingin memberitahumu, tetapi aku tidak pernah menemukan kesempatan yang tepat.",
  ui_story_5089_50891101_12_dialog_content = "Tapi sekarang... Saya rasa lebih cepat kalau langsung kutunjukkan saja pada kamu.",
  ui_story_5089_50891101_13_dialog_content = "?",
  ui_story_5089_50891101_14_dialog_content = "Pemindaian Psikis!",
  ui_story_5089_50891101_15_dialog_content = "Jadi, akhirnya kamu tiba.",
  ui_story_5089_50891101_16_dialog_content = "Kamu telah membuatku menunggu cukup lama, Tuan Putri.",
  ui_story_5089_50891101_17_dialog_content = "Menteri Armilla! Tapi... Kenapa kau...",
  ui_story_5089_50891101_18_dialog_content = "Sebanyak apapun saya ingin mengejar ketinggalan, saya masih memiliki beberapa tamu yang tidak diinginkan untuk dihadapi di ujung saya.",
  ui_story_5089_50891101_19_dialog_content = "Xuan Ji, di belakangmu!",
  ui_story_5089_50891101_20_dialog_content = "Kilat Flash!",
  ui_story_5089_50891101_21_dialog_content = "Sangat dihargai, PlayerName.",
  ui_story_5089_50891101_22_dialog_content = "Apakah selama ini kamu yang memandu kedua pertempuran kita, PlayerName?! Tidak heran bebanmu begitu besar!",
  ui_story_5089_50891101_23_dialog_content = "Jika kamu khawatir tentang hal itu, kamu harus bertanya kepadanya berapa lama dia menjaga hubungan psikisnya dengan saya. Jawabannya mungkin akan mengejutkanmu!",
  ui_story_5089_50891101_24_dialog_content = "...",
  ui_story_5089_50891101_25_dialog_content = "PlayerName?",
  ui_story_5089_50891101_26_dialog_content = "Ini... Ini belum lama... Saya baru mulai berkomunikasi dengan Xuan Ji kemarin.",
  ui_story_5089_50891101_27_dialog_content = "Ya. Untuk sehari semalam, tepatnya.",
  ui_story_5089_50891101_28_dialog_content = "Ini salahmu sendiri karena tidak menjelaskan hal-hal dengan lebih jelas, tahu...",
  ui_story_5089_50891101_29_dialog_content = "Selain itu, saya telah berhati-hati untuk tidak menjaga hubungan kuat dengannya kecuali jika terjadi keadaan darurat...",
  ui_story_5089_50891101_30_dialog_content = "Namun, untuk mempertahankan bahkan koneksi yang lemah, berarti kau belum tidur selama ini.",
  ui_story_5089_50891101_31_dialog_content = "...",
  ui_story_5089_50891101_32_dialog_content = "Bukan hanya aku juga.",
  ui_story_5089_50891101_33_dialog_content = "Kamu benar... Saya juga berhutang maaf kepada Jiu.",
  ui_story_5089_50891101_34_dialog_content = "Apa yang kamu katakan semalam membuatku khawatir bahwa kamu akan melakukan sesuatu yang ceroboh, jadi aku diam-diam terhubung denganmu untuk berjaga-jaga.",
  ui_story_5089_50891101_35_dialog_content = "Saya juga melihat pertempuranmu dengan Raja Ye.",
  ui_story_5089_50891101_36_dialog_content = "Aku paham bagaimana perasaanmu, tapi...",
  ui_story_5089_50891101_37_dialog_content = "Awas!",
  ui_story_5089_50891101_38_dialog_content = "Nng...",
  ui_story_5089_50891101_39_dialog_content = "Dantang! Apakah kamu baik-baik saja?!",
  ui_story_5089_50891101_40_dialog_content = "!",
  ui_story_5089_50891101_41_dialog_content = "Tolong, Jiu! Saya tahu kamu sedang dalam keadaan yang sangat buruk sekarang, tapi kami butuh bantuanmu!",
  ui_story_5089_50891101_42_dialog_content = "Tapi... Tapi aku...",
  ui_story_5089_50891101_43_dialog_content = "<color=#e8d9bb>Jiu berhenti sejenak dan menghela nafas panjang.</color>",
  ui_story_5089_50891101_44_dialog_content = "<color=#e8d9bb>Tanpa mengucapkan sepatah kata pun, dia mengambil belati yang dijatuhkan oleh pembunuh Fate Rider dan menusukkannya kepadanya.</color>",
  ui_story_5089_50891101_45_dialog_content = "!",
  ui_story_5089_50891101_46_dialog_content = "<color=#e8d9bb>Dia menghindar dalam kepanikan, tetapi belati hanya menggoresnya sebelum terlepas dari tangan Jiu dan beradu dengan dinding.</color>",
  ui_story_5089_50891101_47_dialog_content = "Nona Jiu, kamu...",
  ui_story_5089_50891101_48_dialog_content = "Di masa lalu, pedangku tak berbeda dari tubuhku.",
  ui_story_5089_50891101_49_dialog_content = "Apakah terluka atau bernoda darah, itu tidak membuat perbedaan bagi saya.",
  ui_story_5089_50891101_50_dialog_content = "Jalur pedangku jelas—Rasa syukur adalah yang membimbing setiap ayunan dan setiap pukulan.",
  ui_story_5089_50891101_51_dialog_content = "Tapi sekarang, ketika jalanku tidak lagi jelas, kemampuan pedangku juga telah meninggalkanku.",
  ui_story_5089_50891101_52_dialog_content = "Seperti yang kamu lihat, aku tidak bisa lagi menggunakan pedang.",
  ui_story_5089_50891101_53_dialog_content = "Jiu...",
  ui_story_5089_50891101_54_dialog_content = "Fokus pada pertempuran, PlayerName. Kita tidak punya waktu untuk memikirkan orang yang tidak relevan seperti dia lagi.",
  ui_story_5089_50891101_55_dialog_content = "Awalnya saya ragu, tapi sekarang saya melihat bahwa melepaskan tugasnya sebagai penjaga saya adalah pilihan yang tepat.",
  ui_story_5089_50891101_56_dialog_content = "D-Dantang?",
  ui_story_5089_50891101_57_dialog_content = "Selama sepuluh tahun, dia mengabdikan dirinya pada seni pedang, tetapi sekarang dia bersedia membuang semuanya tanpa berpikir dua kali.",
  ui_story_5089_50891101_58_dialog_content = "Gurunya, yang disebut-sebut sebagai \"pendekar terhebat di dunia,\" tampaknya tidak lebih dari sebuah nama tanpa substansi.",
  ui_story_5089_50891101_59_dialog_content = "... Kurangnya keterampilan saya bukan alasan untuk memfitnah nama tuan saya seperti ini, Yang Mulia.",
  ui_story_5089_50891101_60_dialog_content = "\"Master\"mu? Bisakah kamu masih memanggilnya seperti itu seperti sekarang ini?",
  ui_story_5089_50891101_61_dialog_content = "Karena tampaknya ajarannya tidak lagi tercermin dalam ilmu pedang Anda.",
  ui_story_5089_50891101_62_dialog_content = "...",
  ui_story_5089_50891101_63_dialog_content = "Jika kamu begitu terobsesi dengan menyelesaikan skor, maka mari kita selesaikan beberapa sekarang juga.",
  ui_story_5089_50891101_64_dialog_content = "Kamu memiliki orang tua yang mencintaimu, tetangga yang peduli padamu, dan guru yang membimbingmu.",
  ui_story_5089_50891101_65_dialog_content = "Jika bukan karena upaya Kapten Yuebai dan Menteri Armilla di atas Shadowind, kami kemungkinan besar sekarang berada di dasar laut.",
  ui_story_5089_50891101_66_dialog_content = "Dan jangan lupa bahwa PlayerName tidak pernah sekali pun meninggalkan Anda, terutama sekarang.",
  ui_story_5089_50891101_67_dialog_content = "Namun, kamu tidak pernah benar-benar memperhatikan pertimbangan yang diberikan kepadamu. Sungguh pemborosan kebaikan yang memalukan.",
  ui_story_5089_50891101_68_dialog_content = "... Wawasan Anda tentang karakter saya sepenuhnya benar, Yang Mulia.",
  ui_story_5089_50891101_69_dialog_content = "Hutang saya kepada kalian semua lebih dari yang bisa saya bayar. Saya tidak mungkin gagal memahami itu.",
  ui_story_5089_50891101_70_dialog_content = "Tapi bagaimana denganmu, Lady Dantang?",
  ui_story_5089_50891101_71_dialog_content = "Saya menganggap diri saya telah setia melayani di sisi Anda, tidak pernah meninggalkan Anda meski sejenak.",
  ui_story_5089_50891101_72_dialog_content = "Dan namun kau membuangku tanpa sepatah kata lagi, seolah-olah aku ini sepasang sepatu yang sudah usang!",
  ui_story_5089_50891101_73_dialog_content = "Apakah kamu marah padaku, Jiu?",
  ui_story_5089_50891101_74_dialog_content = "Dan di sini saya pikir Anda telah menjadi tidak lebih dari boneka tanpa jiwa.",
  ui_story_5089_50891101_75_dialog_content = "Maaf. Apakah saya telah mengecewakan Anda lagi, Yang Mulia?",
  ui_story_5089_50891101_76_dialog_content = "Ya, sebenarnya.",
  ui_story_5089_50891101_77_dialog_content = "Karena kami tahu Anda masih mampu merasakan emosi, itu berarti Anda juga bisa memahami kepedulian kami terhadap Anda.",
  ui_story_5089_50891101_78_dialog_content = "Jadi mengapa kau tetap bersikeras menekan pedangmu atas hal-hal seperti rasa terima kasih dan balas dendam?!",
  ui_story_5089_50891101_79_dialog_content = "Yang mulia...?",
  ui_story_5089_50891101_80_dialog_content = "Dantang, di belakangmu—!",
  ui_story_5089_50891101_81_dialog_content = "Begonia yang Bersinar!",
  ui_story_5089_50891101_82_dialog_content = "<color=#e8d9bb>Tanpa menoleh ke belakang, lautan begonia meletus di belakang Dantang dan meluap ke segala arah.</color>",
  ui_story_5089_50891101_83_dialog_content = "Ada satu hal terakhir yang perlu kukatakan kepada kamu.",
  ui_story_5089_50891101_84_dialog_content = "Aku tidak meninggalkanmu karena kesetiaanmu pada orang lain, tapi karena kamu tidak mengerti.",
  ui_story_5089_50891101_85_dialog_content = "<color=#e8d9bb>Dalam sekejap, begonia mekar sejauh mata memandang.</color>",
  ui_story_5089_50891101_86_dialog_content = "<color=#e8d9bb>Setelah menginjakkan kaki di lautan bunga ini, musuh mereka menurunkan senjata dan berdiri dalam keadaan trance.</color>",
  ui_story_5089_50891101_87_dialog_content = "<color=#e8d9bb>Di tengah mereka, penampilan Dantang yang penuh dengan darah ini menarik perhatian secara tak terduga.</color>",
  ui_story_5089_50891101_88_dialog_content = "\"Alam semesta mengikuti lima puluh hukum, tetapi Surga menyimpan empat puluh sembilan rahasia, meninggalkan satu jalan bagi umat manusia.\"",
  ui_story_5089_50891101_89_dialog_content = "Bahkan surga yang tak menentu pun meninggalkan jalan untuk kita, jadi mengapa kau bersikeras menahan diri seperti ini?",
  ui_story_5089_50891101_90_dialog_content = "Aku akan mengatakan lagi kata-kata yang tidak bisa kuselesaikan di penginapan tadi.",
  ui_story_5089_50891101_91_dialog_content = "Harus dikurung jika kamu ingin mengagumi bulu burung yang indah.",
  ui_story_5089_50891101_92_dialog_content = "Jika Anda ingin mengagumi bulu harimau yang berwarna-warni, itu harus diburu dan diubah menjadi mantel.",
  ui_story_5089_50891101_93_dialog_content = "Tapi ini bukan kekaguman yang sebenarnya.",
  ui_story_5089_50891101_94_dialog_content = "Semua makhluk hidup terlahir bebas. Biarkan mereka terbang melintasi langit dan mengaum dari puncak gunung jika kamu benar-benar ingin mengaguminya.",
  ui_story_5089_50891101_95_dialog_content = "Saya memaksa Anda untuk mencari kebenaran karena saya tidak ingin menjadi belenggu yang mengikat Anda selamanya.",
  ui_story_5089_50891101_96_dialog_content = "Aku tidak menginginkanmu melindungi dan mematuhi setiap keinginanku lagi. Aku tidak ingin kamu menghabiskan sisa hidupmu sebagai pedang yang tersembunyi di bayangan.",
  ui_story_5089_50891101_97_dialog_content = "Aku ingin kamu mengangkat kepalamu tinggi-tinggi, dan hidup dengan bebas di bawah sinar matahari.",
  ui_story_5089_50891101_98_dialog_content = "Saya ingin nama Anda berdiri di samping saya dalam catatan sejarah, bukan sebagai guardian yang diam tetapi sebagai jenderal yang bangga dan dicintai.",
  ui_story_5089_50891101_99_dialog_content = "Saya ingin kamu mengikuti saya atas keinginanmu sendiri.",
  ui_story_5089_50891101_100_dialog_content = "Aku mau—",
  ui_story_5089_50891101_101_dialog_content = "Untuk menjadi penguasa sejati bagi Anda!",
  ui_story_5089_50891101_102_dialog_content = "Putri Dantang...",
  ui_story_5089_50891101_103_dialog_content = "Kamu bukan lagi pelindungku. Aku tidak memiliki hak untuk memberimu perintah sekarang.",
  ui_story_5089_50891101_104_dialog_content = "Tapi sekarang ketika kamu tidak lagi terikat oleh tugas, rasa terima kasih, atau dendam, jika kamu masih bersedia meminjamkan kekuatanmu padaku...",
  ui_story_5089_50891101_105_dialog_content = "Kalau begitu, bangunlah! Merangkak jika harus, tapi lakukan sekarang—",
  ui_story_5089_50891101_106_dialog_content = "Jiu!",
  ui_story_5089_50891101_107_dialog_content = "Bangun dan berdiri di sisiku!",
  ui_story_5089_50891101_108_dialog_content = "...Pernahkah saya katakan betapa keras kepalanya Anda, Yang Mulia?",
  ui_story_5089_50891101_109_dialog_content = "Bahkan tidak pernah sekali pun.",
  ui_story_5089_50891101_110_dialog_content = "Jadi, kemarilah dan katakan padaku.",
  ui_story_5089_50891101_111_dialog_content = "...",
  ui_story_5089_50891101_112_dialog_content = "Baiklah.",
  ui_story_5089_50891101_113_dialog_content = "<color=#e8d9bb>Beberapa saat kemudian.</color>",
  ui_story_5089_50891101_114_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5089_50891101_115_dialog_content = "<color=#e8d9bb>Pintu gerbang istana yang baru diperbaiki runtuh untuk kedua kalinya.</color>",
  ui_story_5089_50891101_116_dialog_content = "Tahanan itu kabur! Kejar dia!",
  ui_story_5089_50891101_117_dialog_content = "Saya kembali, Sister Xu—Ah! A-Apa yang sebenarnya terjadi di sini?!",
  ui_story_5089_50891101_118_dialog_content = "Oh, tidak ada apa-apa, tamu terbaru kita baru saja memutuskan untuk pergi, hanya itu saja.",
  ui_story_5089_50891101_119_dialog_content = "A-Angin yang kurasakan tadi... Apakah itu dia?!",
  ui_story_5089_50891101_120_dialog_content = "Itu benar. Pertarungan terakhirku membuatku sedikit lelah, jadi saya memintanya untuk membersihkan jalan keluar dari penjara untuk kami.",
  ui_story_5089_50891101_121_dialog_content = "Sejujurnya... Hei, tunggu sebentar!",
  ui_story_5089_50891101_122_dialog_content = "Apakah gadis itu benar-benar pergi tanpa senjata?",
  ui_story_5089_50891101_123_dialog_content = "Tentu saja. Dengan kemampuannya, dia bisa dengan mudah membelah istana ini menjadi dua.",
  ui_story_5089_50891101_124_dialog_content = "Aku juga tidak berani memberikan pedang ke tangannya sekarang ini.",
  ui_story_5089_50891101_125_dialog_content = "Jadi dia berencana menghadapi seluruh tentara raja tanpa senjata sama sekali?! Apakah kamu tidak khawatir dengan keselamatannya?!",
  ui_story_5089_50891101_126_dialog_content = "Apa yang perlu dikhawatirkan?",
  ui_story_5089_50891101_127_dialog_content = "Saya tahu sebelumnya keadaannya yang muram tidak begitu menarik untuk dilihat, tapi sekarang—",
  ui_story_5089_50891101_128_dialog_content = "Tidak ada yang bisa menghentikannya kecuali dia sendiri mengizinkannya.",
  ui_story_5089_50891101_129_dialog_content = "Ada dia! Lingkari buronan sebelum dia mencoba melarikan diri!",
  ui_story_5089_50891101_130_dialog_content = "Lihat, dia tidak bersenjata! Tangkap dia!",
  ui_story_5089_50891101_131_dialog_content = "Betapa naifnya kamu menganggap saya tidak bersenjata.",
  ui_story_5089_50891101_132_dialog_content = "Mungkin aku tidak memegang pedang, tetapi apa pun bisa menjadi senjata bagi seorang pendekar sejati.",
  ui_story_5089_50891101_133_dialog_content = "<color=#e8d9bb>Dengan putaran, dia memudar ke dalam kegelapan malam. Tiba-tiba—</color>",
  ui_story_5089_50891101_134_dialog_content = "<color=#e8d9bb>Kelopak bunga berpencar.</color>",
  ui_story_5089_50891101_135_dialog_content = "Apa... Apa ini...?",
  ui_story_5089_50891101_136_dialog_content = "<color=#e8d9bb>Daun-daun berkumpul.</color>",
  ui_story_5089_50891101_137_dialog_content = "Hei, apa masalahmu? Kenapa kamu berbaring di tanah seperti itu?! Bangun dan—Uwaaaa!",
  ui_story_5089_50891101_138_dialog_content = "<color=#e8d9bb>Sapu bambu.</color>",
  ui_story_5089_50891101_139_dialog_content = "Lari! Lari demi hidupmu! Aaaahhhh—",
  ui_story_5089_50891101_140_dialog_content = "<color=#e8d9bb>Shadows berkedip-kedip.</color>",
  ui_story_5089_50891101_141_dialog_content = "Ada kamu! Ambil ini!",
  ui_story_5089_50891101_142_dialog_content = "S-Sebuah jubah? Tapi dari mana dia... Urgh...",
  ui_story_5089_50891101_143_dialog_content = "<color=#e8d9bb>Dalam sekejap, Jiu membabat habis banyak prajurit dalam jalur berdarah.</color>",
  ui_story_5089_50891101_144_dialog_content = "Iblis... Dia pasti jenis iblis tertentu!",
  ui_story_5089_50891101_145_dialog_content = "Tidak. Saya jelas adalah orang.",
  ui_story_5089_50891101_146_dialog_content = "Seseorang yang jauh berbeda dari iblis atau roh jahat.",
  ui_story_5089_50891101_147_dialog_content = "Butuh banyak waktu dan usaha bagi saya untuk menyadari ini, jadi bisakah Anda tolong minggir?",
  ui_story_5089_50891101_148_dialog_content = "Saya harus berada di tempat lain sekarang.",
  ui_story_5089_50891101_149_dialog_content = "... Dapatkan dia.",
  ui_story_5089_50891101_150_dialog_content = "Lakukan dengan cara Anda, kalau begitu.",
  ui_story_5089_50891101_151_dialog_content = "<color=#e8d9bb>Jiu membungkuk dan mengambil tombak seorang prajurit yang jatuh. Dengan gerakan cepat, dia mematahkan mata tombak dan mengayunkannya seperti pedang.</color>",
  ui_story_5089_50891101_152_dialog_content = "Pindah.",
  ui_story_5089_50891101_153_dialog_content = "Tempatku—",
  ui_story_5089_50891101_154_dialog_content = "Berada di sisi tuanku!",
  ui_story_5089_50891201_1_dialog_content = "Apa kau sudah menemukan Zhui Hu, PlayerName?",
  ui_story_5089_50891201_2_dialog_content = "Ya! Dia tepat di depan sana!",
  ui_story_5089_50891201_3_dialog_content = "Hmph.",
  ui_story_5089_50891201_4_dialog_content = "Semua orang itu, dan namun mereka masih tidak berdaya untuk menghentikanmu.",
  ui_story_5089_50891201_5_dialog_content = "Sepertinya mereka memang tidak sebanding dengan binatang jam mekanik setelah semua.",
  ui_story_5089_50891201_6_dialog_content = "Jika saya tidak salah ingat, bukankah kita telah menghancurkan Stinger berharga milikmu sepenuhnya waktu itu?",
  ui_story_5089_50891201_7_dialog_content = "Itu benar, dan bala bantuan kita akan tiba setiap detik sekarang. Jika aku kamu, aku akan menyerah sebelum terlambat.",
  ui_story_5089_50891201_8_dialog_content = "Bala bantuan? Sungguh sangat menakutkan.",
  ui_story_5089_50891201_9_dialog_content = "Tidak peduli berapa banyak bala bantuan yang kalian panggil, kalian semua masih fana seperti orang lain. Apakah kalian yakin ingin mereka berada di sini ketika gunung ini runtuh?",
  ui_story_5089_50891201_10_dialog_content = "Alih-alih membuang waktu dengan tampilan keberanian yang sia-sia ini, kamu harus mulai mengevakuasi setiap orang segera.",
  ui_story_5089_50891201_11_dialog_content = "Menurut perkiraan saya, begitu gunung ini runtuh, semua lahan pertanian di seluruh area ini akan hancur total.",
  ui_story_5089_50891201_12_dialog_content = "Sekarang saya mengerti kenapa saya diberi tugas dengan misi yang aneh seperti ini.",
  ui_story_5089_50891201_13_dialog_content = "Ini pasti salah satu daerah penghasil biji-bijian terpenting di Kerajaan Ye. Sepertinya panen tahun ini akan sedikit kurang.",
  ui_story_5089_50891201_14_dialog_content = "Rumor mengatakan bahwa Kerajaan Ji juga ikut campur dalam pasokan makanan Kerajaan Ye. Jika ada yang salah, kelaparan yang luas bisa saja di depan mata.",
  ui_story_5089_50891201_15_dialog_content = "Bukankah kamu juga dari Kerajaan Ye? Kenapa kamu melakukan hal seperti itu?!",
  ui_story_5089_50891201_16_dialog_content = "Saya pikir saya sudah menjelaskan dengan sangat jelas sebelumnya: siapa saja yang bersedia mendukung karya saya pantas disebut sebagai master saya.",
  ui_story_5089_50891201_17_dialog_content = "Jangan biarkan kata-katanya mengalihkan perhatianmu, PlayerName.",
  ui_story_5089_50891201_18_dialog_content = "Dia hanya mengulur waktu untuk... Tunggu! Mana Stinger-mu, Zhui Hu?!",
  ui_story_5089_50891201_19_dialog_content = "Hehehe, senang akhirnya kamu menyadarinya, tapi ini sudah terlambat sekali.",
  ui_story_5089_50891201_20_dialog_content = "Lihat cahaya itu di kejauhan?",
  ui_story_5089_50891201_21_dialog_content = "Serangan Stinger-ku sekarang sudah sepenuhnya terisi, dan dengan kekuatan Api Zhuyin, gunung ini segera akan menjadi tumpukan puing saja!",
  ui_story_5089_50891201_22_dialog_content = "Cobalah untuk menikmati pertunjukan, bukan?",
  ui_story_5089_50891201_23_dialog_content = "Apakah kamu sudah gila?! Jika \"itu\" menghancurkan gunung, kamu akan mati bersama kami semua!",
  ui_story_5089_50891201_24_dialog_content = "Yakinlah, aku sangat mampu untuk tetap hidup.",
  ui_story_5089_50891201_25_dialog_content = "Lebih penting lagi, karena ini adalah serangan skala penuh pertama dari Stinger saya, sangatlah wajar jika saya mengamati efeknya secara langsung.",
  ui_story_5089_50891201_26_dialog_content = "Bersyukurlah, kalian berdua. Tidak semua orang mendapatkan kesempatan untuk menyaksikan pemandangan yang begitu menakjubkan.",
  ui_story_5089_50891201_27_dialog_content = "... Abaikan dia untuk sekarang, PlayerName! Kita harus menghentikan Stinger!",
  ui_story_5089_50891201_28_dialog_content = "Tidak ada yang bisa menghentikannya sekarang.",
  ui_story_5089_50891201_29_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5089_50891201_30_dialog_content = "<color=#e8d9bb>Sinar cahaya yang menyilaukan merobek gunung kolosal, dan batu-batu tak terhitung jumlahnya dari semua ukuran turun hujan dari langit.</color>",
  ui_story_5089_50891201_31_dialog_content = "Prajurit! Antar Master Hou—maksudku, antar raja ke tempat yang aman! Setelah dia terhindar dari bahaya, cari korban selamat di reruntuhan dan evakuasi mereka!",
  ui_story_5089_50891201_32_dialog_content = "Seorang putri tidak seharusnya meninggalkan tamu-tamunya begitu saja, kamu tahu.",
  ui_story_5089_50891201_33_dialog_content = "<color=#e8d9bb>Binatang mekanik muncul dari puing dan meluncur langsung ke Dantang!</color>",
  ui_story_5089_50891201_34_dialog_content = "Awas—!",
  ui_story_5089_50891201_35_dialog_content = "Maaf, tapi saya tidak bisa membiarkan Anda lewat. Itu terlalu berbahaya di depan.",
  ui_story_5089_50891201_36_dialog_content = "Argh, kita sudah berdebat tentang ini selama berjam-jam, pria baik! Kenapa kamu tidak percaya padaku?",
  ui_story_5089_50891201_37_dialog_content = "Ramalan saya dengan jelas menunjukkan bahwa peristiwa bencana akan segera terjadi di suatu tempat dalam arah ini.",
  ui_story_5089_50891201_38_dialog_content = "Kita hanya bisa meredam gelombang kekacauan dan mencegah bencana yang segera terjadi dengan cepat mengantarkan pedang ini kepada pemilik yang sah.",
  ui_story_5089_50891201_39_dialog_content = "Saya yakin prajurit kita bisa menangani bencana yang disebut-sebut ini dengan baik. Bagaimanapun juga, kamu masih tidak bisa lewat.",
  ui_story_5089_50891201_40_dialog_content = "Saya mohon, Tuan yang baik, biarkan saya—",
  ui_story_5089_50891201_41_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5089_50891201_42_dialog_content = "Gunung itu...! Tapi bagaimana ini bisa terjadi?!",
  ui_story_5089_50891201_43_dialog_content = "Aku sudah memperingatkanmu, bukan?",
  ui_story_5089_50891201_44_dialog_content = "Tidak ada waktu untuk disia-siakan! Saya akan pergi sekarang!",
  ui_story_5089_50891201_45_dialog_content = "Tunggu, Anda—",
  ui_story_5089_50891201_46_dialog_content = "<color=#e8d9bb>Tiba-tiba, angin gelap dan mengganggu seolah-olah lewat.</color>",
  ui_story_5089_50891201_47_dialog_content = "Hmm? Apakah seseorang baru saja lewat di sini?",
  ui_story_5089_50891201_48_dialog_content = "Begonia yang Bersinar!",
  ui_story_5089_50891201_49_dialog_content = "Argh!",
  ui_story_5089_50891201_50_dialog_content = "Sepertinya kamu telah menjadi lebih kuat sejak pertemuan terakhir kita di laut.",
  ui_story_5089_50891201_51_dialog_content = "Tidak seperti kamu, tidak semua dari kita melekat pada barang milik kita dan menolak untuk melanjutkan.",
  ui_story_5089_50891201_52_dialog_content = "Heh, kata-kata yang tajam.",
  ui_story_5089_50891201_53_dialog_content = "Keluar, kalian semua!",
  ui_story_5089_50891201_54_dialog_content = "Saya penasaran untuk melihat apakah Anda bisa bertahan melawan \"barang-barang\" milikku atau tidak!",
  ui_story_5089_50891201_55_dialog_content = "!",
  ui_story_5089_50891201_56_dialog_content = "(Dantang sudah mencapai batasnya. Dia tidak akan bisa terus berjalan dengan kecepatan ini.)",
  ui_story_5089_50891201_57_dialog_content = "(Pegunungan itu belum runtuh, tapi bisa terjadi kapan saja sekarang... Apa yang harus kita lakukan?)",
  ui_story_5089_50891201_58_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5089_50891201_59_dialog_content = "<color=#e8d9bb>Sebuah petir cepat memotong melalui malam yang tebal.</color>",
  ui_story_5089_50891201_60_dialog_content = "Jiu!",
  ui_story_5089_50891201_61_dialog_content = "Kamu terlalu lambat!",
  ui_story_5089_50891201_62_dialog_content = "Harap bersikap masuk akal, Yang Mulia. Saya datang ke sini secepat yang saya bisa.",
  ui_story_5089_50891201_63_dialog_content = "Tapi meski begitu, aku masih berutang permintaan maaf padamu.",
  ui_story_5089_50891201_64_dialog_content = "Maafkan saya karena sangat terlambat.",
  ui_story_5089_50891201_65_dialog_content = "Permohonan maaf diterima.",
  ui_story_5089_50891201_66_dialog_content = "Hmph, gangguan lainnya lagi.",
  ui_story_5089_50891201_67_dialog_content = "Tidak masalah. Saya ragu bahkan ketigamu bisa bertahan dari serangan seluruh bengkel penuh dengan binatang mekanik!",
  ui_story_5089_50891201_68_dialog_content = "Roooooarrr!!!",
  ui_story_5089_50891201_69_dialog_content = "Aku bisa mengurus ini sendiri.",
  ui_story_5089_50891201_70_dialog_content = "Jika kamu ingin mendekati Tuan Putri Dantang dan PlayerName, kamu harus mengalahkan aku dulu!",
  ui_story_5089_50891201_71_dialog_content = "(Pertempuran yang terjadi di depan kami hanya bisa digambarkan sebagai \"mengagumkan.\")",
  ui_story_5089_50891201_72_dialog_content = "(Meskipun menghadapi pasukan binatang mekanik dan batu yang terus menerus jatuh, Jiu tidak pernah bergerak sedikit pun.)",
  ui_story_5089_50891201_73_dialog_content = "(Senjata, cabang, daun, batu, dan bahkan puing-puing binatang jam kerja yang jatuh...)",
  ui_story_5089_50891201_74_dialog_content = "(Setiap objek dalam pandangan Jiu berpotensi menjadi senjata yang kuat. Dia tak terhentikan selama dia memiliki sesuatu di tangannya.)",
  ui_story_5089_50891201_75_dialog_content = "Secepat pemanah legendaris yang menembak jatuh Sembilan Matahari, dan semegah kaisar di atas naga mereka yang menjulang tinggi.",
  ui_story_5089_50891201_76_dialog_content = "Turun ke medan perang seperti badai yang berkumpul, dia memisahkan lautan prajurit seperti kilat yang cemerlang.",
  ui_story_5089_50891201_77_dialog_content = "Apakah akhirnya kamu menemukan pedang sejatimu, Jiu?",
  ui_story_5089_50891201_78_dialog_content = "Kriek—",
  ui_story_5089_50891201_79_dialog_content = "Tidak... Ini tidak mungkin! Bagaimana seorang manusia biasa bisa mengendalikan kekuatan sebesar ini?!",
  ui_story_5089_50891201_80_dialog_content = "Aku belum selesai-!",
  ui_story_5089_50891201_81_dialog_content = "<color=#e8d9bb>Namun, Jiu tiba-tiba muncul di belakangnya sebelum dia bisa memanggil lebih banyak binatang jam mekanik.</color>",
  ui_story_5089_50891201_82_dialog_content = "Jangan bergerak.",
  ui_story_5089_50891201_83_dialog_content = "!",
  ui_story_5089_50891201_84_dialog_content = "Hmph, kamu pikir ini sudah berakhir hanya karena kamu telah menangkap saya?",
  ui_story_5089_50891201_85_dialog_content = "Selama Para Penunggang Takdir berhasil mengambil sengatku yang sangat kuat, itu akan terus menimbulkan kekacauan di medan perang!",
  ui_story_5089_50891201_86_dialog_content = "Dan selain itu, bahkan dengan kekuatan supernaturalmu, kau tidak akan pernah bisa mencegah gunung ini dari runtuh!",
  ui_story_5089_50891201_87_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5089_50891201_88_dialog_content = "<color=#e8d9bb>Dengan tekanan yang sangat besar, lapisan batu di bawah gunung mulai mengeluarkan suara yang menakutkan. Tiba-tiba, batu besar mulai terlepas dan jatuh ke tanah.</color>",
  ui_story_5089_50891201_89_dialog_content = "Dantang! Jiu! Di sini tidak aman! Kita harus pergi sekarang juga!",
  ui_story_5089_50891201_90_dialog_content = "Sepertinya itu satu-satunya pilihan kita. Sampai sekarang, pengawal kerajaan seharusnya telah mengevakuasi warga sipil.",
  ui_story_5089_50891201_91_dialog_content = "Kita akan membahas hal-hal setelah kita sampai di tempat yang aman.",
  ui_story_5089_50891201_92_dialog_content = "... Jiu? Kenapa kau tidak mundur?",
  ui_story_5089_50891201_93_dialog_content = "Aku bisa menghentikannya.",
  ui_story_5089_50891201_94_dialog_content = "Apa?",
  ui_story_5089_50891201_95_dialog_content = "Guru saya pernah mengatakan bahwa teknik Thundering Edge mampu membelah gunung dan memisahkan lautan.",
  ui_story_5089_50891201_96_dialog_content = "Tapi saya pikir Anda mengatakan bahwa guru Anda tidak pernah mengajarkan Anda gerakan itu?",
  ui_story_5089_50891201_97_dialog_content = "Dia mengklaim bahwa dia tidak memiliki cara untuk mengajarkannya kepada saya, ya. Pada awalnya, saya pikir dia hanya mencari alasan.",
  ui_story_5089_50891201_98_dialog_content = "Tapi sekarang saya mulai melihat bahwa dia benar sejak awal.",
  ui_story_5089_50891201_99_dialog_content = "Tepi Menggelegar tidak dapat diajarkan karena sama sekali bukan teknik pedang yang nyata.",
  ui_story_5089_50891201_100_dialog_content = "Sebaliknya, itu adalah hati dari pedang seseorang.",
  ui_story_5089_50891201_101_dialog_content = "Meski begitu, kau tidak memiliki pedang sekarang—",
  ui_story_5089_50891201_102_dialog_content = "Teman-teman! Aku benar-benar butuh bantuan sekarang!",
  ui_story_5089_50891201_103_dialog_content = "Astaga, oh Tuhan, bagaimana saya bisa menghindari semua batu ini—",
  ui_story_5089_50891201_104_dialog_content = "Tianxian! Ini bukan saatnya bermain-main!",
  ui_story_5089_50891201_105_dialog_content = "Saya sedang serius melakukan ramalan sekarang—Ah! Tidak bisa ke arah itu, saya kira.",
  ui_story_5089_50891201_106_dialog_content = "Nyonya Jiu, ini pedangmu! Tangkap!",
  ui_story_5089_50891201_107_dialog_content = "Tidak di jam tangan saya!",
  ui_story_5089_50891201_108_dialog_content = "!",
  ui_story_5089_50891201_109_dialog_content = "<color=#e8d9bb>Ketika pedang Jiu meluncur di udara, beberapa kepiting api langsung melompat ke arah Dantang.</color>",
  ui_story_5089_50891201_110_dialog_content = "<color=#e8d9bb>Jiu tersandung dan pedangnya jatuh ke cakar kepiting api. Pada saat berikutnya, ia merayap menuju area reruntuhan yang sangat padat.</color>",
  ui_story_5089_50891201_111_dialog_content = "<color=#e8d9bb>Hampir seketika, kepiting api itu hancur di bawah batu yang jatuh, menjebak pedang Jiu bersamanya.</color>",
  ui_story_5089_50891201_112_dialog_content = "... Aku akan pergi mendapatkannya!",
  ui_story_5089_50891201_113_dialog_content = "PlayerName! / PlayerName!",
  ui_story_5089_50891201_114_dialog_content = "Force Boost!",
  ui_story_5089_50891201_115_dialog_content = "(Selama aku bisa dengan akurat memprediksi di mana batu-batu itu akan jatuh, aku bisa melakukannya!)",
  ui_story_5089_50891201_116_dialog_content = "Siap!",
  ui_story_5089_50891201_117_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5089_50891201_118_dialog_content = "<color=#e8d9bb>Bumi bergetar keras ketika gunung yang sudah goyah sejak lama akhirnya runtuh sepenuhnya!</color>",
  ui_story_5089_50891201_119_dialog_content = "(Tidak baik, aku tidak bisa menghindari begitu banyak batu sekaligus—!)",
  ui_story_5089_50891201_120_dialog_content = "<color=#e8d9bb>Sekejap cahaya emas.</color>",
  ui_story_5089_50891201_121_dialog_content = "Batu-batunya... Semuanya terpental?",
  ui_story_5089_50891201_122_dialog_content = "<color=#e8d9bb>Sebuah penghalang emas yang akrab, berbentuk teratai menggantung di langit, menghalangi hujan batu yang jatuh.</color>",
  ui_story_5089_50891201_123_dialog_content = "Hah? Ada sesuatu yang terasa hangat di sakuku... Tunggu... Bukankah ini daun yang diberikan Chen'ni kepadaku?",
  ui_story_5089_50891201_124_dialog_content = "<color=#e8d9bb>Ini bukan daun biasa...</color>",
  ui_story_5089_50891201_125_dialog_content = "<color=#e8d9bb>Tapi sebuah sisik naga yang berkilauan.</color>",
  ui_story_5089_50891201_126_dialog_content = "... Terima kasih, Chen'ni.",
  ui_story_5089_50891201_127_dialog_content = "Aku pasti akan membeli banyak camilan untukmu saat kita bertemu lagi nanti!",
  ui_story_5089_50891201_128_dialog_content = "Di depan sana, Jiu—!",
  ui_story_5089_50891201_129_dialog_content = "Terima kasih.",
  ui_story_5089_50891201_130_dialog_content = "<color=#e8d9bb>Gunung itu terus menuruni kemurkaannya, seolah-olah mengancam untuk menghancurkan seluruh planet di bawah bobotnya yang tak terukur.</color>",
  ui_story_5089_50891201_131_dialog_content = "<color=#e8d9bb>Berdiri di tengah-tengah guncangan bumi dan reruntuhan yang jatuh, Jiu menutup matanya dan mengabaikan dunia di sekelilingnya.</color>",
  ui_story_5089_50891201_132_dialog_content = "Guru, sepertinya akhirnya aku mengerti arti dari sebuah pedang.",
  ui_story_5089_50891201_133_dialog_content = "\"Alam semesta mengikuti lima puluh hukum, tetapi Surga menyimpan empat puluh sembilan rahasia, meninggalkan satu jalan bagi umat manusia.\"",
  ui_story_5089_50891201_134_dialog_content = "Bahkan surga yang tak menentu pun meninggalkan jalan untuk kita, jadi mengapa kau bersikeras menahan diri seperti ini?",
  ui_story_5089_50891201_135_dialog_content = "Tidak apa-apa. Jika kamu benar-benar membutuhkan batas waktu, maka...",
  ui_story_5089_50891201_136_dialog_content = "Perintahmu tidak akan berakhir sampai hari di mana kamu bisa mengayunkan pedangmu tanpa melakukannya karena rasa syukur atau balas dendam. Bagaimana menurutmu?",
  ui_story_5089_50891201_137_dialog_content = "Saya punya pertanyaan untuk Anda, Nona Jiu.",
  ui_story_5089_50891201_139_dialog_content = "Maafkan saya, Lady Xuan Ji. Saya terlalu bodoh untuk memahami pertanyaan Anda saat itu.",
  ui_story_5089_50891201_140_dialog_content = "Tapi untungnya, aku memiliki banyak orang hebat di sisiku yang akan membimbingku saat aku tersesat.",
  ui_story_5089_50891201_141_dialog_content = "Jadi sekarang, izinkan saya memberikan jawaban saya kepada Anda.",
  ui_story_5089_50891201_142_dialog_content = "Perbedaan terbesar antara kita dan Eclipsite adalah bahwa insting atau perintah kita tidak sepenuhnya mengendalikan kita.",
  ui_story_5089_50891201_143_dialog_content = "Jika itu masalahnya, kita akan kehilangan makna tanpa mereka.",
  ui_story_5089_50891201_144_dialog_content = "Meskipun kita tersesat, jatuh ke dalam kegelapan, atau memenjarakan diri kita dalam sangkar kebodohan, kita selalu bisa bertemu dengan orang-orang yang penuh kebaikan dan kehangatan tanpa batas.",
  ui_story_5089_50891201_145_dialog_content = "Jiwa-jiwa lembut yang akan membimbing kita keluar dari bayangan yang menindas—",
  ui_story_5089_50891201_146_dialog_content = "Dan masuk ke dalam cahaya hangat matahari!",
  ui_story_5089_50891201_147_dialog_content = "<color=#e8d9bb>Jiu tiba-tiba membuka matanya dan mengayunkan pedangnya dengan kecepatan yang hampir tidak bisa dilihat.</color>",
  ui_story_5089_50891201_148_dialog_content = "<color=#e8d9bb>Gunung itu segera hancur setelahnya saat langit dan bumi beresonansi seirama.</color>",
  ui_story_5089_50891201_149_dialog_content = "<color=#e8d9bb>Sebuah bilah yang mewujudkan keganasan tertinggi, namun membawa keringanan yang ekstrem.</color>",
  ui_story_5089_50891201_150_dialog_content = "Saya tidak lagi menggunakan pedangku untuk rasa terima kasih atau balas dendam.",
  ui_story_5089_50891201_151_dialog_content = "<color=#e8d9bb>Sebaliknya, dia menggunakannya sebagai hadiah untuk banyak teman yang telah menunjukkan kebaikannya padanya.</color>",
  ui_story_5089_50891201_152_dialog_content = "<color=#e8d9bb>Gelombang kejut dari serangan ultimatenya menyapu dari kerikil terkecil hingga gunung tertinggi, menghancurkan semua yang disentuhnya menjadi debu.</color>",
  ui_story_5089_50891201_153_dialog_content = "Luar biasa...",
  ui_story_5089_50891201_154_dialog_content = "<color=#e8d9bb>Melihat ke atas lagi, gunung yang sangat besar yang baru saja runtuh beberapa saat lalu telah berubah menjadi awan debu.</color>",
  ui_story_5089_50891201_155_dialog_content = "<color=#e8d9bb>Pedang es membelah udara, meninggalkan guntur di jejaknya.</color>",
  ui_story_5089_50891201_156_dialog_content = "<color=#e8d9bb>Bergema di puncak gunung yang jauh.</color>",
  ui_story_5089_50891201_157_dialog_content = "Kak Xuan Ji... Serangan barusan tidak akan terjadi lagi, bukan?",
  ui_story_5089_50891201_158_dialog_content = "Kemungkinan besar tidak.",
  ui_story_5089_50891201_159_dialog_content = "Namun, tak pernah kusangka pedangnya memiliki kekuatan yang begitu hebat.",
  ui_story_5089_50891201_160_dialog_content = "Meski dari jarak ini, Stinger sudah terbelah menjadi dua... Hmm?",
  ui_story_5089_50891201_161_dialog_content = "Kakak... Apakah itu Api Zhuyin?!",
  ui_story_5089_50891201_162_dialog_content = "Seperti yang selalu saya katakan, seorang pengrajin harus teliti dalam semua yang mereka lakukan.",
  ui_story_5089_50891201_163_dialog_content = "Meski harus kuakui, ini pertama kalinya aku melihat seseorang membelah api menjadi dua.",
  ui_story_5089_50891201_164_dialog_content = "Ini bukan saatnya bercanda, Sister Xuan Ji!",
  ui_story_5089_50891201_165_dialog_content = "Api Zhuyin adalah artefak paling berharga sekte kami, tapi lihat sekarang! Itu telah dipotong menjadi dua bagian!",
  ui_story_5089_50891201_166_dialog_content = "Iya, dan dua bagian yang sempurna simetris, tidak kurang.",
  ui_story_5089_50891201_167_dialog_content = "Miss Jiu benar-benar telah memberikan kami sebuah kebaikan besar.",
  ui_story_5089_50891201_168_dialog_content = "Apa yang sedang kamu bicarakan?! Bagaimana kita harus menjelaskan ini kepada guild?!",
  ui_story_5089_50891201_169_dialog_content = "Jangan khawatir, aku akan mengurus semuanya.",
  ui_story_5089_50891201_170_dialog_content = "Sekarang pergi dan beri tahu yang lain di bawah. Binatang Mekanik di sini sudah ditangani, jadi minta mereka membantu dengan sisanya.",
  ui_story_5089_50891201_171_dialog_content = "Setelah semua, seharusnya kita sendiri yang bertanggung jawab membersihkan kekacauan dari pengkhianat kita sendiri.",
  ui_story_5089_50891201_172_dialog_content = "Aku mengerti.",
  ui_story_5089_50891201_173_dialog_content = "Nng.",
  ui_story_5089_50891201_174_dialog_content = "Apakah kamu baik-baik saja, Jiu?",
  ui_story_5089_50891201_175_dialog_content = "Aku baik-baik saja, hanya merasa sedikit lelah...",
  ui_story_5089_50891201_176_dialog_content = "Tunggu sebentar... Kamu benar-benar penuh dengan darah! Kamu telah bertarung dalam kondisi seperti ini sepanjang waktu?!",
  ui_story_5089_50891201_177_dialog_content = "Cepat, panggil medik!",
  ui_story_5089_50891201_178_dialog_content = "Aku menghargai kepedulianmu, PlayerName, tapi aku masih ada hal yang harus kulakukan.",
  ui_story_5089_50891201_179_dialog_content = "Apa yang mungkin bisa kamu lakukan setelah semua ini?!",
  ui_story_5089_50891201_180_dialog_content = "Jangan hanya berdiri di sana, Dantang! Katakan sesuatu padanya!",
  ui_story_5089_50891201_181_dialog_content = "Biarkan dia, PlayerName.",
  ui_story_5089_50891201_182_dialog_content = "Saatnya bagi dia untuk menyelesaikan segalanya sekali dan untuk selamanya.",
  ui_story_5089_50891201_183_dialog_content = "Tapi apa yang bisa dia jadi... Oh, aku mengerti sekarang!",
  ui_story_5089_50891201_184_dialog_content = "Kamu benar, sudah saatnya kita selesaikan ini.",
  ui_story_5089_50891201_185_dialog_content = "Jadi, kau datang.",
  ui_story_5089_50891201_186_dialog_content = "Benar.",
  ui_story_5089_50891201_187_dialog_content = "Penjaga, bawakan aku sebuah pedang.",
  ui_story_5089_50891201_188_dialog_content = "Tapi Yang Mulia, Anda masih terluka parah! Anda seharusnya tidak bergerak sekarang!",
  ui_story_5089_50891201_189_dialog_content = "Aku bilang bawakan aku pedang.",
  ui_story_5089_50891201_190_dialog_content = "Setidaknya, aku berhutang sebanyak ini padanya.",
  ui_story_5089_50891201_191_dialog_content = "<color=#e8d9bb>Jiu mengeluarkan topengnya dan memakainya sekali lagi.</color>",
  ui_story_5089_50891201_192_dialog_content = "Mari kita selesaikan ini.",
  ui_story_5089_50891202_1_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_5089_50891202_2_dialog_content = "<color=#e8d9bb>Di sebuah lapangan kosong, dua sosok bertabrakan. Setelah pertukaran singkat, pedang raja palsu terpental dari tangannya dan terlempar ke udara.</color>",
  ui_story_5089_50891202_3_dialog_content = "Batuk... Batuk, batuk...",
  ui_story_5089_50891202_4_dialog_content = "Tolong, Yang Mulia! Cukuplah pertarungan ini!",
  ui_story_5089_50891202_5_dialog_content = "Hasilnya jelas.",
  ui_story_5089_50891202_6_dialog_content = "Anda telah mengalahkan saya.",
  ui_story_5089_50891202_7_dialog_content = "...",
  ui_story_5089_50891202_8_dialog_content = "<color=#e8d9bb>Krak.</color>",
  ui_story_5089_50891202_9_dialog_content = "<color=#e8d9bb>Topeng Jiu dibelah dua oleh serangan raja palsu, dan jatuh ke tanah.</color>",
  ui_story_5089_50891202_10_dialog_content = "Dengan ini, dendam kita sekarang telah diselesaikan.",
  ui_story_5089_50891202_11_dialog_content = "Setuju.",
  ui_story_5089_50891202_12_dialog_content = "Sekarang pergi.",
  ui_story_5089_50891202_13_dialog_content = "<color=#e8d9bb>Jiu menyimpan pedangnya, membungkuk sedikit ke Dantang di kejauhan, lalu berbalik dan pergi.</color>",
  ui_story_5089_50891202_14_dialog_content = "<color=#e8d9bb>Tidak satupun dia menoleh ke belakang.</color>",
  ui_story_5089_50891300_1_dialog_content = "<color=#e8d9bb>Istana Kerajaan Ji</color>",
  ui_story_5089_50891300_2_dialog_content = "Ayah! Ayah! Aku mendengar tunanganku telah mengirimiku hadiah!",
  ui_story_5089_50891300_3_dialog_content = "Memang, anakku.",
  ui_story_5089_50891300_4_dialog_content = "Biar kulihat! Biar kulihat!",
  ui_story_5089_50891300_5_dialog_content = "Di sini, sebuah kekayaan dalam emas.",
  ui_story_5089_50891300_6_dialog_content = "Eh? Tapi bukankah ini hadiah yang pernah saya tawarkan kepadanya sebelum dia pergi?",
  ui_story_5089_50891300_7_dialog_content = "Apakah dia tidak suka emas? Seharusnya aku tahu pahlawan kesayanganku tidak peduli pada perhiasan remeh temeh seperti ini.",
  ui_story_5089_50891300_8_dialog_content = "Mulai sekarang, aku harus lebih memikirkan hadiah-hadiahku!",
  ui_story_5089_50891300_9_dialog_content = "Anak laki-laki itu...",
  ui_story_5089_50891300_10_dialog_content = "Pemuda itu menggunakan hadiah emas dari pangeran mahkota untuk ditukar dengan makanan yang sebelumnya kami beli dari Kerajaan Ye. Niatnya tampaknya cukup jelas.",
  ui_story_5089_50891300_11_dialog_content = "Bagaimana kita harus melanjutkan, Yang Mulia?",
  ui_story_5089_50891300_12_dialog_content = "PlayerName adalah teman dari Kerajaan Ji, seseorang yang kehormatannya dapat saya jamin secara pribadi. Saya juga belum membayar balik bantuan dia menyelamatkan Haojin.",
  ui_story_5089_50891300_13_dialog_content = "Jika dia ingin terlibat dalam urusan ini, saya akan menghormati keputusannya.",
  ui_story_5089_50891300_14_dialog_content = "Namun, saya tidak akan begitu ramah jika Kerajaan mencari konflik dengan kami lagi di masa depan.",
  ui_story_5089_50891300_15_dialog_content = "Baik tuan ku.",
  ui_story_5089_50891300_16_dialog_content = "<color=#e8d9bb>Fwoosh—</color>",
  ui_story_5089_50891300_17_dialog_content = "<color=#e8d9bb>Di dermaga yang ramai, kapal besar lainnya mengangkat layarnya dan berangkat.</color>",
  ui_story_5089_50891300_18_dialog_content = "Jadi, Jiu tidak pernah kembali setelah itu?",
  ui_story_5089_50891300_19_dialog_content = "Ya. Mengingat bahwa saya dengan sukarela memberikan kebebasan padanya, sangatlah wajar jika saya menghormati pilihannya.",
  ui_story_5089_50891300_20_dialog_content = "Meskipun dia tak pernah kembali, aku akan selalu mengingat betapa beruntungnya aku memiliki teman yang begitu dekat.",
  ui_story_5089_50891300_21_dialog_content = "Tapi bagaimana denganmu, PlayerName? Apa yang akan kamu lakukan selanjutnya?",
  ui_story_5089_50891300_22_dialog_content = "Hah? Kita sedang berada di kapal menuju Kerajaan Ji sekarang, bukan?",
  ui_story_5089_50891300_23_dialog_content = "Kamu adalah orang yang mengatakan bahwa Fate Riders adalah musuh bersama kita. Tujuan kita selanjutnya adalah meyakinkan Kerajaan Ji dan Ye untuk mengesampingkan perbedaan mereka untuk sementara waktu.",
  ui_story_5089_50891300_24_dialog_content = "Saya juga perlu mengembalikan semua emas ini kepada putra mahkota. Saya tidak pernah mendapat kesempatan untuk berterima kasih kepada Houfeng... Maksud saya, Raja Ye... Atas bantuannya menutupi selisihnya.",
  ui_story_5089_50891300_25_dialog_content = "Ngomong-ngomong, apakah Anda yakin baik membiarkannya terus menjabat sebagai raja?",
  ui_story_5089_50891300_26_dialog_content = "Sayangnya, kita tidak punya pilihan lain.",
  ui_story_5089_50891300_27_dialog_content = "Paman kandungku mentalnya tidak layak untuk memerintah, dan kakak perempuanku masih terlalu muda untuk mengambil alih tanggung jawab takhta. Seperti sekarang ini, Kerajaan Ye tidak bisa menanggung gangguan sekecil apapun.",
  ui_story_5089_50891300_28_dialog_content = "Meskipun Master Houfeng agak arogan, dia benar-benar memiliki kepentingan terbaik untuk Kerajaan Ye di hatinya.",
  ui_story_5089_50891300_29_dialog_content = "Lebih jauh lagi, dengan Ministress Armilla dan Artisan's Guild yang memiliki otoritas lebih besar dari sebelumnya, dia tidak akan bisa bertindak semena-mena untuk sementara waktu.",
  ui_story_5089_50891300_30_dialog_content = "Tapi itu bukan inti dari pertanyaan saya. Saya lebih merujuk pada rencana masa depan Anda.",
  ui_story_5089_50891300_31_dialog_content = "Nah, sekarang setelah saya pergi ke Haojin dan Kota Jingliang, saya ingin melihat lebih banyak tentang Longzhou.",
  ui_story_5089_50891300_32_dialog_content = "Tapi setelah lama tidak berada di Astra, mungkin saya harus kembali dulu? Saya lebih baik tidak membuat Vice dan Carleen khawatir lebih dari yang seharusnya.",
  ui_story_5089_50891300_33_dialog_content = "Bagaimana menurutmu, Dantang?",
  ui_story_5089_50891300_34_dialog_content = "Tentu saja kamu bercanda?",
  ui_story_5089_50891300_35_dialog_content = "Anda bukan burung dalam sangkar atau binatang dalam kandang. Bukan tempat saya untuk menentukan masa depan Anda.",
  ui_story_5089_50891300_36_dialog_content = "Jadi jika aku bukan ini atau itu, lalu apa sebenarnya aku di mata Anda, Dantang?",
  ui_story_5089_50891300_37_dialog_content = "Jika aku harus mengatakannya...",
  ui_story_5089_50891300_38_dialog_content = "<color=#e8d9bb>Di bawah sinar matahari pagi, dia tertawa kecil saat menatap ke atas, matanya yang serius penuh dengan cahaya yang berkilau.</color>",
  ui_story_5089_50891300_39_dialog_content = "Kamu adalah Peng untuk Kun-ku.",
  ui_story_5089_50891300_40_dialog_content = "Sebuah burung besar dan agung yang akhirnya akan terbang melintasi sembilan langit.",
  ui_story_5089_50891300_41_dialog_content = "Itu sedikit terlalu banyak, bukan begitu?",
  ui_story_5089_50891300_42_dialog_content = "Tidak ada sama sekali.",
  ui_story_5089_50891300_43_dialog_content = "Hei, lihat di sana! Ada orang yang mengejar kapal kita!",
  ui_story_5089_50891300_44_dialog_content = "Apakah kamu terlalu lama berada di bawah sinar matahari? Bagaimana mungkin seseorang bisa—Tunggu, kamu benar! Dragon Maiden ada di atas; benar-benar ada seseorang yang berlari di atas air!",
  ui_story_5089_50891300_45_dialog_content = "Apa yang kalian berdua teriakkan—Wah!",
  ui_story_5089_50891300_46_dialog_content = "Apakah itu Jiu?!",
  ui_story_5089_50891300_47_dialog_content = "<color=#e8d9bb>Kapal telah berlayar jauh dari pantai, namun sebuah sosok berjalan di atas air, berlari menuju kapal dengan kecepatan yang luar biasa.</color>",
  ui_story_5089_50891300_48_dialog_content = "<color=#e8d9bb>Ketika dia mendekati kapal, dia membuat lompatan berani dan mendarat dengan anggun di geladak.</color>",
  ui_story_5089_50891300_49_dialog_content = "<color=#e8d9bb>Berdiri di depan kita, segar seperti angin laut, tidak lain adalah Jiu sendiri.</color>",
  ui_story_5089_50891300_50_dialog_content = "Yang Mulia, bukankah Anda ceroboh berangkat ke kerajaan lain tanpa penjaga setia Anda?",
  ui_story_5089_50891300_51_dialog_content = "Jadi, kamu sudah memutuskan?",
  ui_story_5089_50891300_52_dialog_content = "Jika kamu telah memilih untuk terus mengikutiku, ketahuilah bahwa saya tidak akan mentolerir kesalahan yang sama dua kali, Jiu.",
  ui_story_5089_50891300_53_dialog_content = "Pikiranku sudah bulat, Yang Mulia.",
  ui_story_5089_50891300_54_dialog_content = "Demi kehormatanku, aku tidak akan mengecewakanmu.",
  ui_story_5089_50891300_55_dialog_content = "Bagus. Sekarang ayo pergi.",
  ui_story_5089_50891300_56_dialog_content = "Fate Riders masih menjadi ancaman bagi seluruh Kekaisaran Zhao. Setelah urusan kami di Kerajaan Ji selesai, kami akan bepergian ke kerajaan-kerajaan vasal lainnya untuk melanjutkan penyelidikan kami.",
  ui_story_5089_50891300_57_dialog_content = "Tetapi dengan kerajaan dalam bahaya seperti itu, bukankah lebih baik mengirim orang lain ke kerajaan vasal sebagai penggantimu?",
  ui_story_5089_50891300_58_dialog_content = "Melakukan perjalanan melintasi tanah dalam setiap arah yang dapat dibayangkan adalah kesempatan yang diberikan hanya kepada sedikit orang.",
  ui_story_5089_50891300_59_dialog_content = "Saya selalu bercita-cita untuk bepergian seperti ini. Bagaimana mungkin saya membiarkan krisis kecil menghentikan saya untuk mencapai impian seumur hidup saya?",
  ui_story_5089_50891300_60_dialog_content = "Selain itu, burung dan ikan bebas menjelajahi dunia.",
  ui_story_5089_50891300_61_dialog_content = "Jika aku tidak berani menjelajahi setiap sudut dunia, bagaimana aku bisa berharap menemukan teman sehebat mereka untuk terbang bersamaku?",
  ui_story_5089_50891300_62_dialog_content = "Kita masih memiliki perjalanan panjang di depan kita.",
  ui_story_5089_50891300_63_dialog_content = "<color=#e8d9bb>Di sebuah rumah teh di suatu tempat</color>",
  ui_story_5089_50891300_64_dialog_content = "... Dan begitu, Putri Zhuohua dan Utusan Astra berangkat dalam perjalanan mereka masing-masing.",
  ui_story_5089_50891300_65_dialog_content = "Angin yang berubah-ubah dan awan yang bergulung di atas mereka akhirnya mereda, setidaknya untuk saat ini.",
  ui_story_5089_50891300_66_dialog_content = "Untukku, ini adalah kesempatan yang sempurna untuk meminta beberapa koin cadangan sebagai imbalan atas cerita indahku. Lagipula, burung-burung kecilku yang miskin juga harus makan!",
  ui_story_5089_50891300_67_dialog_content = "Apa itu? Kamu pikir saya membuat semua ini? Wah, sungguh salah paham yang besar!",
  ui_story_5089_50891300_68_dialog_content = "Setiap kata dari apa yang baru saja saya katakan adalah benar, dan lautan ini adalah buktinya!",
  ui_story_5089_50891300_69_dialog_content = "Terukir di atas ombak lautan, sebuah kapal penuh dengan begonia yang bersinar berlayar maju.",
  ui_story_5089_50891300_70_dialog_content = "Pada malam Festival Musim Semi, tarian antara ikan dan naga berlangsung, dan kekuatan badai menenangkan laut.",
  ui_story_5089_50891300_71_dialog_content = "Sebuah pedang berguntur menjadi bilah murni es, dan menghantam iblis menjadi debu.",
  ui_story_5089_50891300_72_dialog_content = "Burung yang dikurung berhasil bebas, mengguncang langit dengan sayapnya saat menemukan kebahagiaan dalam kebesaran dunia.",
  ui_story_5089_50891300_73_dialog_content = "Dengan demikian, Kisah Begonia yang Mengambang berakhir.",
  ui_story_5089_50891300_74_dialog_content = "Tentu saja, perjalanan sang pahlawan masih jauh dari selesai. Jika kamu ingin mendengar sisanya—",
  ui_story_5089_50891300_75_dialog_content = "<color=#e8d9bb>Klak!</color>",
  ui_story_5089_50891300_76_dialog_content = "<color=#e8d9bb>Dengan sekali ketukan palu kayu, buku yang telah dibalik hingga akhir perlahan ditutup, cahaya lilin memudar, dan tirai pun jatuh.</color>",
  ui_story_5089_50891300_77_dialog_content = "Apa selanjutnya... Yah, mungkin kita berdiri di ujung laut yang berlawanan, kita akan bertemu lagi selama takdir mengizinkannya.",
  ui_story_5089_50891400_1_dialog_content = "Sudahkah Anda membuat keputusan?",
  ui_story_5089_50891400_2_dialog_content = "Bergerak maju berarti mengucapkan selamat tinggal kepada semua orang yang kamu kenal sekarang.",
  ui_story_5089_50891400_3_dialog_content = "Semua koneksi yang telah Anda bangun dengan keras akan memudar.",
  ui_story_5089_50891400_4_dialog_content = "Tapi meski begitu, kau masih akan pergi ke ujung dunia untuknya, bukan?",
  ui_story_5089_50891400_5_option_content = "Ya.",
  ui_story_5089_50891400_6_option_content = "Ya, aku sudah memutuskan.",
  ui_story_5089_50891400_7_dialog_content = "...",
  ui_story_5089_50891400_8_dialog_content = "Perjalanan Anda di Longzhou tampaknya telah membuat Anda lebih tegas.",
  ui_story_5089_50891400_9_dialog_content = "Kalau begitu, mari kita ucapkan selamat tinggal.",
  ui_story_5089_50891400_10_dialog_content = "Di akhir dari akhir, bersama semua teman-temanku...",
  ui_story_5089_50891400_11_dialog_content = "Satu perjalanan terakhir mengelilingi Astra, benar?",
  ui_story_5089_50891400_12_dialog_content = "Sama seperti di awal, kita akan memulai dengan gaya!",
  ui_story_5089_50891400_13_dialog_content = "Kamu datang jauh-jauh hanya untuk mengucapkan selamat tinggal?",
  ui_story_5089_50891400_14_dialog_content = "Oh, aku pandai dalam hal ini, tahu. Tapi, kau akan kembali suatu hari nanti, 'kan?",
  ui_story_5089_50891400_15_option_content = "Aku juga tidak yakin.",
  ui_story_5089_50891400_16_option_content = "Hmm…",
  ui_story_5089_50891400_17_dialog_content = "Mendesah, kemarilah.",
  ui_story_5089_50891400_18_dialog_content = "Di sini. Ketika pria-pria berpelukan seperti ini, mereka tidak perlu mengatakan apa-apa lagi.",
  ui_story_5089_50891400_19_dialog_content = "Aku tahu kamu punya alasanmu, dan aku mendukungmu.",
  ui_story_5089_50891400_20_dialog_content = "Dan... Terima kasih. Kamu selalu sangat membantu kami, dan aku.",
  ui_story_5089_50891400_21_dialog_content = "Jika kalian pernah kembali, ingatlah untuk memberi tahu kami.",
  ui_story_5089_50891400_22_dialog_content = "Dan jika segala sesuatu tidak berjalan sesuai rencana, jangan lupa bahwa kamu selalu memiliki tempat di sini.",
  ui_story_5089_50891400_23_dialog_content = "Terima kasih, aku pasti akan mengingatnya.",
  ui_story_5089_50891400_24_dialog_content = "Argh, di sini aku mulai menangis... Ini salahmu.",
  ui_story_5089_50891400_25_dialog_content = "Sekarang pergilah ucapkan selamat tinggal kepada Eve dan yang lainnya.",
  ui_story_5089_50891400_26_dialog_content = "Selamat tinggal, Sinsa.",
  ui_story_5089_50891400_27_dialog_content = "... Selamat tinggal, PlayerName.",
  ui_story_5089_50891400_28_dialog_content = "Apa? Begitu saja... dan kamu pergi dan tidak akan kembali lagi?!",
  ui_story_5089_50891400_29_dialog_content = "Ah, itu tidak selalu begitu, tapi aku tidak benar-benar yakin kapan aku akan kembali...",
  ui_story_5089_50891400_30_dialog_content = "O-Oh, Eve, jangan menangis. Jika Sinsa melihat ini, aku akan berada dalam masalah besar!",
  ui_story_5089_50891400_31_dialog_content = "Namun…",
  ui_story_5089_50891400_32_dialog_content = "Aku tahu kita akan bertemu lagi suatu hari nanti!",
  ui_story_5089_50891400_33_dialog_content = "Dan ketika akhirnya saya menemukan jalan kembali ke sini...",
  ui_story_5089_50891400_34_dialog_content = "Aku akan memiliki banyak cerita baru untuk dibagikan denganmu, cerita-cerita yang tidak pernah bisa kamu lihat di sini di Astra!",
  ui_story_5089_50891400_35_dialog_content = "Janji?",
  ui_story_5089_50891400_36_dialog_content = "Tentu saja!",
  ui_story_5089_50891400_37_dialog_content = "Janji kelingking?",
  ui_story_5089_50891400_38_dialog_content = "Sangat cocok!",
  ui_story_5089_50891400_39_dialog_content = "Bagus! Ayo, aku akan membawamu ke yang lain sehingga kamu bisa mengucapkan selamat tinggal pada mereka.",
  ui_story_5089_50891400_40_dialog_content = "Kami merindukanmu setiap saat, tahu kan?",
  ui_story_5089_50891400_41_dialog_content = "Oh, dan ingat wanita yang pernah kamu perkenalkan kepada kami sebelumnya? Kamu masih belum melihatnya di sekitar sini!",
  ui_story_5089_50891400_42_dialog_content = "Dan ada juga Nona Attar! Dia...",
  ui_story_5089_50891400_43_dialog_content = "Eve?",
  ui_story_5089_50891400_44_dialog_content = "Maaf. Aku tahu aku berjanji tidak akan menangis lagi.",
  ui_story_5089_50891400_45_dialog_content = "Tapi... Aku tiba-tiba mengingat semua yang telah kita lalui bersama...",
  ui_story_5089_50891400_46_dialog_content = "Aku paham maksudmu. Sudah lama, ya?",
  ui_story_5089_50891400_47_dialog_content = "Sebelum kami sadari, kami telah membuat banyak teman baru. Mereka semua juga telah berkembang dalam banyak cara.",
  ui_story_5089_50891400_48_dialog_content = "Tempat ini akan selalu dekat dan berharga di hati saya.",
  ui_story_5089_50891400_49_dialog_content = "Sama seperti hot pot di Longzhou.",
  ui_story_5089_50891400_50_dialog_content = "Itulah mengapa aku pikir kamu akan baik-baik saja, Eve.",
  ui_story_5089_50891400_51_dialog_content = "Karena kamu masih akan memiliki setiap orang di sisimu.",
  ui_story_5089_50891400_52_dialog_content = "A-Baiklah.",
  ui_story_5089_50891400_54_dialog_content = "Ayo, mari kita ucapkan selamat tinggal.",
  ui_story_5089_50891400_55_dialog_content = "Saya telah diberitahu tentang masalah itu.",
  ui_story_5089_50891400_56_dialog_content = "Karena ini melibatkan Vice, saya tidak akan menghentikanmu.",
  ui_story_5089_50891400_57_dialog_content = "Saya juga telah menyetujui permintaan Vice untuk cuti. Jika kamu membutuhkan sesuatu yang lain, jangan ragu untuk memberitahuku.",
  ui_story_5089_50891400_58_dialog_content = "Tidak apa-apa, ini lebih dari cukup. Terima kasih dan Reinhardt atas semua bantuan kalian!",
  ui_story_5089_50891400_59_dialog_content = "Perjalanan kita akan membawa kita jauh ke dalam wilayah yang belum diketahui.",
  ui_story_5089_50891400_60_dialog_content = "Ini bukan sesuatu yang bisa diselesaikan hanya dengan mencari lebih banyak orang.",
  ui_story_5089_50891400_61_dialog_content = "Aku mengerti, tapi aku masih ingin membantu jika memungkinkan.",
  ui_story_5089_50891400_62_dialog_content = "Pasti akan sedikit sepi tanpa kamu, aku yakin.",
  ui_story_5089_50891400_63_dialog_content = "Aku tahu Barton akan merasakannya saat duduk-duduk di rumah.",
  ui_story_5089_50891400_64_dialog_content = "Mengapa tidak membiarkan Gronru membawanya keluar untuk bermain lebih banyak? Tidak sehat baginya untuk tinggal di rumah saat tidak ada pertempuran yang harus diperjuangkan.",
  ui_story_5089_50891400_65_dialog_content = "Heh, aku hanya bercanda.",
  ui_story_5089_50891400_66_dialog_content = "Komandannya yang lama sekarang mengawasinya dengan ketat, jadi dia akan memiliki banyak hal untuk dilakukan.",
  ui_story_5089_50891400_67_dialog_content = "Commander Hiiro bercanda... Aku tidak percaya aku bisa melihat hari ini.",
  ui_story_5089_50891400_68_dialog_content = "Hmm. Mungkin ini hanya jenis perubahan yang Anda bawa keluar pada orang lain.",
  ui_story_5089_50891400_69_dialog_content = "Kamu telah sangat mempengaruhi Grand Marshal, dan aku bukan pengecualian.",
  ui_story_5089_50891400_70_dialog_content = "...",
  ui_story_5089_50891400_71_dialog_content = "Jaga dirimu.",
  ui_story_5089_50891400_72_dialog_content = "Baiklah!",
  ui_story_5089_50891400_73_dialog_content = "Hai! Disini!",
  ui_story_5089_50891400_74_dialog_content = "Di sini, di sini, PlayerName!",
  ui_story_5089_50891400_75_dialog_content = "Saya di sini untuk mengucapkan selamat tinggal.",
  ui_story_5089_50891400_76_dialog_content = "Apakah Colossus selalu lepas landas dengan cepat ini?",
  ui_story_5089_50891400_77_dialog_content = "Hei—PlayerName!",
  ui_story_5089_50891400_78_dialog_content = "Jaga dirimu dengan baik dalam perjalananmu, kamu dengar? Ingatlah untuk makan tiga kali sehari, dan jangan terlambat untuk satupun!",
  ui_story_5089_50891400_79_dialog_content = "Dan kamu juga harus membawa Vice pulang dengan selamat!",
  ui_story_5089_50891400_80_dialog_content = "Aku akan—Tunggu saja!",
  ui_story_5089_50891400_81_dialog_content = "Aku berjanji akan membawanya kembali dengan selamat!",
  ui_story_5089_50891400_82_dialog_content = "Ah, bocah itu... Berpikir dia bisa terbang bebas bersama salah satu prajurit terbaik Illumina kapan saja dia mau...",
  ui_story_5089_50891400_83_dialog_content = "Bukankah kamu akan mengucapkan selamat tinggal?",
  ui_story_5089_50891400_84_dialog_content = "Tidak, ah.",
  ui_story_5089_50891400_85_dialog_content = "Dia adalah burung bebas. Saya tidak ingin menambah beban yang tidak perlu padanya.",
  ui_story_5089_50891400_86_dialog_content = "Apa yang terjadi selanjutnya adalah keputusan PlayerName. Ini adalah ceritanya, setelah semua.",
  ui_story_5089_50891400_87_dialog_content = "Sebagai temannya, yang bisa saya lakukan hanyalah memberikan harapan terbaik saya saat dia terbang.",
  ui_story_5089_50891400_88_dialog_content = "... Ayo pergi. Kita punya banyak keputusan yang harus kita buat sendiri, 'kan?",
  ui_story_5089_50891400_89_dialog_content = "Sampai jumpa...?",
  ui_story_5089_50891400_90_dialog_content = "...",
  ui_story_5089_50891400_91_dialog_content = "Tapi tidak ada orang di sini sekarang... Lady Victoria, Paloma, Pasolo... Tidak ada satupun dari mereka.",
  ui_story_5089_50891400_92_dialog_content = "Ya, tapi kamu masih di sini, 'kan?",
  ui_story_5089_50891400_93_dialog_content = "Setidaknya, aku bisa melihatmu satu kali lagi sebelum aku pergi.",
  ui_story_5089_50891400_94_dialog_content = "Dan hanya itu yang bisa saya minta.",
  ui_story_5089_50891400_95_dialog_content = "Rasanya seperti ada yang hilang jika kita tidak bisa saling mengucapkan selamat tinggal.",
  ui_story_5089_50891400_96_dialog_content = "?!",
  ui_story_5089_50891400_97_dialog_content = "Meski sayang sekali saya tidak bisa melihat Paloma...",
  ui_story_5089_50891400_98_dialog_content = "Mungkin Victoria akan membantu aku menyampaikan pesan, dia selalu tahu segalanya, 'kan?",
  ui_story_5089_50891400_99_dialog_content = "Dan jika itu tidak berhasil—",
  ui_story_5089_50891400_100_dialog_content = "Hei—! Master Pertapa—!",
  ui_story_5089_50891400_101_dialog_content = "Tolong pastikan Victoria dan yang lainnya mendapatkan pesanku—!",
  ui_story_5089_50891400_102_dialog_content = "... Kau bicara dengan siapa?",
  ui_story_5089_50891400_103_dialog_content = "Heheh... Orang yang mengerti.",
  ui_story_5089_50891400_104_dialog_content = "...",
  ui_story_5089_50891400_105_dialog_content = "Aku…",
  ui_story_5089_50891400_106_dialog_content = "Semoga suatu hari nanti kamu bisa kembali dengan selamat.",
  ui_story_5089_50891400_107_dialog_content = "Tentu saja!",
  ui_story_5089_50891400_108_dialog_content = "Selamat tinggal!",
  ui_story_5089_50891400_109_dialog_content = "Selamat tinggal.",
  ui_story_5089_50891400_110_dialog_content = "... Di sana. Itu seharusnya yang terakhir.",
  ui_story_5089_50891400_111_dialog_content = "Itu semua persediaan untuk perjalananmu dari Guild Umbraton dan... Lovegator.",
  ui_story_5089_50891400_112_dialog_content = "Tak kusangka bisa mendapatkan begitu banyak barang gratis hanya dengan datang ke Umbraton...",
  ui_story_5089_50891400_113_dialog_content = "Aku agak malu untuk menerimanya.",
  ui_story_5089_50891400_114_dialog_content = "Kamu selalu menjadi teman bagi Umbraton, dan juga bagi kami.",
  ui_story_5089_50891400_115_dialog_content = "Anggaplah ini sebagai lambang dari persahabatan itu.",
  ui_story_5089_50891400_116_dialog_content = "Wow! K-Kamu membuatku takut!",
  ui_story_5089_50891400_117_dialog_content = "Hahaha! Jangan lupa, tempat tujuanmu berada jauh di luar pengawasan bayangan Umbraton.",
  ui_story_5089_50891400_118_dialog_content = "Berhati-hati dalam semua yang kamu lakukan.",
  ui_story_5089_50891400_119_dialog_content = "Baiklah.",
  ui_story_5089_50891400_120_dialog_content = "... Aku serahkan sisanya padamu, Bethel.",
  ui_story_5089_50891400_121_dialog_content = "...",
  ui_story_5089_50891400_122_dialog_content = "Luke, Smokey, Genevieve, dan Naroxel semua menunggumu di belakang.",
  ui_story_5089_50891400_123_dialog_content = "Sebagai salah satu selebritas paling terkenal di Astra, mereka semua ingin mengucapkan selamat tinggal secara langsung.",
  ui_story_5089_50891400_124_dialog_content = "Oh, begitu…",
  ui_story_5089_50891400_125_dialog_content = "Tebak itu berarti aku harus memberi mereka perpisahan yang pantas.",
  ui_story_5089_50891400_126_dialog_content = "Dan kamu juga, Bethel.",
  ui_story_5089_50891400_127_dialog_content = "…!",
  ui_story_5089_50891400_128_dialog_content = "... Benarkah kamu akan pergi selama itu?",
  ui_story_5089_50891400_129_dialog_content = "Aku tidak bisa mengatakannya dengan pasti. Bahkan, aku tidak tahu apakah aku akan bisa kembali setelahnya.",
  ui_story_5089_50891400_130_dialog_content = "Tapi aku tahu bahwa aku tidak akan pernah melupakan orang-orang hebat yang pernah aku temui di sini.",
  ui_story_5089_50891400_131_dialog_content = "Jadi, jika ada kesempatan sekecil apapun untukku kembali, aku akan melakukan segala yang aku bisa untuk mewujudkannya.",
  ui_story_5089_50891400_132_dialog_content = "PlayerName…",
  ui_story_5089_50891400_133_dialog_content = "Tolong jaga dirimu.",
  ui_story_5089_50891400_134_dialog_content = "Dan jika aku menemukan novel menarik di sepanjang jalan, aku pasti akan membawanya kembali untukmu juga.",
  ui_story_5089_50891400_135_dialog_content = "Ketika hari itu tiba, kita bisa menghabiskan waktu membaca di kafe bersama setiap orang!",
  ui_story_5089_50891400_136_dialog_content = "Tapi untuk sekarang...",
  ui_story_5089_50891400_137_dialog_content = "Selamat tinggal, Bethel.",
  ui_story_5089_50891400_138_dialog_content = "Ketemu. Dia di sana.",
  ui_story_5089_50891400_139_dialog_content = "PlayerName!",
  ui_story_5089_50891400_140_dialog_content = "Selamat tinggal!",
  ui_story_5089_50891400_141_dialog_content = "Ah...",
  ui_story_5089_50891400_142_dialog_content = "Selamat tinggal—",
  ui_story_5089_50891400_143_dialog_content = "Saya harap kamu selalu memiliki musik dan harapan untuk membimbing jalanmu....",
  ui_story_5089_50891400_144_dialog_content = "... Selamat tinggal.",
  ui_story_5089_50891400_145_dialog_content = "Hah? Kamu ingin ikut juga?",
  ui_story_5089_50891400_146_dialog_content = "B-Bukan berarti aku ingin pergi bersamamu, secara khusus...",
  ui_story_5089_50891400_147_dialog_content = "Tapi menjelajahi negeri fantasi yang tidak diketahui terdengar seperti waktu yang menarik.",
  ui_story_5089_50891400_148_dialog_content = "Bahkan Antony sangat bersemangat dengan prospek itu, jadi bukankah wajar jika saya sedikit tertarik?",
  ui_story_5089_50891400_149_dialog_content = "Kamu harus mengatakan apa yang ada di pikiranmu, atau kamu mungkin akan menyesalinya nanti.",
  ui_story_5089_50891400_150_dialog_content = "...",
  ui_story_5089_50891400_151_dialog_content = "Sebagai Fosferus dari Astra, membiarkan kamu memulai perjalanan yang begitu berbahaya adalah hal yang mengkhawatirkan, setidaknya.",
  ui_story_5089_50891400_152_dialog_content = "Oh? Lalu bagaimana dengan ini?",
  ui_story_5089_50891400_153_dialog_content = "Aku akan mencari empat pejuang lagi, dan semua dari kami akan berada di bawah perintahmu!",
  ui_story_5089_50891400_154_dialog_content = "Kami akan menangani setiap elemen, dan tidak ada yang bisa menghalangiku...",
  ui_story_5089_50891400_155_dialog_content = "Meski begitu, aku telah melihat masa depanmu.",
  ui_story_5089_50891400_156_dialog_content = "Dan di tempat yang jauh itu, kamu masih memiliki kilauan yang tak terbatas.",
  ui_story_5089_50891400_157_dialog_content = "Mungkin itulah tempat pertempuran sejati Anda berada.",
  ui_story_5089_50891400_158_dialog_content = "Sebuah tempat yang penuh dengan fantasi dan realitas, di mana kamu akan berjuang untuk peningkatan semua orang.",
  ui_story_5089_50891400_159_dialog_content = "Itu adalah jalanmu sendiri.",
  ui_story_5089_50891400_160_dialog_content = "Dan meskipun hati kami dipenuhi kekhawatiran untukmu, yang bisa kami lakukan hanyalah memberikan berkat kami kepada kamu.",
  ui_story_5089_50891400_161_dialog_content = "Terima kasih. Ucapan baikmu membuatku merasa lebih tenang lebih dari yang kamu tahu.",
  ui_story_5089_50891400_162_dialog_content = "Hah? Jadi tidak akan ada lagi kesempatan bagi kita untuk naik level bersama? Saya benar-benar berharap kita bisa berpetualang lebih banyak dan mengalahkan beberapa Hantu-hantu lagi.",
  ui_story_5089_50891400_163_dialog_content = "Sejujurnya, sangat membosankan di sekitar sini.",
  ui_story_5089_50891400_164_dialog_content = "Kamu menikmati waktu di sini, ya, Freya?",
  ui_story_5089_50891400_165_dialog_content = "Saya kira bisa dibilang begitu...",
  ui_story_5089_50891400_166_dialog_content = "Aku mengunjungi kampung halamanku yang lama, memastikan bahwa \"harta karun\" masih aman, dan membeli beberapa pakaian baru untuk diriku sendiri...",
  ui_story_5089_50891400_167_dialog_content = "Sepertinya aku telah ditunjuk oleh takdir itu sendiri.",
  ui_story_5089_50891400_168_dialog_content = "Tapi, itu hampir tidak cukup untuk memuaskan saya, kamu tahu!",
  ui_story_5089_50891400_169_dialog_content = "Dan kamu hanya perlu pergi dan muncul dengan petualangan baru dan menarik, hanya untuk memberi tahu kami bahwa kami tidak bisa pergi bersamamu!",
  ui_story_5089_50891400_170_dialog_content = "Tinjuku sangat gatal ingin bertarung sampai-sampai rasanya sakit...",
  ui_story_5089_50891400_171_dialog_content = "Jadi, bagaimana kalau kita bertukar beberapa pukulan sebelum kamu pergi, Navigator?",
  ui_story_5089_50891400_172_dialog_content = "Setelah semua, mimpiku adalah—",
  ui_story_5089_50891400_173_dialog_content = "Selamat tinggal, Freya.",
  ui_story_5089_50891400_174_dialog_content = "...",
  ui_story_5089_50891400_175_dialog_content = "Melihatmu tersenyum begitu gembira dan tulus seperti ini...",
  ui_story_5089_50891400_176_dialog_content = "Itu benar-benar membuat hatiku juga merasa tenang.",
  ui_story_5089_50891400_177_dialog_content = "... Pastikan untuk memberi mereka perpisahan yang pantas, oke?",
  ui_story_5089_50891400_178_dialog_content = "Baiklah.",
  ui_story_5089_50891400_179_dialog_content = "Selamat tinggal, Queen Bethlehem.",
  ui_story_5089_50891400_180_dialog_content = "Sampai jumpa.",
  ui_story_5089_50891400_181_dialog_content = "Orang-orang yang ingin kamu lihat berada di luar istana.",
  ui_story_5089_50891400_182_dialog_content = "Pergi temui mereka, PlayerName.",
  ui_story_5089_50891400_183_dialog_content = "Selamat tinggal, Zarya.",
  ui_story_5089_50891400_184_dialog_content = "Aku masih ingin pergi.",
  ui_story_5089_50891400_185_dialog_content = "Hah?",
  ui_story_5089_50891400_186_dialog_content = "T-Tidak ada.",
  ui_story_5089_50891400_187_dialog_content = "Dadah…",
  ui_story_5089_50891400_188_dialog_content = "Oh tidak. Di sini, biarkan saya berbagi sedikit kebijaksanaan tua dengan Anda.",
  ui_story_5089_50891400_189_dialog_content = "Hei!",
  ui_story_5089_50891400_190_dialog_content = "Ini adalah kesempatan yang langka, tahu? Kamu hanya bisa menggunakan kartu gadis muda di sekitar Queen dan Dewa Gunung.",
  ui_story_5089_50891400_191_dialog_content = "Hei!!!",
  ui_story_5089_50891400_192_dialog_content = "... Jadi ini adalah perhentian terakhir.",
  ui_story_5089_50891400_193_dialog_content = "PlayerName... Lebih baik kamu kembali.",
  ui_story_5089_50891400_194_dialog_content = "Aku akan berusaha sebaik mungkin, Leyn. Bisakah kamu membantu saya menyampaikan salam perpisahan kepada yang lain?",
  ui_story_5089_50891400_195_dialog_content = "Nah, sepertinya saatnya untuk membiarkan tokoh utama naik ke panggung.",
  ui_story_5089_50891400_196_dialog_content = "Ayo pergi, semuanya.",
  ui_story_5089_50891400_197_dialog_content = "...",
  ui_story_5089_50891400_198_dialog_content = "...",
  ui_story_5089_50891400_199_dialog_content = "Apa masalahnya? Bukankah kamu datang untuk mengucapkan selamat tinggal?",
  ui_story_5089_50891400_200_dialog_content = "Aku memang melakukannya, tapi entah kenapa, aku tidak bisa menemukan kata-kata yang tepat untuk diucapkan...",
  ui_story_5089_50891400_201_dialog_content = "Kemudian biarkan saya yang berbicara!",
  ui_story_5089_50891400_202_dialog_content = "Hah? Maya?",
  ui_story_5089_50891400_203_dialog_content = "Tunggu sebentar... Achilles?! K-Kamu bukan Maya!",
  ui_story_5089_50891400_204_dialog_content = "Dia berbicara dari belakangku—",
  ui_story_5089_50891400_205_dialog_content = "Aku datang segera setelah mendengar kamu akan pergi, PlayerName!",
  ui_story_5089_50891400_206_dialog_content = "Tapi kemudian aku tersesat... Untungnya, pria besar ini cukup baik untuk membawaku ke sini!",
  ui_story_5089_50891400_207_dialog_content = "Itu menjelaskan mengapa tadi aku tidak bisa menemukanmu...",
  ui_story_5089_50891400_208_dialog_content = "Jika Jeno dan Elvis tahu kamu berlari-lari seperti ini, mereka pasti akan sangat khawatir.",
  ui_story_5089_50891400_209_dialog_content = "Ehem.",
  ui_story_5089_50891400_210_dialog_content = "S-saya maksud Elvis akan sedih.",
  ui_story_5089_50891400_211_dialog_content = "Itu Laird Elvis untukmu, pak!",
  ui_story_5089_50891400_212_dialog_content = "Uhuk, uhuk.",
  ui_story_5089_50891400_213_dialog_content = "Jadi, kamu sudah membuat keputusan?",
  ui_story_5089_50891400_214_dialog_content = "Karena begitu kamu pergi, kami tidak akan bisa membantu kamu.",
  ui_story_5089_50891400_215_dialog_content = "Aku tahu, tapi aku tidak selalu bisa mengandalkan setiap orang.",
  ui_story_5089_50891400_216_dialog_content = "...",
  ui_story_5089_50891400_217_dialog_content = "Semua telah diberikan kesempatan untuk masa depan baru...",
  ui_story_5089_50891400_218_dialog_content = "Saya berharap Anda dapat menghabiskan sisa hari-hari Anda persis seperti yang Anda inginkan.",
  ui_story_5089_50891400_219_dialog_content = "Oh, begitu... Bagaimana jika beberapa dari kita ingin menghabiskan hari-hari itu di sisimu?",
  ui_story_5089_50891400_220_dialog_content = "Eh, apa?",
  ui_story_5089_50891400_221_dialog_content = "Jika kamu mempercayakan kami dengan hak untuk memilih, maka kamu harus menghargai setiap satu dari pendapat kami.",
  ui_story_5089_50891400_222_dialog_content = "Beberapa dari kita mungkin tidak mau meninggalkanmu.",
  ui_story_5089_50891400_223_dialog_content = "Beberapa dari kita mungkin tidak ingin melepaskan petualangan yang telah kita bagikan dengan kamu.",
  ui_story_5089_50891400_224_dialog_content = "Mereka di antara kita yang merasa demikian mungkin ingin terus bertempur di sisimu.",
  ui_story_5089_50891400_225_dialog_content = "Dan mungkin saja kami cukup banyak untuk mengisi setiap kamar di Colossus milikmu.",
  ui_story_5089_50891400_226_dialog_content = "K-Kamu benar-benar berpikir begitu?",
  ui_story_5089_50891400_227_dialog_content = "Kalau begitu, aku ingin pergi juga!",
  ui_story_5089_50891400_228_dialog_content = "Dan jika tidak ada cukup ruang untukku, aku bisa meminta leluhurku untuk membawaku!",
  ui_story_5089_50891400_229_dialog_content = "Tapi bagaimana dengan akuariumnya?",
  ui_story_5089_50891400_230_dialog_content = "... Oh, tidak!!!",
  ui_story_5089_50891400_231_dialog_content = "Saya sangat khawatir tentang PlayerName dan perjalanannya sampai-sampai saya benar-benar lupa!",
  ui_story_5089_50891400_232_dialog_content = "Oh...",
  ui_story_5089_50891400_233_dialog_content = "Kamu benar-benar tidak perlu memaksakan diri, Maya.",
  ui_story_5089_50891400_234_dialog_content = "Ini bukan sesuatu yang harus diputuskan dalam waktu singkat.",
  ui_story_5089_50891400_235_dialog_content = "Kamu tidak perlu terburu-buru dalam mengambil keputusan. Tidak akan mengubah cara saya memandangmu jika kamu memutuskan untuk tidak pergi.",
  ui_story_5089_50891400_236_dialog_content = "Sungguh?",
  ui_story_5089_50891400_237_dialog_content = "Tentu.",
  ui_story_5089_50891400_238_dialog_content = "Kalau begitu... Aku akan menunggumu kembali di akuarium.",
  ui_story_5089_50891400_239_dialog_content = "Baiklah, itu kesepakatan.",
  ui_story_5089_50891400_240_dialog_content = "Bagus! Aku akan kembali dan memberi tahu Jeno dan Elvis sekarang juga!",
  ui_story_5089_50891400_241_dialog_content = "EHM—!",
  ui_story_5089_50891400_242_dialog_content = "Sepertinya Anda mulai mengerti sekarang.",
  ui_story_5089_50891400_243_dialog_content = "Mengucapkan \"selamat tinggal\" berarti kita harus berpisah untuk sementara waktu.",
  ui_story_5089_50891400_244_dialog_content = "Tapi, waktu itu tidak harus berlangsung selamanya.",
  ui_story_5089_50891400_245_dialog_content = "Dan karena kamu berharap untuk kembali suatu hari nanti, tak perlu membiarkan \"selamat tinggal\"mu begitu membebani hatimu.",
  ui_story_5089_50891400_246_dialog_content = "Kamu juga tidak seharusnya memaksa diri untuk mengucapkan kata-kata itu.",
  ui_story_5089_50891400_247_dialog_content = "Setelah semua, ceritamu masih jauh dari berakhir.",
  ui_story_5089_50891400_248_dialog_content = "Jadi, buatlah pilihanmu, dan arahkan ceritamu menuju akhir yang sempurna di hatimu.",
  ui_story_5089_50891400_249_dialog_content = "Achilles...",
  ui_story_5089_50891400_250_dialog_content = "Selamat tinggal, PlayerName.",
  ui_story_5089_50891400_251_dialog_content = "May Caelestite Terakhir terbang lebih tinggi ke langit daripada sebelumnya.",
  ui_story_5089_50891400_252_dialog_content = "...",
  ui_story_5089_50891400_253_dialog_content = "...",
  ui_story_5089_50891400_254_dialog_content = "Carleen, Aku...",
  ui_story_5089_50891400_255_dialog_content = "Soroz ada di sini.",
  ui_story_5089_50891400_256_dialog_content = "Yang berarti sudah saatnya berangkat, bukan?",
  ui_story_5089_50891400_257_dialog_content = "Ya.",
  ui_story_5089_50891400_258_dialog_content = "... Ini sama seperti saat kita pertama kali bertemu.",
  ui_story_5089_50891400_259_dialog_content = "Kamu, Soroz, Vice, dan saya, semua di Lumopolis...",
  ui_story_5089_50891400_260_dialog_content = "...",
  ui_story_5089_50891400_261_dialog_content = "Baikl—",
  ui_story_5089_50891400_262_dialog_content = "Ikut dengan kami, Carleen.",
  ui_story_5089_50891400_263_dialog_content = "Seperti bagaimana semua ini dimulai?",
  ui_story_5089_50891400_264_dialog_content = "Tepat seperti itu.",
  ui_story_5089_50891400_265_dialog_content = "...",
  ui_story_5089_50891400_266_dialog_content = "Maka ayo pergi, PlayerName!",
  ui_story_5089_50891400_267_dialog_content = "Kenapa lama sekali, PlayerName?",
  ui_story_5089_50891400_268_dialog_content = "Aku mulai merasa pusing karena mengambil alih semua tugasmu!",
  ui_story_5089_50891400_269_dialog_content = "Vice, aku...",
  ui_story_5089_50891400_270_dialog_content = "Aku tahu kamu akan datang, Carleen.",
  ui_story_5089_50891400_271_dialog_content = "Saya hanya tidak menyangka akan memakan waktu sepanjang ini.",
  ui_story_5089_50891400_272_dialog_content = "Yah, tidak sopan menyeret orang tanpa penjelasan yang layak...",
  ui_story_5089_50891400_273_dialog_content = "Maksudmu seperti apa yang telah kau lakukan padaku?",
  ui_story_5089_50891400_274_dialog_content = "Sumpah, kamu bertingkah seolah-olah kita belum pernah saling kenal.",
  ui_story_5089_50891400_275_dialog_content = "Kamu akan melukai perasaan orang jika terus bersikap seperti itu.",
  ui_story_5089_50891400_276_dialog_content = "Huh...",
  ui_story_5089_50891400_277_dialog_content = "Apakah ada hal lain yang Anda butuhkan bantuan?",
  ui_story_5089_50891400_278_dialog_content = "Tidak, kita hampir siap. Yang tersisa adalah menentukan tujuan kita.",
  ui_story_5089_50891400_279_dialog_content = "Tujuan kita... Maksudmu \"negeri fantasi\" yang sebelumnya kita temukan?",
  ui_story_5089_50891400_280_dialog_content = "Benar. Kita menuju langsung ke celah itu, tempat di mana serpihan memori Vice terbang melintasi. Itu telah memanggilku.",
  ui_story_5089_50891400_281_dialog_content = "Dan setelah membuat Migard, Victoria, Suci Perempuan, dan beberapa pihak lainnya melihat ke dalamnya, kami hampir dapat memastikan bahwa ada dunia yang sama sekali berbeda di sisi lain.",
  ui_story_5089_50891400_282_dialog_content = "Saya diberitahu bahwa dunia lain ini hampir meluap dengan N-matter.",
  ui_story_5089_50891400_283_dialog_content = "Benar, yang berarti itu harus menjadi dunia yang sangat realistis. X-matter yang membentuk dunia fantasi hampir tidak terdeteksi.",
  ui_story_5089_50891400_284_dialog_content = "Ini seharusnya tempat yang cukup aman, tetapi masih dikelilingi misteri.",
  ui_story_5089_50891400_285_dialog_content = "Itu sebabnya aku tidak ingin membiarkan orang lain datang bersamaku.",
  ui_story_5089_50891400_286_dialog_content = "Tapi... Teman-temanku... Mereka bukan hanya \"orang lain.\"",
  ui_story_5089_50891400_287_dialog_content = "Hei, itu mengingatkanku. Mengapa kita terus menyebutnya \"negeri fantasi\"?",
  ui_story_5089_50891400_288_dialog_content = "Yah... Pada akhirnya, inilah bagaimana Bethlehem menggambarkannya—",
  ui_story_5089_50891400_289_dialog_content = "Ketika dibandingkan dengan dunia kita, mungkin dunia lain itu adalah dunia nyata...",
  ui_story_5089_50891400_290_dialog_content = "Namun, ia memiliki ikatan yang menarik dan tak terpisahkan dengan Astra.",
  ui_story_5089_50891400_291_dialog_content = "Inilah alasan utama mengapa kenangan Vice mengalir ke dalamnya. Kebenaran yang kamu cari juga terletak di dunia itu, Caelestite.",
  ui_story_5089_50891400_292_dialog_content = "Mungkin, dalam kenyataan itu, ada fantasi yang sesuai.",
  ui_story_5089_50891400_293_dialog_content = "Ini mengimplikasikan bahwa bahkan di dunia \"nyata\", orang masih bisa menciptakan \"fantasi\" yang indah dari angan-angan.",
  ui_story_5089_50891400_294_dialog_content = "Kerinduan mereka pada hal yang imajiner pada akhirnya membawa kedua dunia kita untuk saling terhubung.",
  ui_story_5089_50891400_295_dialog_content = "... Tapi kita tidak pergi ke sana untuk mengakhiri fantasi-fantasi itu.",
  ui_story_5089_50891400_296_dialog_content = "Kita juga tidak hanya akan menerima dunia mereka sebagai satu-satunya \"kenyataan\".",
  ui_story_5089_50891400_297_dialog_content = "Pada akhirnya, kita hanya memulai perjalanan baru ke tempat yang tidak diketahui, mengejar mimpi indah yang juga kita rindukan.",
  ui_story_5089_50891400_298_dialog_content = "Meskipun kita hanya bisa mencapai itu di dunia nyata, saya benar-benar percaya kita akan mewujudkannya suatu hari nanti.",
  ui_story_5089_50891400_299_dialog_content = "Dan ketika waktu itu tiba, kita semua akan kembali ke Astra!",
  ui_story_5089_50891400_300_dialog_content = "Sejujurnya, aku juga tidak benar-benar mengerti cara berpikir ini.",
  ui_story_5089_50891400_301_dialog_content = "Saya hanya senang bisa bergabung dengan semua orang dalam petualangan lainnya.",
  ui_story_5089_50891400_302_dialog_content = "Iya, aku juga.",
  ui_story_5089_50891400_303_dialog_content = "Mungkin saya tidak banyak bicara, tapi jangan lupa untuk mengikutsertakan saya juga.",
  ui_story_5089_50891400_304_dialog_content = "Bagaimana kita bisa lupa?",
  ui_story_5089_50891400_305_dialog_content = "Terutama setelah betapa sulitnya menemukanmu lagi!",
  ui_story_5089_50891400_306_dialog_content = "Lalu tolong atur koordinat untuk tujuan baru kita.",
  ui_story_5089_50891400_307_dialog_content = "Vice.",
  ui_story_5089_50891400_308_dialog_content = "Yep! Ingin bergabung dengan kami kali ini, Carleen?",
  ui_story_5089_50891400_309_dialog_content = "Tapi, aku tak bisa bermain...",
  ui_story_5089_50891400_310_dialog_content = "Oh, itu tidak masalah. Hanya ada sedikit fantasi terakhir ini yang tersisa, setelah semua.",
  ui_story_5089_50891400_311_dialog_content = "Dia benar! Vice dan aku bisa membimbingmu selama kamu melakukannya dengan sepenuh hati.",
  ui_story_5089_50891400_312_dialog_content = "... Baiklah.",
  ui_story_5089_50891400_313_dialog_content = "Baiklah…",
  ui_story_5089_50891400_314_dialog_content = "Ayo kita pergi!",
  ui_story_5089_50891400_315_dialog_content = "Selamat tinggal, Astra.",
  ui_story_5089_50891400_316_dialog_content = "Selamat tinggal untuk semua orang yang telah menemani perjalanan melalui mimpi indah ini bersamaku.",
  ui_story_5089_50891400_317_dialog_content = "Sampai jumpa lagi!",
  ui_story_5089_50891400_318_dialog_content = "AKHIR",
  ui_story_5089_50891400_319_dialog_content = "Terima kasih telah bermain."
}
return config
